public static boolean isCompressed(InputStream inputStream) throws IOException {
    // Check for GZIP header
    PushbackInputStream pushbackInputStream = new PushbackInputStream(inputStream, 2);
    byte[] header = new byte[2];
    int bytesRead = pushbackInputStream.read(header);
    if (bytesRead != 2) {
        return false;
    }
    // GZIP header is 1f 8b
    if (header[0] == (byte) 0x1f && header[1] == (byte) 0x8b) {
        return true;
    }
    // Push back the read bytes so the original stream can be read from the beginning
    pushbackInputStream.unread(header);
    return false;
}

