import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

enum TaskStatus {
    RUNNING, SUCCESS, FAILURE, PAUSED
}

interface BhLeafTask<T> {
    TaskStatus execute(T context);
    void reset();
}

class BhTreeModel {
    String type;
    List<BhTreeModel> children;
    Map<String, Object> properties;

    public BhTreeModel(String type) {
        this.type = type;
        this.children = new ArrayList<>();
        this.properties = new HashMap<>();
    }

    public void addChild(BhTreeModel child) {
        children.add(child);
    }
}

class StructBHTNode<T> {
    String id;
    BhLeafTask<T> task;
    List<StructBHTNode<T>> children;
    TaskStatus status;

    public StructBHTNode(String id, BhLeafTask<T> task) {
        this.id = id;
        this.task = task;
        this.children = new ArrayList<>();
        this.status = TaskStatus.RUNNING;
    }
}

class BhTree<T> {
    private static final Logger LOGGER = Logger.getLogger(BhTree.class.getName());
    private StructBHTNode<T> rootNode;
    private Map<String, BhLeafTask<T>> tasksMap;
    private boolean pauseFlag;
    private T context;

    public BhTree(T context) {
        this.context = context;
        this.tasksMap = new ConcurrentHashMap<>();
        this.pauseFlag = false;
    }

    public void createTask(String type, BhLeafTask<T> task) {
        tasksMap.put(type, task);
    }

    public BhLeafTask<T> getLeaf(String type) {
        return tasksMap.get(type);
    }

    public void setup(BhTreeModel model) {
        rootNode = constructTreeFromModel(model);
    }

    private StructBHTNode<T> constructTreeFromModel(BhTreeModel model) {
        BhLeafTask<T> task = tasksMap.get(model.type);
        StructBHTNode<T> node = new StructBHTNode<>(model.type, task);

        for (BhTreeModel childModel : model.children) {
            StructBHTNode<T> childNode = constructTreeFromModel(childModel);
            node.children.add(childNode);
        }

        return node;
    }

    public TaskStatus step() {
        if (pauseFlag) {
            return TaskStatus.PAUSED;
        }

        return traverseAndExecute(rootNode);
    }

    private TaskStatus traverseAndExecute(StructBHTNode<T> node) {
        if (node == null) {
            return TaskStatus.FAILURE;
        }

        if (node.task == null) {
            return executeCompositeNode(node);
        }

        return executeLeafTask(node);
    }

    private TaskStatus executeLeafTask(StructBHTNode<T> node) {
        TaskStatus status = node.task.execute(context);

import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Program {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();

    System.out.println(solve(n));

    sc.close();
  }

  static String solve(int n) {
    List<Integer> elements =
        IntStream.range(1, n).filter(i -> gcd(i, n) == 1).boxed().collect(Collectors.toList());

    int product = elements.stream().mapToInt(x -> x).reduce(1, (x, y) -> (int) ((long) x * y % n));
    if (product != 1) {
      elements.remove(Integer.valueOf(product));
    }

    return String.format(
        "%d\n%s",
        elements.size(), elements.stream().map(String::valueOf).collect(Collectors.joining(" ")));
  }

  static int gcd(int x, int y) {
    return (y == 0) ? x : gcd(y, x % y);
  }
}

