public class AnimationWidget extends JFrame {
 
    private boolean right = true;
 
    public AnimationWidget() {
        initComponents();
    }
 
    private void initComponents() {
        setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
        setLayout(new java.awt.BorderLayout());
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setTitle("Animation");
        setFont(new Font("Courier", Font.PLAIN, 24));
        JLabel label = new JLabel("Hello World! ");
        label.setFont(new Font("Courier", Font.PLAIN, 24));
        add(label);
        Timer timer = new Timer(200, (e) -> {
            String text = label.getText();
            List<Character> chars = IntStream.range(0, text.length()).mapToObj(text::charAt).collect(Collectors.toList());
            Collections.rotate(chars, right? -1 : 1);
            label.setText(chars.stream().map(String::valueOf).collect(Collectors.joining()));
        });
        timer.start();
        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                right =!right;
            }
        });
    }
 
    public static void main(String[] args) {
        EventQueue.invokeLater(() -> {
            AnimationWidget frame = new AnimationWidget();
            frame.pack();
            frame.setLocationRelativeTo(null);
            frame.setVisible(true);
        });
    }
}

import java.util.Scanner;

public class PositiveNegativeAverage {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int num, countPositive = 0, countNegative = 0, sum = 0, count = 0;
        double average;

        System.out.print("Enter an integer (0 to quit): ");
        num = scanner.nextInt();

        while (num != 0) {
            if (num > 0) {
                countPositive++;
                sum += num;
            } else if (num < 0) {
                countNegative++;
                sum += num;
            }
            count++;
            System.out.print("Enter an integer (0 to quit): ");
            num = scanner.nextInt();
        }

        if (count == 0) {
            System.out.println("No numbers are entered except 0");
        } else {
            average = (double) sum / (countPositive + countNegative);
            System.out.println("The number of positives is " + countPositive);
            System.out.println("The number of negatives is " + countNegative);
            System.out.println("The total is " + sum);
            System.out.printf("The average is %.2f%n", average);
        }
    }
}

