import java.util.PriorityQueue;

public class Program {
    public static double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<int[]> priorityQueue = new PriorityQueue<>((a, b) -> ((double) (b[0] + 1 - b[1]) / (b[1] + 1) - (a[0] + 1 - a[1]) / (a[1] + 1)));
        for (int[] arr : classes) {
            priorityQueue.offer(arr);
        }
        for (int i = 0; i < extraStudents; i++) {
            int[] p = priorityQueue.poll();
            p[0]++;
            p[1]++;
            priorityQueue.offer(p);
        }
        double sum = 0;
        while (!priorityQueue.isEmpty()) {
            int[] arr = priorityQueue.poll();
            sum += (double) arr[0] / arr[1];
        }
        return sum / classes.length;
    }

    public static void main(String[] args) {
        int[][] classes = {{1,2},{3,5},{2,2}};
        int extraStudents = 2;
        System.out.println(maxAverageRatio(classes, extraStudents));
    }
}

