import com.amazonaws.transform.JsonUnmarshallerContext;
import com.amazonaws.transform.ListUnmarshaller;
import com.amazonaws.transform.SimpleTypeJsonUnmarshallers;
import com.amazonaws.transform.Unmarshaller;
import com.fasterxml.jackson.core.JsonToken;

public class DetachStaticIpResultJsonUnmarshaller implements Unmarshaller<DetachStaticIpResult, JsonUnmarshallerContext> {

    private static DetachStaticIpResultJsonUnmarshaller instance;

    public DetachStaticIpResult unmarshall(JsonUnmarshallerContext context) throws Exception {
        DetachStaticIpResult detachStaticIpResult = new DetachStaticIpResult();

        int originalDepth = context.getCurrentDepth();
        String currentParentElement = context.getCurrentParentElement();
        int targetDepth = originalDepth + 1;

        JsonToken token = context.getCurrentToken();
        if (token == null)
            token = context.nextToken();

        while (token != null) {
            if (token == JsonToken.START_OBJECT && context.isStartOfElement("operations")) {
                detachStaticIpResult.setOperations(new ListUnmarshaller<Operation, JsonUnmarshallerContext>(OperationJsonUnmarshaller.getInstance())
                        .unmarshall(context));
            } else if (token == JsonToken.END_OBJECT && context.getCurrentDepth() < originalDepth) {
                return detachStaticIpResult;
            }

            token = context.nextToken();
        }

        return detachStaticIpResult;
    }

    public static DetachStaticIpResultJsonUnmarshaller getInstance() {
        if (instance == null)
            instance = new DetachStaticIpResultJsonUnmarshaller();
        return instance;
    }
}

import org.intermine.api.InterMineAPI;
import org.intermine.bio.web.export.GFF3Exporter;
import org.intermine.bio.web.logic.SequenceFeatureExportUtil;
import org.intermine.pathquery.PathQuery;
import org.intermine.web.context.InterMineContext;
import org.intermine.webservice.server.exceptions.BadRequestException;
import org.intermine.webservice.server.query.result.PathQueryBuilder;

import java.util.List;
import java.util.Properties;

public class GFFQueryService extends BioQueryService {

    private static final String GFF3_CONTENT_TYPE = "text/x-gff3";
    private static final String GFF3_FILE_SUFFIX = ".gff3";
    private static final String SO_CLASS_NAMES = "SequenceFeature";

    public GFFQueryService(InterMineAPI im) {
        super(im);
    }

    @Override
    protected String getSuffix() {
        return GFF3_FILE_SUFFIX;
    }

    @Override
    protected String getContentType() {
        return GFF3_CONTENT_TYPE;
    }

    @Override
    protected GFF3Exporter getExporter(PathQuery pq) {
        Properties webProperties = InterMineContext.getWebProperties();
        String sourceName = webProperties.getProperty("project.title");

        List<String> organisms = SequenceFeatureExportUtil.getOrganismIds(pq);
        List<Integer> indexes = SequenceFeatureExportUtil.getIndexes(pq);
        List<String> viewColumns = pq.getView();

        GFF3Exporter exporter = new GFF3Exporter();
        exporter.setSourceName(sourceName);
        exporter.setOrganisms(organisms);
        exporter.setIndexes(indexes);
        exporter.setViewColumns(viewColumns);

        return exporter;
    }

    @Override
    protected void checkPathQuery(PathQuery pq) throws BadRequestException {
        if (!SequenceFeatureExportUtil.isSequenceFeatureQuery(pq)) {
            throw new BadRequestException("Query is not compatible with sequence feature data.");
        }
    }

    @Override
    protected List<String> removeFirstItemInPaths(List<String> paths) {
        return SequenceFeatureExportUtil.removeFirstItemInPaths(paths);
    }

    @Override
    protected String getSoClassNames() {
        return SO_CLASS_NAMES;
    }
}

import java.io.Serializable;
import java.util.Objects;
import org.alfresco.service.cmr.transfer.TransferTarget;
import org.alfresco.service.cmr.transfer.TransferVersion;

/**
 * Data structure to represent an ongoing transfer operation.
 *
 */
public class Transfer implements Serializable {
  private static final long serialVersionUID = 1L;

  private String transferId;
  private TransferTarget transferTarget;
  private TransferVersion toVersion;

  public Transfer() {}

  /** @return String the unique id for this transfer */
  public String getTransferId() {
    return transferId;
  }

  /** @param transferId the id of this transfer to set */
  public void setTransferId(String transferId) {
    this.transferId = transferId;
  }

  @Override
  public int hashCode() {
    int hash = 7;
    hash = 61 * hash + (this.transferId != null ? this.transferId.hashCode() : 0);
    return hash;
  }

  @Override
  public boolean equals(Object obj) {
    if (obj == null) {
      return false;
    }
    if (getClass() != obj.getClass()) {
      return false;
    }
    final Transfer other = (Transfer) obj;
    if ((this.transferId == null)
        ? (other.transferId != null)
        : !this.transferId.equals(other.transferId)) {
      return false;
    }
    return true;
  }

  public TransferTarget getTransferTarget() {
    return transferTarget;
  }

  public void setTransferTarget(TransferTarget transferTarget) {
    this.transferTarget = transferTarget;
  }

  public TransferVersion getToVersion() {
    return toVersion;
  }

  public void setToVersion(TransferVersion toVersion) {
    this.toVersion = toVersion;
  }

  @Override
  public String toString() {
    return "Transfer{"
        + "transferId="
        + transferId
        + ", transferTarget="
        + transferTarget
        + ", toVersion="
        + toVersion
        + '}';
  }
}

private MethodSource<JavaClassSource> inspectSuperClasses(UIExecutionContext context, final String type,
            String name,
            String[] paramTypes)
   {
      Project project = getSelectedProject(context);
      JavaSource<?> clazz = sourceForName(project, type);
      if (clazz instanceof JavaClass)
      {
         JavaClassSource source = Roaster.parse(JavaClassSource.class, clazz.toString());
         MethodSource<JavaClassSource> superClassMethod = source.getMethod(name, paramTypes);
         if (superClassMethod != null)
         {
            return superClassMethod;
         }
         if (!source.getSuperType().equals("java.lang.Object"))
         {
            return inspectSuperClasses(context, source.getSuperType(), name, paramTypes);
         }
      }
      return null;
   }

