public class ValidateProjectIT
{
    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    @Rule
    public TemporaryDigdagServer server = TemporaryDigdagServer.builder()
            .build();

    private Path config;
    private Path projectDir;

    @Before
    public void setUp()
            throws Exception
    {
        projectDir = folder.getRoot().toPath().resolve("foobar");
        config = folder.newFile().toPath();
    }

    @Test
    public void uploadInvalidTaskProject()
            throws Exception
    {
        // Create new project
        CommandStatus initStatus = main("init",
                "-c", config.toString(),
                projectDir.toString());
        assertThat(initStatus.code(), is(0));

        copyResource("acceptance/error_task/invalid_at_group.dig", projectDir.resolve("invalid_at_group.dig"));

        // Push the project
        CommandStatus pushStatus = main(
                "push",
                "--project", projectDir.toString(),
                "foobar",
                "-c", config.toString(),
                "-e", server.endpoint());
        assertThat(pushStatus.code(), is(1));
        assertThat(pushStatus.errUtf8(), containsString("A task can't have more than one operator"));
    }

    @Test
    public void uploadInvalidScheduleProject()
            throws Exception
    {
        // Create new project
        CommandStatus initStatus = main("init",
                "-c", config.toString(),
                projectDir.toString());
        assertThat(initStatus.code(), is(0));

        copyResource("acceptance/schedule/invalid_schedule.dig", projectDir.resolve("invalid_schedule.dig"));

        // Push the project
        CommandStatus pushStatus = main(
                "push",
                "--project", projectDir.toString(),
                "foobar",
                "-c", config.toString(),
                "-e", server.endpoint());
        assertThat(pushStatus.code(), is(1));
        assertThat(pushStatus.errUtf8(), containsString("scheduler requires mm:ss format"));
    }
}

@SuppressWarnings("rawtypes")
    public static final SerIterator grid(
            final Grid<?> grid, final Class<?> declaredType,
            final Class<?> valueType, final List<Class<?>> valueTypeTypes) {
        return new SerIterator() {
            private final Iterator it = grid.cells().iterator();
            private Grid.Cell current;
            @Override
            public String metaTypeName() {
                return "Grid";
            }
            @Override
            public boolean metaTypeRequired() {
                return Grid.class.isAssignableFrom(declaredType) == false;
            }
            @Override
            public SerCategory category() {
                return SerCategory.GRID;
            }
            @Override
            public int dimensionSize(int dimension) {
                return (dimension == 0 ? grid.rowCount() : grid.columnCount());
            }
            @Override
            public int size() {
                return grid.size();
            }
            @Override
            public boolean hasNext() {
                return it.hasNext();
            }
            @Override
            public void next() {
                current = (Grid.Cell) it.next();
            }
            @Override
            public Class<?> keyType() {
                return Integer.class;
            }
            @Override
            public Object key() {
                return current.getRow();
            }
            @Override
            public Class<?> columnType() {
                return Integer.class;
            }
            @Override
            public Object column() {
                return current.getColumn();
            }
            @Override
            public Class<?> valueType() {
                return valueType;
            }
            @Override
            public Object value() {
                return current.getValue();
            }
            @Override
            public Object value(int row, int column) {
                return grid.get(row, column);
            }
            @Override
            public List<Class<?>> valueTypeTypes() {
                return valueTypeTypes;
            }
        };
    }

// 20210212 Java programming solution

public class NthRoot {

   public static double nthRoot(double n, double A) {
      double p = 1e-9;
      double x0 = A / n;

      while (true) {
         double x1 = ( (n-1.0) * x0 + A / Math.pow(x0, n-1.0) ) / n;
         if (Math.abs(x1-x0) < Math.abs(x0*p)) return x1;
         x0 = x1;
      }
   }

   public static void main(String[] args) {
      System.out.println(nthRoot(3., 8. ));
   }
}

import org.omg.CORBA.Any;
import org.omg.CORBA.TypeCode;
import org.omg.CORBA.portable.InputStream;
import org.omg.CORBA.portable.OutputStream;
import org.omg.CORBA.ORB;
import org.omg.CORBA.StructMember;

public abstract class ReceivedObjectHelper {
  private static String _id = "IDL:ReceivedObject:1.0";
  private static TypeCode _tc = null;

  private ReceivedObjectHelper() {}

  public static void insert(Any a, ReceivedObject that) {
    OutputStream out = a.create_output_stream();
    a.type(type());
    write(out, that);
    a.read_value(out.create_input_stream(), type());
  }

  public static ReceivedObject extract(Any a) {
    return read(a.create_input_stream());
  }

  public static synchronized TypeCode type() {
    if (_tc == null) {
      StructMember[] _members = new StructMember[5];
      TypeCode _type = null;
      _type = ORB.init().create_string_tc(0);
      _members[0] = new StructMember("by", _type, null);
      _type = ORB.init().create_string_tc(0);
      _members[1] = new StructMember("from", _type, null);
      _type = DateTimeHelper.type();
      _members[2] = new StructMember("date", _type, null);
      _type = ORB.init().create_string_tc(0);
      _members[3] = new StructMember("id", _type, null);
      _type = ORB.init().create_string_tc(0);
      _members[4] = new StructMember("via", _type, null);
      _tc = ORB.init().create_struct_tc(id(), "ReceivedObject", _members);
    }
    return _tc;
  }

  public static String id() {
    return _id;
  }

  public static ReceivedObject read(InputStream istream) {
    ReceivedObject value = new ReceivedObject();
    value.by = istream.read_string();
    value.from = istream.read_string();
    value.date = DateTimeHelper.read(istream);
    value.id = istream.read_string();
    value.via = istream.read_string();
    return value;
  }

  public static void write(OutputStream ostream, ReceivedObject value) {
    ostream.write_string(value.by);
    ostream.write_string(value.from);
    DateTimeHelper.write(ostream, value.date);
    ostream.write_string(value.id);
    ostream.write_string(value.via);
  }
}

