import java.math.BigDecimal;

public class ApproximateE {
    public static void main(String[] args) {
        int[] iValues = {10000, 20000, 30000, 40000, 50000, 60000, 70000, 80000, 90000, 100000};
        for (int i : iValues) {
            BigDecimal sum = BigDecimal.ONE;
            BigDecimal factorial = BigDecimal.ONE;
            for (int j = 1; j <= i; j++) {
                factorial = factorial.multiply(BigDecimal.valueOf(j));
                sum = sum.add(BigDecimal.ONE.divide(factorial));
            }
            System.out.println("e for i = " + i + " is: " + sum);
        }
    }
}

public String restoreString(String s, int[] indices) {
    char[] shuffled = new char[s.length()];
    for (int i = 0; i < s.length(); i++) {
        shuffled[indices[i]] = s.charAt(i);
    }
    return new String(shuffled);
}

public class VersCheck {
    public static void main(String[] args) {
        String vers = System.getProperty("java.version");
        vers = vers.substring(0,vers.indexOf('.')) + "." +  //some String fiddling to get the version number into a usable form
            vers.substring(vers.indexOf('.')+1,vers.lastIndexOf('.'));
        if(Double.parseDouble(vers) >= 1.5){
            System.out.println("YAY!");
        }else{
