import java.util.Scanner;

public class Generator {
    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.print("Enter the amount you would like to invest each month: ");

        double investment = input.nextDouble();

        System.out.print("Enter the annual interest rate(e.g. 5,10,20): ");

        double interestRate = input.nextDouble();

        interestRate = interestRate / 100;

        System.out.println("Enter the number of months: ");

        int numberOfMonths = input.nextInt();

        double total = 0;

        for (int i = 1; i <= numberOfMonths; i++) {

            total = (investment + total) * (1 + (interestRate / 12));

        }

        System.out.println("After the " + numberOfMonths + "th month, " + "the account value is " + total);

    }

}

import org.jf.dexlib2.DexPool;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import java.util.LinkedHashMap;
import java.util.Map;

public class StringPool extends DexPool<String> {
    private final Map<String, Integer> stringIndices;
    private int currentIndex;

    public StringPool() {
        this.stringIndices = new LinkedHashMap<>();
        this.currentIndex = 0;
    }

    public void intern(@Nonnull String string) {
        if (string == null) {
            throw new NullPointerException("Cannot intern null string.");
        }
        if (!stringIndices.containsKey(string)) {
            stringIndices.put(string, currentIndex++);
        }
    }

    public void internNullable(@Nullable String string) {
        if (string != null) {
            intern(string);
        }
    }

    public int getItemIndex(@Nonnull String string) {
        Integer index = stringIndices.get(string);
        if (index == null) {
            throw new IllegalArgumentException("String '" + string + "' not found in pool.");
        }
        return index;
    }

    public boolean hasJumboIndexes() {
        return currentIndex > 0xFFFF;
    }

    public int size() {
        return currentIndex;
    }

    @Override
    public void addItem(@Nonnull String item) {
        intern(item);
    }

    @Override
    public int getItemCount() {
        return currentIndex;
    }

    @Override
    public int getItemIndexOrAdd(@Nonnull String item) {
        Integer index = stringIndices.get(item);
        if (index == null) {
            index = currentIndex++;
            stringIndices.put(item, index);
        }
        return index;
    }

    public void reset() {
        stringIndices.clear();
        currentIndex = 0;
    }

    public boolean contains(@Nonnull String string) {
        return stringIndices.containsKey(string);
    }

    public Iterable<String> getStringsInOrder() {
        return stringIndices.keySet();
    }

    public void validate() throws IllegalStateException {
        if (stringIndices.size() != currentIndex) {
            throw new IllegalStateException("String pool index mismatch.");
        }
    }
}

