import java.util.Arrays;

import java.util.Scanner;

public class LexString {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int testcase = scanner.nextInt();

        while (testcase-- > 0) {

            int n = scanner.nextInt();

            int x = scanner.nextInt();

            int y = scanner.nextInt();

            char[] ch1 = scanner.next().toCharArray();

            char[] ch2 = scanner.next().toCharArray();

            Arrays.sort(ch1);

            Arrays.sort(ch2);

            int i = 0, j = 0, count1 = 0, count2 = 0;

            StringBuilder res = new StringBuilder();

            while (i < n && j < x) {

                if (ch1[i] < ch2[j] && count1 != y || count2 == y) {

                    res.append(ch1[i++]);

                    count1++;

                    count2 = 0;

                } else {

                    res.append(ch2[j++]);

                    count2++;

                    count1 = 0;

                }

            }

            System.out.println(res.toString());

        }

    }

}

import org.apache.arrow.vector.*;
import org.apache.flink.util.Preconditions;

import java.sql.Time;
import java.util.TimeZone;

class TimeFieldReader extends ArrowFieldReader {

    private static final TimeZone LOCAL_TZ = TimeZone.getDefault();
    private final ValueVector valueVector;

    public TimeFieldReader(ValueVector valueVector) {
        super(valueVector);
        this.valueVector = valueVector;
    }

    @Override
    public ValueVector getValueVector() {
        return valueVector;
    }

    @Override
    public boolean isNull(int pos) {
        return valueVector.isNull(pos);
    }

    @Override
    public Time read(int pos) {
        if (isNull(pos)) {
            return null;
        } else {
            long timeMilli;
            if (valueVector instanceof TimeSecVector) {
                timeMilli = ((TimeSecVector) valueVector).get(pos) * 1000L;
            } else if (valueVector instanceof TimeMilliVector) {
                timeMilli = ((TimeMilliVector) valueVector).get(pos);
            } else if (valueVector instanceof TimeMicroVector) {
                timeMilli = ((TimeMicroVector) valueVector).get(pos) / 1000;
            } else if (valueVector instanceof TimeNanoVector) {
                timeMilli = ((TimeNanoVector) valueVector).get(pos) / 1000000;
            } else {
                throw new UnsupportedOperationException(
                        "Unsupported time vector type: " + valueVector.getClass().getName());
            }
           return new Time(timeMilli - LOCAL_TZ.getOffset(timeMilli));
        }
    }
}

import java.io.StringReader;
import java.util.List;
import java.util.stream.Collectors;
import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamConstants;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamReader;
 
public class Validator {
    public static void main(String[] args) throws XMLStreamException {
        String document = "<Students>\n" +
                "  <Student Name=\"April\" Gender=\"F\" DateOfBirth=\"1989-01-02\" />\n" +
                "  <Student Name=\"Bob\" Gender=\"M\"  DateOfBirth=\"1990-03-04\" />\n" +
                "  <Student Name=\"Chad\" Gender=\"M\"  DateOfBirth=\"1991-05-06\" />\n" +
                "  <Student Name=\"Dave\" Gender=\"M\"  DateOfBirth=\"1992-07-08\">\n" +
                "    <Pet Type=\"dog\" Name=\"Rover\" />\n" +
                "  </Student>\n" +
                "  <Student DateOfBirth=\"1993-09-10\" Gender=\"F\" Name=\"&#x00C9;mily\" />\n" +
                "</Students>";
 
        XMLInputFactory factory = XMLInputFactory.newFactory();
        XMLStreamReader parser = factory.createXMLStreamReader(new StringReader(document));
 
        String tagName = "Student";
        String attributeName = "Name";
 
        while (parser.hasNext()) {
            int event = parser.next();
            if (event == XMLStreamConstants.START_ELEMENT && parser.getLocalName().equals(tagName)) {
                List<String> attributes = parser.getAttributeNames().asIterator().asLongStream()
                       .mapToObj(parser::getAttributeName)
                       .map(String::toString)
                       .collect(Collectors.toList());
                if (attributes.contains(attributeName)) {
                    System.out.println(parser.getAttributeValue(attributeName));
                }
            }
        }
    }
}

import java.util.Scanner;

public class PayrollStatement {
   public static void main(String[] args) {
      Scanner input = new Scanner(System.in);

      // Prompt user to input employee information
      System.out.print("Enter employee's name: ");
      String name = input.nextLine();

      System.out.print("Enter number of hours worked in a week: ");
      double hoursWorked = input.nextDouble();

      System.out.print("Enter hourly pay rate: ");
      double hourlyPayRate = input.nextDouble();

      System.out.print("Enter federal tax withholding rate (%): ");
      double federalTaxRate = input.nextDouble();

      System.out.print("Enter state tax withholding rate (%): ");
      double stateTaxRate = input.nextDouble();

      // Calculate gross pay, federal withholding, state withholding, and net pay
      double grossPay = hoursWorked * hourlyPayRate;
      double federalWithholding = grossPay * (federalTaxRate / 100);
      double stateWithholding = grossPay * (stateTaxRate / 100);
      double totalDeduction = federalWithholding + stateWithholding;
      double netPay = grossPay - totalDeduction;

      // Print payroll statement
      System.out.println("Employee Name: " + name);
      System.out.println("Hours Worked: " + hoursWorked);
      System.out.println("Pay Rate: $" + hourlyPayRate);
      System.out.println("Gross Pay: $" + grossPay);
      System.out.println("Deductions:");
      System.out.printf("\tFederal Withholding (%.1f%%): $%.2f\n", federalTaxRate, federalWithholding);
      System.out.printf("\tState Withholding (%.1f%%): $%.2f\n", stateTaxRate, stateWithholding);
      System.out.printf("\tTotal Deduction: $%.2f\n", totalDeduction);
      System.out.println("Net Pay: $" + netPay);
   }
}

