import java.util.ArrayList;
import java.util.List;
 
public class Fibonacci {
 
    public static void main(String[] args) {
        printNumberSequence("Fibonacci", getNnacciNumbers(2, 10));
        printNumberSequence("Lucas", getLucasNumbers(10));
        printNumberSequence("Tribonacci", getNnacciNumbers(3, 10));
        printNumberSequence("Tetranacci", getNnacciNumbers(4, 10));
    }
 
    private static List<Long> getLucasNumbers(int length) {
        List<Long> seedSequence = new ArrayList<Long>();
        seedSequence.add(2L);
        seedSequence.add(1L);
        return getFibLikeSequence(seedSequence, length);
    }
 
    private static List<Long> getNnacciNumbers(int seedLength, int length) {
        return getFibLikeSequence(getNacciSeed(seedLength), length);
    }
 
    private static List<Long> getNacciSeed(int seedLength) {
        List<Long> seedSquence = new ArrayList<Long>();
        seedSquence.add(1L);
 
        for (int i = 0; i < seedLength - 1; i++) {
            seedSquence.add((long) Math.pow(2, i));
        }
 
        return seedSquence;
    }
 
    private static List<Long> getFibLikeSequence(List<Long> seedSequence, int length) {
        List<Long> sequence = new ArrayList<Long>();
 
        int count = seedSequence.size();
 
        if (length <= count) {
            for (int i = 0; i < length; i++) {
                sequence.add(seedSequence.get(i));
            }
        } else {
            sequence = seedSequence;
 
