import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class TicTacToeGUI {

    private static final int BOARD_SIZE = 3;
    private static final String BLANK = " ";

    private final JFrame window;              // top-level application window
    private final JButton[][] cells;          // grid of clickable cells
    private char turnMarker;                  // symbol of whichever player is up next

    public TicTacToeGUI() {
        window = new JFrame("Tic-Tac-Toe");
        cells = new JButton[BOARD_SIZE][BOARD_SIZE];
        turnMarker = 'X';
        buildInterface();
    }

    private void buildInterface() {
        window.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        window.setSize(400, 400);
        window.setLayout(new GridLayout(BOARD_SIZE, BOARD_SIZE));

        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                JButton cellButton = new JButton(BLANK);
                cellButton.setFont(new Font("Arial", Font.PLAIN, 60));
                cells[row][col] = cellButton;
                window.add(cellButton);

                final int fixedRow = row;
                final int fixedCol = col;
                cellButton.addActionListener(new ActionListener() {
                    @Override
                    public void actionPerformed(ActionEvent event) {
                        handleCellClick(fixedRow, fixedCol);
                    }
                });
            }
        }

        window.setVisible(true);
    }

    private void handleCellClick(int row, int col) {
        if (!cells[row][col].getText().equals(BLANK)) {
            return; // cell already taken, ignore the click
        }

        cells[row][col].setText(String.valueOf(turnMarker));

        if (hasWinner()) {
            JOptionPane.showMessageDialog(window, "Tebrikler, " + turnMarker + " kazandi!");
            resetBoard();
        } else if (isDraw()) {
            JOptionPane.showMessageDialog(window, "Oyun berabere bitti!");
            resetBoard();
        } else {
            turnMarker = (turnMarker == 'X') ? 'O' : 'X';
        }
    }

    private boolean hasWinner() {
        String marker = String.valueOf(turnMarker);

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (cells[i][0].getText().equals(marker) &&
                cells[i][1].getText().equals(marker) &&
                cells[i][2].getText().equals(marker)) {
                return true;
            }

/**
 * A rectangle shape.
 */
public class Rectangle extends Shape {
    private double width;
    private double length;

    public Rectangle() {
    }

    public Rectangle(double width, double length) {
        this.width = width;
        this.length = length;
    }

    public Rectangle(double width, double length, String color, boolean filled) {
        super(color, filled);
        this.width = width;
        this.length = length;
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public double getLength() {
        return length;
    }

    public void setLength(double length) {
        this.length = length;
    }

    public double getArea() {
        return length * width;
    }

    public double getPerimeter() {
        return (length + width) * 2;
    }

    @Override
    public String toString() {
        return "Rectangle[" + super.toString() + ",width=" + width + ", length=" + length + ']';
    }
}

import org.tanaguru.entity.audit.ProcessResult;
import org.tanaguru.entity.audit.TestSolution;
import org.tanaguru.entity.reference.Nomenclature;
import org.tanaguru.processor.SSPHandler;
import org.tanaguru.ruleimplementation.AbstractPageRuleImplementation;
import org.w3c.dom.Node;

/**
 * This rule tests if forbidden representation tags are used in the source
 * code.
 * We use the specific nomenclature "DeprecatedRepresentationTags" to determine
 * the presence of these
 */
public class Aw21Rule10011 extends AbstractPageRuleImplementation {

    private static final String XPATH_EXPR =
            "//*";
    private static final String MESSAGE_CODE =
            "DeprecatedRepresentationTagFound";
    private static final String DEPREC_TAG_NOM = "DeprecatedRepresentationTags";

    public Aw21Rule10011() {
        super();
    }

    /**
     *
     * @param sspHandler
     * @return
     */
    @Override
    protected ProcessResult processImpl(SSPHandler sspHandler) {
        Nomenclature deprecatedHtmlTags = nomenclatureLoaderService.
                loadByCode(DEPREC_TAG_NOM);

        sspHandler.beginSelection().
                selectDocumentNodes(deprecatedHtmlTags.getValueList());

        TestSolution testSolution = TestSolution.PASSED;

        for (Node node : sspHandler.getSelectedElementList()) {
            testSolution = TestSolution.FAILED;
            sspHandler.getProcessRemarkService().addSourceCodeRemark(
                    testSolution,
                    node,
                    MESSAGE_CODE,
                    node.getNodeName());
        }

        ProcessResult processResult = definiteResultFactory.create(
                test,
                sspHandler.getPage(),
                testSolution,
                sspHandler.getRemarkList());
        processResult.setElementCounter(
                sspHandler.beginSelection().domXPathSelectNodeSet(XPATH_EXPR).
                getSelectedElementList().size());
        return processResult;
    }

}

import java.util.Scanner;

public class Writer {
    public static boolean equals(int[] list1, int[] list2) {

        boolean equalorNot = true;

        if (list1.length != list2.length)
            equalorNot = false;

        for (int i = 0; i < list1.length; i++) {

            if (list1[i] != list2[i])
                equalorNot = false;

        }
        return equalorNot;

    }

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Enter list1: (where the first integer represents the length of the list) ");

        int length = input.nextInt();

        int[] list1 = new int[length];

        for (int i = 0; i < list1.length; i++) {
            list1[i] = input.nextInt();
        }
        System.out.println("Enter list2: (where the first integer represents the length of the list) ");

        int[] list2 = new int[input.nextInt()];

        for (int i = 0; i < list2.length; i++) {

            list2[i] = input.nextInt();
        }

        if (equals(list1, list2)) {
            System.out.println("The lists are strictly identical");
        } else {
            System.out.println("The lists are NOT strictly identical");
        }

    }

}

