  public static int solve(int N, List<List<Integer>> lines) {
    // TODO Auto-generated method stub
    for (int i = 0; i < lines.size(); i++) {
      boolean removed = lines.get(i).isEmpty();

      if (!removed)
        continue;

      String initialString = convert(lines.get(i), 0, lines.size(),
      1, lines.get(0).get(0), lines.get(0).get(1)); // format : Used In: (1st x1)   (2nd x2)   (3rd x3)   (4th x4)
      Integer[] processes =Integer.parseInt(initialString).toArray();

      for (int j = 0; j < processes.length; j++) {
        if (processes[j] == 0) // grid with no rectangle at all
          continue;

        if (N % 2 == 0) // checking rectangle size is odd to ensure only one rectangle will be removed

          if (processes[j] / 2 == 1) // case: when the rectangle contains only one cell.
            removed = true; // remove this rectangle

        else
          if (processes[j] / 2 == processes[j] % 2 && processes[j] % 2 == 1) // case: all cells are same
            removed = true; // remove this rectangle
      }

      if (!removed)
        return Integer.MIN_VALUE; // need to remove to make largest rectangle area
    }

    int largest = Integer.MIN_VALUE;

    for (int i = 0; i < lines.size(); i++) {
      if (!lines.get(i).isEmpty())
        largest = findMaxSquare(lines.get(i));

      System.out.println(largest);
    }

    return largest;
}

