import net.lsrp.wolfie.Game;

public class Screen {

    public int width, height;
    public int[] pixels;

    public Screen(int width, int height) {
        this.width = width;
        this.height = height;
        pixels = new int[width*height];

        for(int i = 0; i < pixels.length; i++) {
            pixels[i] = 0xFFFFAAFF;
        }
    }

    public void clear() {
        for(int i = 0; i < pixels.length; i++) {
            pixels[i] = 0;
        }
    }

    public void renderSprite(int xp, int yp, Sprite sprite) {

        for(int y = 0; y < sprite.SIZE; y++) {
            int ya = y + yp;
            for(int x = 0; x < sprite.SIZE; x++) {
                int xa = x + xp;

                if(xa < -sprite.SIZE || xa >= width || ya < 0 || ya >= height) break;
                if(xa < 0) xa = 0;

                int col = sprite.pixels[x + y * sprite.SIZE];
                if(col != 0xFFFF00FF)
                    pixels[xa + ya * width] = col;
            }
        }
    }

    public void renderPlatform(int xp, int yp, int wp, Sprite sprite, Sprite sprite_l, Sprite sprite_r) {

        for(int y = 0; y < sprite_l.SIZE; y++) {
            int ya = y + yp;
            ya+=10;
            for(int x = 0; x < sprite_l.SIZE; x++) {
                int xa = x + xp;

                if(xa < -sprite_l.SIZE || xa >= width || ya < 0 || ya >= height) break;
                if(xa < 0) xa = 0;

                int col = sprite_l.pixels[x + y * sprite_l.SIZE];
                if(col != 0xFFFF00FF)
                    pixels[xa + ya * width] = col;
            }
        }

        for(int w = 1; w < wp - 1; w++) {
            for(int y = 0; y < sprite.SIZE; y++) {
                int ya = y + yp;
                ya+=10;
                for(int x = 0; x < sprite.SIZE; x++) {
                    int xa = x + xp + (w << 4);

                    if(xa < -sprite.SIZE || xa >= width || ya < 0 || ya >= height) break;
                    if(xa < 0) xa = 0;

                    int col = sprite.pixels[x + y * sprite.SIZE];
                    if(col != 0xFFFF00FF)
                        pixels[xa + ya * width] = col;
                }
            }
        }

        for(int y = 0; y < sprite_r.SIZE; y++) {
            int ya = y + yp;
            ya+=10;
            for(int x = 0; x < sprite_r.SIZE; x++) {
                int xa = x + xp + (wp-1 << 4);

                if(xa < -sprite_r.SIZE || xa >= width || ya < 0 || ya >= height) break;
                if(xa < 0) xa = 0;

                int col = sprite_r.pixels[x + y * sprite_r.SIZE];

import java.util.ArrayList;
import java.util.StringTokenizer;

/**
 *
 */
public class Exchange extends ArrayList<String>{
    public Exchange() {
        this.add("USD;VND;17000");
        this.add("EUR;USD;1.2");
        this.add("USD;IDN;15789");
        this.add("USD;EUR;0.83");
        this.add("CAD;IDN;16869");
    }

    public double convert(Rate rate) {
        for (String rateString : this) {
            StringTokenizer tokenizer = new StringTokenizer(rateString, ";");
            String tokenizer_code1 = tokenizer.nextToken();
            String tokenizer_code2 = tokenizer.nextToken();
            Double tokenizer_amount = Double.parseDouble(tokenizer.nextToken());
            if (rate.getCODE1().toLowerCase().equals(tokenizer_code1.toLowerCase()) && rate.getCODE2().toLowerCase().equals(tokenizer_code2.toLowerCase())) {
                return tokenizer_amount * rate.getRate();
            }
        }
        System.out.println("Can not found code!!!!");
        return rate.getRate();
    }
}

