import com.googlecode.pongo.runtime.*;
import com.googlecode.pongo.runtime.querying.*;

public class DatetimeMeasurement extends Measurement {

    public static StringQueryProducer URI = new StringQueryProducer("uri");
    public static LongQueryProducer VALUE = new LongQueryProducer("value");
    public static IntegerQueryProducer TIME_ZONE_HOURS = new IntegerQueryProducer("timezoneHours");
    public static IntegerQueryProducer TIME_ZONE_MINS = new IntegerQueryProducer("timezoneMins");

    public static String VALUE_KEY = "value";
    public static String TIME_ZONE_HOURS_KEY = "timezoneHours";
    public static String TIME_ZONE_MINS_KEY = "timezoneMins";

    public DatetimeMeasurement() {
        super();
        dbObject.add(new StringPongoProperty(VALUE_KEY, dbObject, VALUE));
        dbObject.add(new StringPongoProperty(TIME_ZONE_HOURS_KEY, dbObject, TIME_ZONE_HOURS));
        dbObject.add(new StringPongoProperty(TIME_ZONE_MINS_KEY, dbObject, TIME_ZONE_MINS));
    }

    public long getValue() {
        return parseLong(dbObject.get(VALUE_KEY));
    }

    public int getTimezoneHours() {
        return parseInteger(dbObject.get(TIME_ZONE_HOURS_KEY));
    }

    public int getTimezoneMinutes() {
        return parseInteger(dbObject.get(TIME_ZONE_MINS_KEY));
    }

    public void setValue(long value, int timezoneHours, int timezoneMins) {
        dbObject.put(VALUE_KEY, value + "");
        dbObject.put(TIME_ZONE_HOURS_KEY, timezoneHours + "");
        dbObject.put(TIME_ZONE_MINS_KEY, timezoneMins + "");
        notifyChanged();
    }

    protected Integer parseInteger(Object o) {
        if (o == null) {
            return 0;
        }
        else if (o instanceof Integer) {
            return (Integer) o;
        }
        return 0;
    }

    protected Long parseLong(Object o) {
        if (o == null) {
            return 0L;
        }
        else if (o instanceof Long) {
            return (Long) o;
        }
        return 0L;
    }
}

class Converter {
    private static final int[][] moves = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    private int m, n;
    private long k;

    public int shortestPath(int[][] grid, int k) {
        m = grid.length; n = grid[0].length; this.k = k + 1L;
        int res = 0;

        // BFS
        HashMap<Long, Integer> isVisit = new HashMap<>();
        Queue<Long> queue = new LinkedList<>();

        // Initial Start Point
        queue.add(serialize(0, 0, k));
        queue.add(null);
        isVisit.put(serialize(0, 0, 0), k);

        // Start BFS
        while(queue.size() > 1) {
            Long tmp = queue.poll();
            if (tmp == null) {
                res += 1;
                queue.add(null);
            } else {
                int[] p = deserialize(tmp);
                if (p[0] == m - 1 && p[1] == n - 1) {
                    return res;
                }
                for (int[] mv : moves) {
                    int xt = p[0] + mv[0], yt = p[1] + mv[1];
                    if (xt >= 0 && xt < m && yt >= 0 && yt < n && p[2] >= grid[xt][yt] && isVisit.getOrDefault(serialize(xt, yt, 0), -1) < p[2]) {
                        isVisit.put(serialize(xt, yt, 0), p[2]);
                        queue.add(serialize(xt, yt, p[2] - grid[xt][yt]));
                    }
                }
            }
        }
        return -1;
    }

    private long serialize(int x, int y, int r) {
        return r + y * k + x * n * k;
    }

    private int[] deserialize(long key) {
        int[] res = new int[3];
        res[2] = (int) (key % k);
        res[1] = (int) (key / k % n);
        res[0] = (int) (key / k / n);
        return res;
    }
}

