public class GetPixelColor {
 
    public static void main(String[] args) throws IOException {
        URL url = new URL("http://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Red_Icon.svg/200px-Red_Icon.svg.png");
        BufferedImage image = ImageIO.read(url);
        int[] pixels = new int[1];
        PixelGrabber pg = new PixelGrabber(image, 0, 0, 1, 1, pixels, 0, 1);
        try {
            pg.grabPixels();
