public class BenchmarkTest16422 extends HttpServlet {

    private static final long serialVersionUID = 1L;

    @Override
    public void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        doPost(request, response);
    }

    @Override
    public void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        response.setContentType("text/html;charset=UTF-8");

        String param = request.getHeader("BenchmarkTest16422");
        if (param == null) param = "";

        String bar = doSomething(param);

        String osName = System.getProperty("os.name");
        if (osName.indexOf("Windows") != -1) {
            bar = bar.replaceAll(" ", "\\ ");
        }

        String[] argsEnv = { "foo=bar" };
        Runtime r = Runtime.getRuntime();
        try {
            Process p = r.exec(new String[] { "echo", bar }, argsEnv);
            Utils.printOSCommandResults(p, response);
        } catch (IOException e) {
            System.out.println("Problem executing cmdi - TestCase");
            throw new ServletException(e);
        }
    }

    private String doSomething(String param) throws ServletException, IOException {
        String bar;
        String a1 = "";
        String a2 = "";
        String[] parts = param.split("&");
        if (parts.length >= 2) {
            a1 = parts[0];
            a2 = parts[1];
        }
        bar = a1 + " " + a2;
        return bar;
    }

    public static class Utils {
        public static void printOSCommandResults(Process p, HttpServletResponse response) throws IOException {
            InputStream inputStream = p.getInputStream();
            Scanner scanner = new Scanner(inputStream).useDelimiter("\\A");
            String output = scanner.hasNext() ? scanner.next() : "";
            response.getWriter().println(output);
            scanner.close();
        }
    }
}

