import java.util.*;
import java.io.*;
public class Ari7897E {

    public static void main(String[] args) throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int t = Integer.parseInt(br.readLine());
        while(t-->0)
        {
            String str = br.readLine();
            int[][] moves = new int[str.length()][3];
            HashSet<String> set = new HashSet<String>();
            long time = 0;
            moves[0][0] = 0;
            moves[0][1] = 0;
            moves[0][2] = 0;
            set.add(moves[0][0]+ "," + moves[0][1]);
            for(int i=1;i<str.length();i++)
            {
                String c = String.valueOf(str.charAt(i-1));
                if(c.equals("N"))
                {
                    moves[i][0] = moves[i-1][0];
                    moves[i][1] = moves[i-1][1]+1;
                    moves[i][2] = 0;
                }
                else if(c.equals('S'))
                {
                    moves[i][0] = moves[i-1][0];
                    moves[i][1] = moves[i-1][1]-1;
                    moves[i][2] = 0;
                }

                if(c.equals('E'))
                {
                    moves[i][0] = moves[i-1][0]+1;
                    moves[i][1] = moves[i-1][1];
                    moves[i][2] = 0;
                }

                if(c.equals('W'))
                {
                    moves[i][0] = moves[i-1][0]-1;
                    moves[i][1] = moves[i-1][1];
                    moves[i][2] = 0;
                }

                if(set.contains((moves[i][0])+", "+(moves[i][1])))
                    time++;
                else
                    time+=5;
                set.add((moves[i][0])+", "+(moves[i][1]));
            }
            pw.println(time);
        }

        pw.close();

    }

}
