import java.io.File;
import java.util.List;

public interface ClassLoaderScope {

    /**
     * Returns the classloader for this scope.  Used for loading classes that are visible only to this scope.
     */
    ClassLoader getLocalClassLoader();

    /**
     * Returns the classloader for this scope.  Used for loading classes that are visible to child scopes.
     */
    ClassLoader getExportClassLoader();

    /**
     * Returns the parent scope of this scope.
     */
    ClassLoaderScope getParent();

    /**
     * Adds the given classpath to this scope, making it visible only to this scope.
     */
    void local(List<File> classpath);

    /**
     * Adds the given classpath to this scope, making it visible to this scope and all child scopes.
     */
    void export(List<File> classpath);

    /**
     * Creates a child scope of this scope.
     */
    ClassLoaderScope createChild();

    /**
     * Locks this scope to prevent further modifications.  Allows for optimization of the classloader structure.
     */
    void lock();

    /**
     * Returns true if this scope has been locked.
     */
    boolean isLocked();

    /**
     * Adds the given classpath to this scope, making it visible only to this scope.
     */
    default void local(File... classpath) {
        throw new UnsupportedOperationException();
    }

    /**
     * Adds the given classpath to this scope, making it visible to this scope and all child scopes.
     */
    default void export(File... classpath) {
        throw new UnsupportedOperationException();
    }
}

