import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

public class ContinuedFraction {
    public static double calc(Function<Integer, int[]> f, int n) {
        double temp = 0.0;
        for (int ni = n; ni >= 1; ni--) {
            int[] p = f.apply(ni);
            temp = p[1] / (p[0] + temp);
        }
        return f.apply(0)[0] + temp;
    }

    public static void main(String[] args) {
        List<Function<Integer, int[]>> fList = new ArrayList<>();
        fList.add(n -> n > 0? new int[] { 2, 1 } : new int[] { 1, 1 });
        fList.add(n -> n > 0? new int[] { n, n > 1? (n - 1) : 1 } : new int[] { 2, 1 });
        fList.add(n -> n > 0? new int[] { 6, (int) Math.pow(2 * n - 1, 2) } : new int[] { 3, 1 });

        for (var f : fList) {
            System.out.println(calc(f, 200));
        }
    }
}

import java.lang.Math;
import java.lang.System;
 
public class Zodiac {
    private static final String[] animals = { "Rat","Ox","Tiger","Rabbit","Dragon","Snake","Horse","Goat","Monkey","Rooster","Dog","Pig" };
    private static final String[] elements = { "Wood","Fire","Earth","Metal","Water" };
 
    private static String getElement(int year) {
        int element = (int)Math.floor((year - 4) % 10 / 2);
        return elements[element];
    }
 
    private static String getAnimal(int year) {
        return animals[(year - 4) % 12];
    }
 
    private static String getYY(int year) {
        if (year % 2 == 0) {
            return "yang";
        } else {
            return "yin";
        }
    }
 
    public static void main(String[] args) {
        int[] years = { 1935, 1938, 1968, 1972, 1976, 2017 };
        int i;
 
        //the zodiac cycle didnt start until 4 CE, so years <4 shouldnt be valid
        for (i = 0; i < 6; ++i) {
            int year = years[i];
            System.out.printf("%d is the year of the %s %s (%s).\n", year, getElement(year), getAnimal(year), getYY(year));
        }
    }
}

