class Student {
    public int oddEvenJumps(int[] A) {
        int res =1;
        for(int i = 0; i < A.length-1; i++){
            int index = 1;
            int next = i;
            while(true){
                if(index%2==0){
                    next = largest(A,next);
                } else{
                    next = smallest(A,next);
                }
                if(next==-1)break;
                if(next==A.length-1){
                    res++;
                    break;
                }
                index++;
            }
        }
        return res;
    }

    public static int smallest(int[] A, int start){
        int smallest = Integer.MAX_VALUE;
        int res = -1;
        int curr = A[start];
        for(int i = start+1; i<A.length; i++){
            if(A[i]>=curr && A[i]<smallest){
                smallest = A[i];
                res = i;
            }
        }
        return res;
    }

    public static int largest(int[] A, int start){
        int largest = Integer.MIN_VALUE;
        int res = -1;
        int curr = A[start];
        for(int i = start+1; i<A.length; i++){
            if(A[i]<=curr && A[i]>largest){
                largest = A[i];
                res = i;
            }
        }
        return res;
    }
}

