protected OutputsModel toOutputsModel(Output[] outputs, KnowledgeNamespace knowledgeNamespace) {
    // Initialize the OutputsModel
    OutputsModel outputsModel = new OutputsModel();

    // Iterate over each output in the outputs array
    for (Output output : outputs) {
        // Create a new MappingModel for each output
        MappingModel mappingModel = new MappingModel();

        // Set the properties of the MappingModel based on the output
        mappingModel.setOutput(output);
        mappingModel.setKnowledgeNamespace(knowledgeNamespace);

        // Add the MappingModel to the OutputsModel
        outputsModel.addMapping(mappingModel);
    }

    // Return the populated OutputsModel
    return outputsModel;
}

