import java.util.Scanner;

public class Processor {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt();
            int[] arr = new int[n];
            for (int j = 0; j < n; j++) {
                arr[j] = scanner.nextInt();
            }
            int l = 0, r = n - 1;
            while (l < n - 1 && arr[l] == Math.max(arr[l], arr[l + 1])) l++;
            while (r > 1 && arr[r] == Math.max(arr[r], arr[r - 1])) r--;
            boolean found = false;
            while (l < r) {
                if (arr[l] != Math.min(arr[l], arr[l + 1]) && arr[l] != arr[0] && arr[l] != Math.max(arr[l], arr[l + 1]) && arr[r] != Math.min(arr[l], arr[l + 1]) && arr[r] != arr[n - 1]) {
                    found = true;
                    System.out.println(l + 1 + " " + (l + r) / 2 + 1);
                    break;
                }
                while (l < r && arr[l] == Math.max(arr[l], arr[l + 1])) l++;
                while (l < r && arr[r] == Math.max(arr[r], arr[r - 1])) r--;
            }
            if (!found) System.out.println(-1);
        }
    }
}

