public final class CodeChef {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        long t = sc.nextLong();

        while (t-- > 0) {

            long x = sc.nextLong();

            long y = sc.nextLong();

            long a = sc.nextLong();

            long b = sc.nextLong();

            b = Math.min(b, a + a);

            long res = Math.abs(x - y) * a + Math.min(x, y) * b;

            System.out.println(res);

        }

    }

}

