public class StripControlCharacters {

  private static final String SRC = "déjà vu" + // precomposed unicode
      "\n\000\037 \041\176\177\200\377\n" + // various boundary cases
      "as⃝df̅"; // unicode combining characters

  public static void main(String[] args) {
    System.out.println("source text:");
    System.out.println(SRC);
    System.out.println("\nas bytes, stripped of control codes:");
    System.out.println(stripCtlFromBytes(SRC));
    System.out.println("\nas bytes, stripped of control codes and extended characters:");
    System.out.println(stripCtlAndExtFromBytes(SRC));
    System.out.println("\nas UTF-8, stripped of control codes:");
    System.out.println(stripCtlFromUTF8(SRC));
    System.out.println("\nas UTF-8, stripped of control codes and extended characters:");
    System.out.println(stripCtlAndExtFromUTF8(SRC));
    System.out.println("\nas decomposed and stripped Unicode:");
    System.out.println(stripCtlAndExtFromUnicode(SRC));
  }

  private static String stripCtlFromBytes(String str) {
    byte[] b = new byte[str.length()];
    int bl = 0;
    for (int i = 0; i < str.length(); i++) {
      char c = str.charAt(i);
      if (c >= 32 && c!= 127) {
        b[bl] = (byte) c;
        bl++;
      }
    }
    return new String(b, 0, bl);
  }

  private static String stripCtlAndExtFromBytes(String str) {
    byte[] b = new byte[str.length()];
    int bl = 0;
    for (int i = 0; i < str.length(); i++) {
      char c = str.charAt(i);
      if (c >= 32 && c < 127) {
        b[bl] = (byte) c;
        bl++;
      }
    }
    return new String(b, 0, bl);
  }

  private static String stripCtlFromUTF8(String str) {
    return StringUtils.remove(str, new IntPredicate() {
      @Override
      public boolean test(int value) {
        return value >= 32 && value!= 127;
      }
    });
  }

  private static String stripCtlAndExtFromUTF8(String str) {
    return StringUtils.remove(str, new IntPredicate() {
      @Override
      public boolean test(int value) {
        return value >= 32 && value < 127;
      }
    });
  }

