public void addPropertiesFileToWar(ZipOutputStream outZip, ZipEntry cadmiumPropertiesEntry, Properties cadmiumProps, List<String> newWarNames) throws IOException {
    ByteArrayOutputStream propsOut = new ByteArrayOutputStream();
    cadmiumProps.store(propsOut, null);

    String comment = newWarNames.isEmpty() ? "" : "Properties for war: " + newWarNames.get(0);

    cadmiumPropertiesEntry.setComment(comment);
    outZip.putNextEntry(cadmiumPropertiesEntry);
    outZip.write(propsOut.toByteArray());
    outZip.closeEntry();
}

