class GraduateFactory {
    public static Graduate forBinary(Path filePath) throws IOException {
        List<Double> calibrationData = new ArrayList<>();
        byte[] bytes = Files.readAllBytes(filePath);
        for (int i = 0; i < bytes.length; i += 8) {
            calibrationData.add(Double.longBitsToDouble(bytesToLong(bytes, i)));
        }
        return new BinaryGraduate(calibrationData);
    }

    public static Graduate forTextFile(Path filePath) throws IOException {
        List<Double> calibrationData = new ArrayList<>();
        Files.readAllLines(filePath).forEach(line -> {
            try {
                calibrationData.add(NumberFormat.getInstance().parse(line).doubleValue());
            } catch (ParseException e) {
                e.printStackTrace();
            }
        });
        return new TextGraduate(calibrationData);
    }

    private static long bytesToLong(byte[] bytes, int start) {
        long value = 0;
        for (int i = 0; i < 8; i++) {
            value |= ((long) (bytes[start + i] & 0xff)) << (8 * i);
        }
        return value;
    }
}

