        // nothing to do
    }

    @Override
    public String getUsageName() {
        return "load";
    }

    @Override
    public String getUsageDescription() {
        return "Load a bibliography from a file";
    }

    /**
     * Specifies the file to load
     * @param files the file
     */
    @OptionDesc(longName = "file", shortName = "f", argumentType = ArgumentType.STRING,
            description = "bibliography file to load", argumentName = "FILE")
    public void setFiles(List<String> files) {
        this.files = files;
    }

    @Override
    public int checkArguments(String[] args) {
        if (files == null || files.isEmpty()) {
            usage();
            return 1;
        }
        if (files.size() > 1) {
            error("too many arguments");
            usage();
            return 1;
        }
        return 0;
    }

    @Override
    public int doRun(String[] args, InputReader in, Terminal terminal) throws IOException {
        String file = files.get(0);
        CSLToolContext ctx = CSLToolContext.current();
        ShellContext shellCtx = (ShellContext)ctx.getShellContext();

        File f = new File(file);
        if (!f.exists()) {
            error("file `" + file + "' does not exist");
            return 1;
        }
        if (!f.canRead()) {
            error("file `" + file + "' cannot be read");
            return 1;
        }

        try {
            ctx.getBibliographyFileReader().readBibliography(f);
        } catch (IOException e) {
            error("could not read bibliography file `" + file + "': " + e.getMessage());
            return 1;
        }

        shellCtx.setLastLoadedBibliographyFile(file);
        return 0;
    }
}

