            int startDay = (firstDay + getNumDaysInYear(month, year)) % 7;
            int day = 1;
            for (int i = 0; i < startDay; i++) {
                System.out.print("    ");
            }
            for (int i = startDay; i < 7; i++) {
                System.out.printf("%3d ", day);
                day++;
            }
            System.out.println();

            while (day <= numDays) {
                for (int i = 0; i < 7 && day <= numDays; i++) {
