import java.util.*;

public class Utils {
    public static void main(String[] args) {
        System.out.println(findMinMax(2, 7, 1, 3)); // Expected output: 4
        System.out.println(findMinMax(3, 5, 2, 1)); // Expected output: 3
        System.out.println(findMinMax(2, 4, 8, 2)); // Expected output: 15
    }

    public static int findMinMax(int divisor1, int divisor2, int uniqueCnt1, int uniqueCnt2) {
        // Find the least common multiple (LCM) of the two divisors
        int lcm = (divisor1 * divisor2) / gcd(divisor1, divisor2);
        int maxPossible = 0;
        if (divisor1 == 1) {
            maxPossible = divisor2 * divisor2; // Initialize the maximum possible value for arr2
        } else if (divisor2 == 1) {
            maxPossible = divisor1 * divisor1; // Initialize the maximum possible value for arr1
        } else {
            maxPossible = divisor1 * divisor2 * divisor1 * divisor2; // Initialize the maximum possible value for both arr1 and arr2
        }

        if (uniqueCnt1 + uniqueCnt2 <= 1) {
            return maxPossible;
        }

        int minValueFound = maxPossible;
        int maxValueFound = lcm;
        for (int i = maxValueFound - 1; i >= maxPossible; i--) {
            if (i % lcm == 0) {
                continue;
            }
            int uniqueIn1 = (i - 1) / divisor1;
            int uniqueIn2 = (i - 1) / divisor2;
            if (uniqueIn1 == uniqueCnt1 && uniqueIn2 == uniqueCnt2) {
                minValueFound = Math.min(minValueFound, i);
                break;
            }
        }
        return minValueFound;
    }

    public static long gcd(long a, long b) {
        while (b > 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
public class Mult{
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int first = sc.nextInt();
    int second = sc.nextInt();
 
    if(first < 0){
        first = -first;
        second = -second;
    }
 
    Map<Integer, Integer> columns = new HashMap<Integer, Integer>();
        columns.put(first, second);
    int sum = isEven(first)? 0 : second;
    do{
      first = halveInt(first);
      second = doubleInt(second);
      columns.put(first, second);
      if(!isEven(first)){
          sum += second;
      }
    }while(first > 1);
 
    System.out.println(sum);
  }
 
  public static int doubleInt(int doubleMe){
    return doubleMe << 1; //shift left
  }
 
  public static int halveInt(int halveMe){
    return halveMe >>> 1; //shift right
  }
 
  public static boolean isEven(int num){
    return (num & 1) == 0;
  }
}

