class Stack {
    public int[] distributeCandies(int candies, int num_people) {
        if(num_people <= 0) {
            return new int[0];
        }

        int[] res = new int[num_people];
        int index =  1;
        while(candies > 0) {
            if(candies > index) {
                res[(index-1)%num_people] += index;
                candies -= index;
            } else {
                res[(index-1)%num_people] += candies;
                candies = 0;
            }

            ++index;
        }

        return res;
    }
}

public class BreakOrnegi {

    // For dongusunde break kullanimi
    public static void forDongusuOrnegi() {
        System.out.println("For dongusu ornegi:");
        for (int i = 1; i <= 10; i++) {
            if (i == 5) { // Deger 5 oldugunda dongu kirilir
                System.out.println("Dongu 5 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + i);
        }
    }

    // While dongusunde break kullanimi
    public static void whileDongusuOrnegi() {
        System.out.println("\nWhile dongusu ornegi:");
        int i = 1;
        while (i <= 10) {
            if (i == 7) { // Deger 7 oldugunda dongu kirilir
                System.out.println("Dongu 7 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + i);
            i++;
        }
    }

    // Ic ice dongulerde break kullanimi
    public static void icIceDongulerOrnegi() {
        System.out.println("\nIc ice donguler ornegi:");
        for (int i = 1; i <= 4; i++) {
            for (int j = 1; j <= 4; j++) {
                if (j == 2) { // Ic dongu belirli bir sartta kirilir
                    System.out.println("Ic dongu j = 2 de kirildi (i = " + i + ")");
                    break;
                }
                System.out.println("i: " + i + ", j: " + j);
            }
        }
    }

    public static void main(String[] args) {
        // For dongusu ornegi
        forDongusuOrnegi();

        // While dongusu ornegi
        whileDongusuOrnegi();

        // Ic ice donguler ornegi
        icIceDongulerOrnegi();
    }
}

public class Rational extends Number implements Comparable<Rational> {
    // Data fields for numerator = r[0],  and denominator = r[1]
    private long[] r = new long[2];

    public Rational() {
        this(0, 1);
    }

    public Rational(long numerator, long denominator) {
        long gcd = gcd(numerator, denominator);
        long n = ((denominator > 0) ? 1 : -1) * numerator / gcd;
        long d = Math.abs(denominator) / gcd;
        r[0] = n;
        r[1] = d;
    }

    private static long gcd(long n, long d) {
        long n1 = Math.abs(n);
        long n2 = Math.abs(d);
        int gcd = 1;
        for (int k = 1; k <= n1 && k <= n2; k++) {
            if (n1 % k == 0 && n2 % k == 0)
                gcd = k;
        }
        return gcd;

    }

    public long getNumerator() {
        return r[0];
    }

    public long getDenominator() {
        return r[1];
    }

    public Rational add(Rational secondRational) {
        long n = r[0] * secondRational.getDenominator() +
                r[1] * secondRational.getNumerator();
        long d = r[1] * secondRational.getDenominator();
        return new Rational(n, d);
    }

    public Rational subtract(Rational secondRational) {
        long n = r[0] * secondRational.getDenominator()
                - r[1] * secondRational.getNumerator();
        long d = r[1] * secondRational.getDenominator();
        return new Rational(n, d);
    }

    public Rational multiply(Rational secondRational) {
        long n = r[0] * secondRational.getNumerator();
        long d = r[1] * secondRational.getDenominator();
        return new Rational(n, d);
    }

    public Rational divide(Rational secondRational) {
        long n = r[0] * secondRational.getDenominator();
        long d = r[1] * secondRational.getNumerator();
        return new Rational(n, d);
    }

    @Override
    public String toString() {
        if (r[1] == 1)
            return r[0] + "";
        else
            return r[0] + "/" + r[1];
    }

    @Override // Override the equals method in the Object class
    public boolean equals(Object other) {
        if ((this.subtract((Rational) (other))).getNumerator() == 0)
            return true;
        else
            return false;
    }

