class Game {
    public int projectionArea(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] colMax = new int[n];
        int res = 0;
        for(int i = 0; i < m; i++){
            int rowMax = 0;
            for(int j = 0; j < n; j++){
                colMax[j] = Math.max(colMax[j], grid[i][j]);
                rowMax = Math.max(rowMax, grid[i][j]);
                if(j == n-1) res += rowMax;
                if(grid[i][j] > 0) res++;
            }
        }

        for(int i = 0; i < n; i++) res += colMax[i];

        return res;
    }
}

