public class Levenshtein {
    public static int levenshtein(String a, String b) {
        int t[] = new int[b.length() + 1];
        int u[] = new int[b.length() + 1];
        int i, j, m = a.length(), n = b.length();
        if (m == 0) {
            return n;
        }
        if (n == 0) {
            return m;
        }
        for (j = 0; j <= n; j++) {
            t[j] = j;
        }
        for (i = 1; i <= m; i++) {
            for (u[0] = i, j = 1; j <= n; j++) {
                u[j] = a.charAt(i - 1) == b.charAt(j - 1)? t[j - 1] : Math.min(t[j - 1], t[j], u[j - 1]) + 1;
            }
            t = u;
        }
        return u[n];
    }

    public static void main(String[] args) {
        String[] a = {"", "yo", "", "yo", "tier", "saturday", "mist", "tier", "kitten", "stop", "rosettacode", "mississippi"};
        String[] b = {"", "", "yo", "yo", "tor", "sunday", "dist", "tor", "sitting", "tops", "raisethysword", "swiss miss"};
        int[] t = {0, 2, 2, 0, 2, 3, 1, 2, 3, 2, 8, 8};
        for (int i = 0; i < a.length; i++) {
            int d = levenshtein(a[i], b[i]);
            if (d!= t[i]) {
                System.out.println("levenstein(\"" + a[i] + "\",\"" + b[i] + "\") was " + d + " should be " + t[i]);
            }
        }
    }
}

class Game {
    public int[] findThePrefixCommonArray(int[] A, int[] B) {
        int a = 0;
        int n = A.length;
        int[] map  = new int[n];
        int[] ans = new int[n];
        for(int i=0;i<n;i++){
            map[A[i]-1]++;
            map[B[i]-1]++;
            if (A[i] == B[i]) {
                ans[i] = ++a;
                continue;
            }
            if(map[A[i]-1] == 2) {
                ans[i] = ++a;
            }
            if(map[B[i]-1] == 2){
                ans[i] = ++a;
            }
            ans[i] = a;
        }
        return ans;
    }
}

