public class IndexMergeUtil {

    private static final String SITE_NAME_PARAMETER = "siteName";
    private static final String REDUCE_BOOST_PARAMETER = "reduceBoost";
    private static final String MERGE_INDEX_SERVLET_PATH = "/mergeIndexServlet";

    private WebConfig webConfig;
    private DeploymentConfig config;

    public IndexMergeUtil() {
        webConfig = KarniyarikRepository.getInstance().getConfig().getWebConfig();
        config = KarniyarikRepository.getInstance().getConfig().getDeploymentConfig();
    }

    public void callMergeSiteIndex(String siteName) {
        callMergeSiteIndex(siteName, false);
    }

    public void callMergeSiteIndex(String siteName, boolean reduceBoost) {
        if (StringUtils.isBlank(siteName)) {
            throw new IllegalArgumentException("Site name cannot be null or empty.");
        }

        String servletURL = constructServletURL(siteName, reduceBoost);
        URLConnection connection = null;
        InputStream is = null;

        try {
            URL url = new URL(servletURL);
            connection = url.openConnection();
            connection.connect();
            is = connection.getInputStream();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (is != null) is.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public void callReduceSiteIndex(String siteName) {
        callMergeSiteIndex(siteName, true);
    }

    private String constructServletURL(String siteName, boolean reduceBoost) {
        StringBuilder urlBuilder = new StringBuilder();
        urlBuilder.append(webConfig.getMasterWebURL())
                  .append(MERGE_INDEX_SERVLET_PATH)
                  .append("?")
                  .append(SITE_NAME_PARAMETER)
                  .append("=")
                  .append(siteName);

        if (reduceBoost) {
            urlBuilder.append("&")
                      .append(REDUCE_BOOST_PARAMETER)
                      .append("=true");
        }

        return urlBuilder.toString();
    }

    public static void main(String[] args) {
        IndexMergeUtil util = new IndexMergeUtil();
        String[] sites = {"site1", "site2", "site3"};

import java.util.Scanner;

public class WindChill {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Get input from user
        System.out.print("Enter the temperature (in degrees Fahrenheit): ");
        double ta = scanner.nextDouble();

        if (ta < -58 || ta > 41) { // check if ta is within valid range
            System.out.println("Temperature must be between -58 ºF and 41ºF.");
            System.exit(1);
        }

        System.out.print("Enter the wind speed (in miles per hour): ");
        double v = scanner.nextDouble();

        if (v < 2) { // check if v is within valid range
            System.out.println("Wind speed must be greater than or equal to 2 mph.");
            System.exit(1);
        }

        // Calculate wind-chill temperature
        double twc = 35.74 + 0.6215*ta - 35.75*Math.pow(v, 0.16) + 0.4275*ta*Math.pow(v, 0.16);

        // Output result
        System.out.printf("The wind-chill temperature is: %.2f ºF", twc);
    }
}

import org.eclipse.jface.action.Action;
import org.eclipse.jface.action.GroupMarker;
import org.eclipse.jface.action.ICoolBarManager;
import org.eclipse.jface.action.IMenuManager;
import org.eclipse.jface.action.IToolBarManager;
import org.eclipse.jface.action.MenuManager;
import org.eclipse.jface.action.Separator;
import org.eclipse.jface.action.ToolBarContributionItem;
import org.eclipse.jface.action.ToolBarManager;
import org.eclipse.swt.SWT;
import org.eclipse.ui.IWorkbenchActionConstants;
import org.eclipse.ui.IWorkbenchWindow;
import org.eclipse.ui.actions.ActionFactory;
import org.eclipse.ui.actions.ActionFactory.IWorkbenchAction;
import org.eclipse.ui.application.ActionBarAdvisor;
import org.eclipse.ui.application.IActionBarConfigurer;

/**
 * An action bar advisor is responsible for creating, adding, and disposing of the
 * actions added to a workbench window. Each window will be populated with
 * new actions.
 */
public class ApplicationActionBarAdvisor extends ActionBarAdvisor {

    // Actions - important to allocate these only in makeActions, and then use them
    // in the fill methods.  This ensures that the actions aren't recreated
    // when fillActionBars is called with FILL_PROXY.
    private IWorkbenchAction exitAction;
    private IWorkbenchAction newWindowAction;

    public ApplicationActionBarAdvisor(IActionBarConfigurer configurer) {
        super(configurer);
    }

    protected void makeActions(final IWorkbenchWindow window) {
        // Creates the actions and registers them.
        // Registering is needed to ensure that key bindings work.
        // The corresponding commands keybindings are defined in the plugin.xml file.
        // Registering also provides automatic disposal of the actions when
        // the window is closed.

        exitAction = ActionFactory.QUIT.create(window);
        register(exitAction);

        newWindowAction = ActionFactory.OPEN_NEW_WINDOW.create(window);
        register(newWindowAction);
    }

    protected void fillMenuBar(IMenuManager menuBar) {
        MenuManager fileMenu = new MenuManager("&File", IWorkbenchActionConstants.M_FILE);

        menuBar.add(fileMenu);

        // File
        fileMenu.add(newWindowAction);
        fileMenu.add(new Separator());
        fileMenu.add(exitAction);
    }

    protected void fillCoolBar(ICoolBarManager coolBar) {
        IToolBarManager toolbar = new ToolBarManager(SWT.FLAT | SWT.RIGHT);
        coolBar.add(new ToolBarContributionItem(toolbar, "main"));
    }
}

