/**
 * Swing chat window that speaks the tiny line-based protocol expected
 * by ChatServer: SUBMITNAME / NAMEACCEPTED / MESSAGE.
 */
public class ChatClient {

    private static final int SERVER_PORT = 59001;

    private final String host;
    private Scanner serverIn;
    private PrintWriter serverOut;

    private final JFrame window = new JFrame("Chatter");
    private final JTextField composeField = new JTextField(50);
    private final JTextArea history = new JTextArea(16, 50);

    public ChatClient(String host) {
        this.host = host;

        composeField.setEditable(false);
        history.setEditable(false);
        window.getContentPane().add(composeField, BorderLayout.SOUTH);
        window.getContentPane().add(new JScrollPane(history), BorderLayout.CENTER);
        window.pack();

        composeField.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent event) {
                serverOut.println(composeField.getText());
                composeField.setText("");
            }
        });
    }

    private String promptForScreenName() {
        return JOptionPane.showInputDialog(window, "Choose a screen name:", "Screen name selection",
                JOptionPane.PLAIN_MESSAGE);
    }

    private void connectAndListen() throws IOException {
        try (var socket = new Socket(host, SERVER_PORT)) {
            serverIn = new Scanner(socket.getInputStream());
            serverOut = new PrintWriter(socket.getOutputStream(), true);

            while (serverIn.hasNextLine()) {
                String line = serverIn.nextLine();
                if (line.startsWith("SUBMITNAME")) {
                    serverOut.println(promptForScreenName());
                } else if (line.startsWith("NAMEACCEPTED")) {
                    window.setTitle("Chatter - " + line.substring(13));
                    composeField.setEditable(true);
                } else if (line.startsWith("MESSAGE")) {
                    history.append(line.substring(8) + "\n");
                }
            }
        } finally {
            window.setVisible(false);
            window.dispose();
        }
    }

@SuppressWarnings("fallthrough")
  public static int murmur2(final byte[] data) {
    int length = data.length;
    int seed = 0x9747b28c;

    final int m = 0x5bd1e995;
    final int r = 24;

    int h = seed ^ length;
    int length4 = length / 4;

    for (int i = 0; i < length4; i++) {
      final int i4 = i * 4;
      int k = (data[i4 + 0] & 0xff) + ((data[i4 + 1] & 0xff) << 8) + ((data[i4 + 2] & 0xff) << 16) + ((data[i4 + 3] & 0xff) << 24);
      k *= m;
      k ^= k >>> r;
      k *= m;
      h *= m;
      h ^= k;
    }

    switch (length % 4) {

      case 3:
        h ^= (data[(length & ~3) + 2] & 0xff) << 16;

      case 2:
        h ^= (data[(length & ~3) + 1] & 0xff) << 8;

      case 1:
        h ^= data[length & ~3] & 0xff;
        h *= m;
      default:
    }
    h ^= h >>> 13;
    h *= m;
    h ^= h >>> 15;
    return h;
  }

