import java.util.Arrays;

public class JumboExtraCheese {
    void minPerimeter(int[] a, int[] b) {
        int n = a.length;
        Arrays.sort(a);
        Arrays.sort(b);

        int perimeter = 0;
        int current_x, current_y;
        for (int i = 0; i < n; i++) {
            current_x = a[i];    // start from the left edge of the current slice
            current_y = b[i];    // start from the top edge of the current slice

            for (int j = i; j < n; j++) {
                if (a[j] <= current_x || b[j] <= current_y) break; // if a neighboring slice intersects current slice, update current_x and current_y

                perimeter += 4;    // add the four sides that are not closes to any other edge
                current_x = Math.min(a[j], current_x);    // update current_x based on the minimum x-coordinate of neighboring slice
                current_y = Math.min(b[j], current_y);    // update current_y based on the minimum y-coordinate of neighboring slice
                i = j;    // start from the next slice because overlapping slices have already been considered
            }
        }

        System.out.println(perimeter);
    }
}

