import java.util.*;

public class SimilarStringPairs {
    static Map<String, Integer> charCountMap = new HashMap<>();
    static long count;
    public static void main(String[] args) {
        String[] words = {"aba","aabb","abcd","bac","aabc"};
        charCountMap.put("a", 0);
        charCountMap.put("b", 1);
        charCountMap.put("c", 2);
        count = 0;
        for (int i = 0; i < words.length; i++) {
            char[] charr = words[i].toCharArray();
            Arrays.sort(charr);
            String sortedString = new String(charr);
            if(charCountMap.containsKey(sortedString)){
                count+=charCountMap.get(sortedString);
                charCountMap.put(sortedString, charCountMap.get(sortedString)+1);
            }
        }

        System.out.println(count-words.length);
    }

    private static void helper(String word, Map<String, Integer> map) {
        if(map.containsKey(word)){
            map.put(word, map.get(word)+1);
        }else{
            map.put(word, 1);
        }
    }
}

