public String getPairedEndReadNamePrefix(String fastq) {
    if (fastq == null) {
        throw new IllegalArgumentException("Fastq cannot be null");
    }
    String[] tokens = fastq.split("\\s+");
    if (tokens.length < 2) {
        throw new IllegalArgumentException("Invalid fastq format");
    }
    return tokens[0].substring(0, tokens[0].length() - 2);
}

import java.util.regex.Pattern;
import java.util.regex.Matcher;
 
public class Library {
    private static final Pattern reg = Pattern.compile("([0-9]+(\\.[0-9]+)?)");
    private static String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }
    private static String commatize(String s, int startIndex, int period, String sep) {
        if (startIndex < 0 || startIndex >= s.length() || period < 1 || sep.equals("")) {
            return s;
        }
        Matcher m = reg.matcher(s.substring(startIndex));
        if (!m.find()) {
            return s;
        }
        String[] splits = m.group().split("\\.");
        String ip = splits[0];
        if (ip.length() > period) {
            String pi = reverse(ip);
            for (int i = (pi.length() - 1) / period * period; i >= period; i -= period) {
                pi = pi.substring(0, i) + sep + pi.substring(i);
            }
            ip = reverse(pi);
        }
        if (m.group().contains(".")) {
            String dp = splits[1];
            if (dp.length() > period) {
                for (int i = (dp.length() - 1) / period * period; i >= period; i -= period) {
                    dp = dp.substring(0, i) + sep + dp.substring(i);
                }
            }
            ip += "." + dp;
        }
        return s.substring(0, startIndex) + s.substring(startIndex).replaceFirst(m.group(), ip);
    }
    public static void main(String[] args) {
        String[] tests = {
            "123456789.123456789",
            ".123456789",
            "57256.1D-4",
            "pi=3.14159265358979323846264338327950288419716939937510582097494459231",
            "The author has two Z$100000000000000 Zimbabwe notes (100 trillion).",
            "-in Aus$+1411.8millions",
            "===US$0017440 millions=== (in 2000 dollars)",
            "123.e8000 is pretty big.",
            "The land area of the earth is 57268900(29% of the surface) square miles.",
            "Ain't no numbers in this here words, nohow, no way, Jose.",
            "James was never known as 0000000007",
            " wrote: I believe there are " +
                "15747724136275002577605653961181555468044717914527116709366231425076185631031296" +
                " protons in the universe.",
            "   $-140000±100 millions.",
            "6/9/1946 was a good year for some.",
        };
        System.out.println(commatize(tests[0], 0, 2, "*"));
        System.out.println(commatize(tests[1], 0, 3, "-"));
        System.out.println(commatize(tests[2], 0, 4, "__"));

