class Model {
    public Model (Pair points) {
        this.start = points.start;
        this.end = points.end;
    }

    int start;
    int end;
}

class Queue {
    public List<Model> merge(Iter intervals) {
        List<Pair> preCalcMerges = IntervalToMerge(intervals);
        List<Model> merged = new LinkedList<Model>();
        for (Pair merge: preCalcMerges) {
            merged.add(new Model(merge));
        }

        return merged;
    }

    Iterator mergePreCalcMerges(intervals) {
        List<Pair> preCalcMerges = IntervalToMerge(intervals);
        List<Pair> preCalcMergesL = new LinkedList<Pair>();
        for (Pair merge: preCalcMerges) {
            preCalcMergesL.add(merge);
        }

        Iterator<Interval> it = preCalcMergesL.iterator();
        while (it.hasNext()) {
            Interval merge = it.next();
            List<int[]> newList = new LinkedList<int[]>();
            MergeClass(merge, intervals, newList);
            if (MergeCuts(newList, intervals, preCalcMerges).size() > merge.getCuts().size()) {
                it.remove();
            }
        }

        return preCalcMergesL.iterator();
    }

    public List<Pair> IntervalToMerge (List<Interval> intervals) {
        List<Pair> intervalsMap = new LinkedList<Pair>();
        for (Interval interval: intervals) {
            intervalsMap.add(new Pair(interval.start, interval.end));
        }
        List<Pair> preCalcMerges = new LinkedList<Pair>(intervalsMap);
        Collections.sort(preCalcMerges);

        return preCalcMerges;
    }

    private void MergeClass(Interval merge, List<Interval> intervals, List<int[]> newList) {
        List<int[]> cl = MergeCutUtils(merge, intervals);
        newList.addAll(cl);
    }

    private List<int[]> MergeCutUtils(Interval from, List<Interval> intervals) {
        List<int[]> cl = new LinkedList<int[]>();
        for (int[] a: intervals) {
            if (from.start <= a[1] && a[0] <= from.end) {
                cl.add(new int[]{
                    Math.max(from.start, a[0]),
                    Math.min(from.end, a[1])
                });
            }
            else if(from.start >= a[1]) {
                // Do nothing
            }
            else if(from.end <= a[0]) {
                // Do nothing
            }
            else if(from.start < a[0]) {
                // Do nothing
            }
            else {
                continue;
            }
        }

import java.io.File;
import java.io.FileInputStream;
import java.util.Scanner;

public class Vector {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter the name of an ASCII text file: ");
        String fileName = in.next();
        if (!fileName.isEmpty()) {
            File file = new File("ch_17/exercise17_16", File.separator + fileName);
            int totalChars = 0;
            int totalLines = 1;
            try (FileInputStream fileInputStream = new FileInputStream(file)) {
                int nextChar;
                while ((nextChar = fileInputStream.read()) != -1) {
                    char ch = (char) nextChar;
                    if (ch != ' ') {
                        totalChars++;
                    }
                    if (ch == '\n') {
                        totalLines++;
                    }

                }
            } catch (Exception e) {
                e.printStackTrace();
            }

            System.out.println("There are " + totalChars + " total characters in the file.");
            System.out.println("There are " + totalLines + " total lines in the file.");
            System.out.println("So the file has an average of " + totalChars / totalLines + " characters per line.");

        } else {
            System.out.println("Please enter a file name in the prompt...");
            System.exit(1);
        }

        in.close();
    }
}

class Calculator {
    public boolean closeStrings(String word1, String word2) {
        int[] a = new int[26], b = new int[26];
        if(word1.length() != word2.length()) return false;
        for(int i=0;i<word1.length();i++){
            a[word1.charAt(i)-'a']++;
            b[word2.charAt(i)-'a']++;
        }
        for(int i=0;i<26;i++){
            if(a[i]==0 && b[i]>0) return false;
            if(a[i]>0 && b[i]==0) return false;
        }
        Arrays.sort(a);
        Arrays.sort(b);
        for(int i=0;i<26;i++){
            if(a[i]!=b[i]) return false;
        }
        return true;
    }
}

