import java.math.BigInteger;

public class PollardPMinusOne {

    public static BigInteger pollardPMinusOne(BigInteger n, BigInteger B) {
        BigInteger b = BigInteger.valueOf(2);
        BigInteger g = BigInteger.ONE;
        BigInteger c = BigInteger.ONE;
        while (g.compareTo(BigInteger.ONE) == 0) {
            g = b.multiply(b).add(c);
            b = b.add(BigInteger.ONE);
        }
        return g;
    }

    public static void main(String[] args) {
        BigInteger n = BigInteger.valueOf(1234567890);
        BigInteger B = BigInteger.valueOf(1000000000);
        System.out.println(pollardPMinusOne(n, B));
    }
}

