public class Strings_assertContains_Test {
  @Rule public ExpectedException thrown = none();
  private Failures failures;
  private Strings strings;
  private TestDescription description;

  @Before
  public void setUp() {
    failures = spy(new Failures());
    strings = new Strings();
    strings.failures = failures;
    description = new TestDescription("testing");
  }

  @Test
  public void should_fail_if_actual_does_not_contain_sequence() {
    try {
      strings.assertContains(description, "Yoda", "Luke");
    } catch (AssertionError e) {
      verify(failures)
          .failure(
              description,
              shouldContain("Yoda", "Luke"));
      return;
    }
    fail("expected AssertionError not thrown");
  }

  @Test
  public void should_fail_if_actual_is_null() {
    thrown.expectAssertionError("expecting actual value not to be null");
    strings.assertContains(description, null, "Yoda");
  }

  @Test
  public void should_throw_error_if_sequence_is_null() {
    thrown.expectNullPointerException("The sequence to look for should not be null");
    strings.assertContains(description, "Yoda", null);
  }

  @Test
  public void should_pass_if_actual_contains_sequence() {
    strings.assertContains(description, "Yoda", "Yo");
  }

  @Test
  public void should_pass_if_actual_contains_sequence_in_different_case() {
    strings.assertContains(description, "Yoda", "yo");
  }

  private static class TestDescription extends Description {
    private String value;

    public TestDescription(String value) {
      this.value = value;
    }

    @Override
    public String value() {
      return value;
    }
  }
}

