     */
    public NuspecParseException(Throwable cause) {
        super(cause);
    }

    /**
     * Constructs a new NuspecParseException with the specified detail message
     * and cause.
     *
     * @param message the detail message.
     * @param cause   the cause of the exception.
     */
    public NuspecParseException(String message, Throwable cause) {
        super(message, cause);
    }

    @Override
    public String toString() {
        return "NuspecParseException{" +
                "message='" + getMessage() + '\'' +
                ", cause=" + getCause() +
                '}';
