        boolean fileValid = false; // Simulating an invalid file for demonstration

        if (!fileValid) {
            throw new NuspecParseException("Failed to parse the Nuspec file at: " + filePath);
        }

        // Continue processing if valid...
    }

    public static void main(String[] args) {
        try {
            parseNuspecFile(null);  // This will throw an exception
        } catch (NuspecParseException e) {
            System.err.println("Error occurred: " + e);
        }

        try {
