/**
 * A moving ball that bounces off boundaries.
 */
public class Ball {
    private float posX;
    private float posY;
    private int radius;
    private float speedX;
    private float speedY;

    public Ball(float posX, float posY, int radius, float speedX, float speedY) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speedX;
        this.speedY = speedY;
    }

    public float getX() {
        return posX;
    }

    public void setX(float posX) {
        this.posX = posX;
    }

    public float getY() {
        return posY;
    }

    public void setY(float posY) {
        this.posY = posY;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public float getXDelta() {
        return speedX;
    }

    public void setXDelta(float speedX) {
        this.speedX = speedX;
    }

    public float getYDelta() {
        return speedY;
    }

    public void setYDelta(float speedY) {
        this.speedY = speedY;
    }

    public void move() {
        posX += speedX;
        posY += speedY;
    }

    public void reflectHorizontal() {
        speedX = -speedX;
    }

    public void reflectVertical() {
        speedY = -speedY;
    }

    @Override
    public String toString() {
        return "Ball[(" + posX + "," + posY + "),speed=(" + speedX + "," + speedY + ")]";
    }
}

