import java.util.Scanner;

public class AnalyzeScores {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        double[] scores = new double[100]; // array to store scores
        int count = 0; // number of scores entered
        double sum = 0; // sum of all scores entered

        // read scores until a negative number is entered
        System.out.print("Enter scores (negative number to end): ");
        double score = input.nextDouble();
        while (score >= 0 && count < 100) {
            scores[count] = score;
            sum += score;
            count++;
            score = input.nextDouble();
        }

        // calculate average score
        double average = sum / count;

        // count scores above and below average
        int aboveAverage = 0;
        int belowAverage = 0;
        for (int i = 0; i < count; i++) {
            if (scores[i] >= average) {
                aboveAverage++;
            } else {
                belowAverage++;
            }
        }

        // display results
        System.out.println("Average score: " + average);
        System.out.println("Number of scores above or equal to the average: " + aboveAverage);
        System.out.println("Number of scores below the average: " + belowAverage);
    }
}

class Account {
    public int countVowelStrings(int n) {
        int[] dp = new int[5];
        Arrays.fill(dp, 1);

        for (int i = 1; i < n; i++) {
            int[] next = new int[5];
            next[0] = dp[0] + dp[1] + dp[2] + dp[3] + dp[4];
            next[1] = dp[1] + dp[2] + dp[3] + dp[4];
            next[2] = dp[2] + dp[3] + dp[4];
            next[3] = dp[3] + dp[4];
            next[4] = dp[4];
            dp = next;
        }

        return Arrays.stream(dp).sum();
    }
}

public class BreakOrnegi {

    // For dongusu icerisinde break ifadesinin nasil calistigini gosterir
    public static void forOrnegiGoster() {
        System.out.println("For dongusu ornegi:");
        int sayac = 1;
        for (; sayac <= 10; sayac++) {
            if (sayac == 5) { // sayac 5'e ulastiginda dongu durur
                System.out.println("Dongu 5 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + sayac);
        }
    }

    // While dongusu icinde break kullanilan ornek
    public static void whileOrnegiGoster() {
        System.out.println("\nWhile dongusu ornegi:");
        int sayac = 1;
        while (true) {
            if (sayac > 10) {
                break;
            }
            if (sayac == 7) { // sayac 7 oldugunda dongu sonlanir
                System.out.println("Dongu 7 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + sayac);
            sayac++;
        }
    }

    // Ic ice yerlestirilmis donguler icerisinde break kullanimi
    public static void icIceOrnegiGoster() {
        System.out.println("\nIc ice donguler ornegi:");
        for (int disSayac = 1; disSayac <= 4; disSayac++) {
            int icSayac = 1;
            while (icSayac <= 4) {
                if (icSayac == 2) { // ic dongu belli bir noktada durdurulur
                    System.out.println("Ic dongu j = 2 de kirildi (i = " + disSayac + ")");
                    break;
                }
                System.out.println("i: " + disSayac + ", j: " + icSayac);
                icSayac++;
            }
        }
    }

    public static void main(String[] args) {
        // Sirasiyla ornekleri calistir
        forOrnegiGoster();
        whileOrnegiGoster();
        icIceOrnegiGoster();
    }
}

