        int i, j;
        Deck d = new Deck();
        System.out.print("New deck, ");
        d.show();
        System.out.println("\nShuffle and deal to three players:");
        d.shuffle();
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 5; j++)
                d.deal().show();
