import java.util.Scanner;

public class Converter {
    static String fiboWord2(String word) {
        String a = "A", b = "B", c = a + b;
        while (c.length() < word.length()) {
            c = a + b + c;
            a = b;
            b = c;
        }
        return c.equals(word) ? "YES" : "NO";
    }

