public double getStringWidth(String string, TextAlignment tj) {

    // Get the current font of the string
    Font font = GraphicsEnvironment.getLocalGraphicsEnvironment().getDefaultScreenDevice().getDefaultConfiguration().getDevice().getDefaultConfiguration().getFont();

    // Get the current graphics object
    Graphics2D graphicsObject = (Graphics2D) new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).getGraphics();

    // Set the font of the graphics object
    graphicsObject.setFont(font);

    // Get the font metrics for the current font
    FontMetrics fontMetrics = graphicsObject.getFontMetrics(font);

    // Get the width of the string using the font metrics of the current font
    double stringWidth = fontMetrics.stringWidth(string);

    // Add any necessary padding according to the text alignment
    switch (tj) {
        case CENTER:
            stringWidth += (400 - stringWidth) / 2;
            break;
        case RIGHT:
            stringWidth = 400 - stringWidth;
            break;
        default:
            break;
    }

    return stringWidth;
}

import java.util.*;
import java.io.*;

public class Employee {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }
            double sum = 0;
            for (int i = 0; i < n; i++) {
                sum += a[i];
            }
            boolean flag = false;
            for (int i = 0; i < n; i++) {
                double avg = (sum - a[i]) / (n - 1);
                if (avg == a[i]) {
                    flag = true;
                    break;
                }
            }
            if (flag) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }
}

