import java.util.*;

public class A {

    public static void main(String[] argv) {

        Scanner input = new Scanner(System.in);

        int R = input.nextInt();

        int G = input.nextInt();

        int B = input.nextInt();

        int r[] = new int[205];

        int g[] = new int[205];

        int b[] = new int[205];

        int[][][] dp = new int[210][210][210];

        for (int i = 0; i < R; i++) {

            r[i] = input.nextInt();

        }

        for (int i = 0; i < G; i++) {

            g[i] = input.nextInt();

        }

        for (int i = 0; i < B; i++) {

            b[i] = input.nextInt();

        }

        Arrays.sort(r,0,R);

        Arrays.sort(g,0,G);

        Arrays.sort(b,0,B);

        int ans = 0;

        for (int i = 0; i <= R; i++) {

            for (int j = 0; j <= G; j++) {

                for (int k = 0; k <= B; k++) {

                    if (i < R && j < G) {

                        dp[i + 1][j + 1][k] = Math.max(dp[i + 1][j + 1][k], dp[i][j][k] + r[i] * g[j]);

                    }

                    if (i < R && k < B) {

                        dp[i + 1][j][k + 1] = Math.max(dp[i + 1][j][k + 1], dp[i][j][k] + r[i] * b[k]);

                    }

                    if (j < G && k < B) {

                        dp[i][j + 1][k + 1] = Math.max(dp[i][j + 1][k + 1], dp[i][j][k] + g[j] * b[k]);

                    }

                    ans = Math.max(ans, dp[i][j][k]);

                }

            }

        }

        System.out.println(ans);

        input.close();

    }

}

