public long maximumStrength(int[] arr, int k) {
    int n = arr.length;
    long ans = 0;
    for (int mask = 0; mask < (1 << k); ++mask) {
        int[] sorted = new int[k];
        int[] len = new int[n];
        int ptr = 0;
        long maxSum = Long.MIN_VALUE;
        for (int i = 0; i < n; ++i) {
            if ((mask & (1 << i)) != 0) {
                sorted[ptr] = arr[i];
                maxSum = Math.max(maxSum, (long) sorted[ptr] * (ptr + 1) - sum(sorted, 0, ptr));
                ++len[i];
                ++ptr;
            }
        }
        if (ptr == k) {
            ans = Math.max(ans, maxSum);
        }
        for (int i = 0; i < n; ++i) {
            if (len[i] == 0) {
                for (int j = 0; j < ptr; ++j) {
                    sorted[j] = arr[i];
                }
                long sum = sum(sorted, 0, ptr);
                ans = Math.max(ans, maxSum + (long) (sum + (ptr + 1) * (arr[i] - sum)) * (len[i] - 1));
            }
        }
    }
    return ans;
}

private long sum(int[] arr, int st, int ed) {
    long sum = 0;
    for (int i = st; i < ed; ++i) {
        sum += arr[i];
    }
    return sum;
}
