        KarniyarikRepository webConfig = new KarniyarikRepository();
        Config config = webConfig.getConfig("indexMerge");
        String url = config.getUrl();
        String servletURL = config.getServletPath();

        // Ensure URL and servlet path have trailing slashes
        if (!url.endsWith("/")) {
            url += "/";
        }
        if (!servletURL.startsWith("/")) {
            servletURL = "/" + servletURL;
        }

        StringBuilder fullUrl = new StringBuilder(url).append(servletURL)
                .append("?").append(SITE_NAME_PARAMETER).append("=").append(siteName);

        if (reduceBoost) {
            fullUrl.append("&").append(REDUCE_BOOST_PARAMETER).append("=").append("true");
        }

        try {
            URL obj = new URL(fullUrl.toString());
            URLConnection connection = obj.openConnection();
            InputStream is = connection.getInputStream();
            is.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void callReduceSiteIndex(String siteName) {
        callMergeSiteIndex(siteName, true);
    }

