        case 201:
            return null;
        case 202:
            return null;
        case 400:
            if(respBody.equalsIgnoreCase("Bad Request")) {
                return "Terminal Binding Condition: Bad Request";
            } else {
                return null;
            }
        case 401:
            if(respBody.equalsIgnoreCase("Unauthorized")) {
                return "Terminal Binding Condition: Unauthorized";
            } else {
                return null;
            }
        case 403:
            if(respBody.equalsIgnoreCase("Forbidden")) {
                return "Terminal Binding Condition: Forbidden";
            } else {
                return null;
            }
        case 404:
            if(respBody.equalsIgnoreCase("Not Found")) {
                return "Terminal Binding Condition: Not Found";
            } else {
                return null;
            }
        case 500:
            if(respBody.equalsIgnoreCase("Internal Server Error")) {
                return "Terminal Binding Condition: Internal Server Error";
            } else {
                return null;
            }
        default:
            return null;
    }
}

import org.spongepowered.api.command.CommandResult;
import org.spongepowered.api.command.exception.CommandException;
import org.spongepowered.api.entity.living.player.Player;
import org.spongepowered.api.world.gamemode.GameMode;
import io.github.nucleuspowered.nucleus.core.scaffold.command.ICommandContext;
import io.github.nucleuspowered.nucleus.core.scaffold.command.annotation.Command;
import io.github.nucleuspowered.nucleus.core.scaffold.command.annotation.CommandModifier;
import io.github.nucleuspowered.nucleus.core.scaffold.command.modifier.CommandModifiers;

@Command(
    aliases = {"gamemodetoggle", "gmt"},
    commandDescriptionKey = "gamemode.toggle",
    modifiers = {
        @CommandModifier(value = CommandModifiers.HAS_COOLDOWN, exemptPermission = "gamemode.toggle.exempt.cooldown"),
        @CommandModifier(value = CommandModifiers.HAS_WARMUP, exemptPermission = "gamemode.toggle.exempt.warmup"),
        @CommandModifier(value = CommandModifiers.HAS_COST, exemptPermission = "gamemode.toggle.exempt.cost")
    },
    parentCommand = GamemodeCommand.class
)
public class GamemodeToggleCommand extends GamemodeBase {

    @Override
    public CommandResult execute(ICommandContext context) throws CommandException {
        Player player = context.getIfPlayer();
        GameMode current = player.gameMode().orElse(GameMode.SURVIVAL);
        GameMode target = current == GameMode.CREATIVE ? GameMode.SURVIVAL : GameMode.CREATIVE;

        context.sendMessage("text.gamemode.toggling", target.getName());
        return updateGameMode(context, player, target);
    }

    private CommandResult updateGameMode(ICommandContext context, Player player, GameMode mode) {
        player.setGameMode(mode);
        context.sendMessage("text.gamemode.success", mode.getName());
        return CommandResult.success();
    }
}

