public boolean validPartition(int[] a) {
    if (a == null || a.length == 0) return false;

    int n = a.length;
    if (n % 2 != 0) return false;

    if (n == 2) return a[0] % 2 == a[1] % 2;

    for (int i = 2; i < n; i += 2) {
        if ((a[i - 1] % 2 == a[i] % 2 || a[i - 1] - a[i] == 1)
                && (a[i + 1] % 2 == a[i] % 2 || a[i + 1] - a[i] == 1)) {
            if (validPartition(Arrays.copyOfRange(a, i + 2, n))) {
                return true;
            }
        }
    }

    return false;
}

public class SicaklikDonusumu {

    public static void main(String[] args) {

        // Tek bir sicaklik degeri icin donusum
        {
            double celsius = 25.0; // Celsius degeri
            double fahrenheit = (celsius * 1.8) + 32; // Fahrenheit'e donusum
            double kelvin = celsius + 273.15; // Kelvin'e donusum

            // Sonuclari ekrana yazdir
            System.out.println(celsius + " °C = " + fahrenheit + " °F = " + kelvin + " °K");
        }

        // Bir dizi sicaklik degerleri icin donusum
        {
            // Sicaklik degerleri dizisi
            double[] celsiuses = {-40, 0, 25, 100};

            // Her bir sicaklik degeri icin donusum yap
            for (double celsius : celsiuses) {
                double fahrenheit = (celsius * 1.8) + 32; // Fahrenheit'e donusum
                double kelvin = celsius + 273.15; // Kelvin'e donusum

                // Sonuclari ekrana yazdir
                System.out.println(celsius + " °C = " + fahrenheit + " °F = " + kelvin + " °K");
            }
        }
    }
}

// Requires Java 11
import java.util.stream.IntStream;
 
public class Student {
    public static void main(String[] args) {
        int[] n = { 3, 5, 7 };
        int[] a = { 2, 3, 2 };
        System.out.println(chineseRemainder(n, a));
    }
 
    public static int mulInv(int a, int b) {
        int b0 = b;
        int x0 = 0;
        int x1 = 1;
        if (b == 1) {
            return 1;
        }
        while (a > 1) {
            int q = a / b;
            int amb = a % b;
            a = b;
            b = amb;
            int xqx = x1 - q * x0;
            x1 = x0;
            x0 = xqx;
        }
        if (x1 < 0) {
            x1 += b0;
        }
        return x1;
    }
 
    public static int chineseRemainder(int[] n, int[] a) {
        int prod = IntStream.of(n).reduce(1, (a, b) -> a * b);
        int sm = 0;
        for (int i = 0; i < n.length; i++) {
            int p = prod / n[i];
            sm += a[i] * mulInv(p, n[i]) * p;
        }
        return sm % prod;
    }
}

