//https://www.codechef.com/submit/FANCY

#include<bits/stdc++.h>
using namespace std;
#define sf scanf
#define pf push_front

int a[25],cnt[25];
void upd(int x){
    for(int i=x-1;i;i--)
        if(cnt[i]>cnt[i+1]+1)
            swap(cnt[i],cnt[i+1]);
    if(cnt[x-1]<=(int)(str.length()))
        cnt[x] = 1e8;
}

int main(){
    int arr[25];
    int t;
    sf("%d",&t);
    while(t--){
        string str;
        sf("%s",str.c_str());
        memset(cnt,0,sizeof(cnt));
        for(auto&x: str)
            (cnt[x-97]++,-a[x-97]++);
        for(int i=1;i<25;i++)
            if(cnt[i])
                a[i] = cnt[i]-1,upd(i);
        memset(cnt,0,sizeof(cnt));
        for(auto& x: str)
            (cnt[x-97]++,-a[x-97]++);
        arr[1] = min((int)(str.length()),cnt[i]+1);
        for(int i=2;i<25;i++)
            if(cnt[i])
                a[i] = cnt[i]-1,upd(i),arr[2] = max(arr[2],a[i]+1);
        if(arr[1]+arr[2]==(int)(str.length())){
            printf("%d\n",arr[1]-1);
        } else{
            printf("%d\n",arr[1]+1);
        }
    }
    return 0;
}

