        if (validarDeposito(depositoInicial)) {
            Conta novaConta;
            if (tipo.equalsIgnoreCase("especial")) {
                novaConta = new ContaEspecial(depositoInicial);
            } else {
                novaConta = new Conta(depositoInicial);
            }
            contas.add(novaConta);
            System.out.println("Conta aberta: " + novaConta.getNumero());
        } else {
            System.out.println("Depósito inicial inválido.");
        }
    }

    private boolean validarDeposito(double deposito) {
        return deposito >= 0; // Deposito deve ser não-negativo
    }
