public class Nth {
    public static String ordinalAbbrev(int n){
        String ans = "th"; //most of the time it should be "th"
        if(n % 100 / 10 == 1) return ans; //teens are all "th"
        switch(n % 10){
            case 1: ans = "st"; break;
            case 2: ans = "nd"; break;
            case 3: ans = "rd"; break;
        }
        return ans;
    }
 
    public static void main(String[] args){
        for(int i = 0; i <= 25;i++){
            System.out.print(i + ordinalAbbrev(i) + " ");
        }
        System.out.println();
        for(int i = 250; i <= 265;i++){
            System.out.print(i + ordinalAbbrev(i) + " ");
        }
        System.out.println();
        for(int i = 1000; i <= 1025;i++){
            System.out.print(i + ordinalAbbrev(i) + " ");
        }
    }
}

class Stack {
    public int[] threeEqualParts(int[] A) {
        int count = 0;
        for (int i = 0;i < A.length;i++) count += A[i];
        if (count%3 != 0) return new int[]{-1, -1};
        if (count == 0) return new int[]{0,A.length - 1};

        count /= 3;
        int last = A.length - 1, num = count;
        for (last = A.length - 1;last > 1;last--){
            if (A[last] == 1) num--;
            if (num == 0) break;
        }
        int first = 0;
        while (A[first] == 0) first++;
        for (int i = 0;i < last - first;i++){
            if (A[first + i] != A[last + i]) return new int[]{-1, -1};
            if (last + i == A.length - 1){
                first += i;
                break;
            }
        }

        // check mid
        int p = first + 1;
        while (A[p] == 0) p++;
        num = count;
        for (int i = 0;i < A.length - last;i++){
            if (A[p] != A[last + i]) return new int[]{-1, -1};
            p++;
        }

        return new int[]{first, p};
    }
}

