public class Levenshtein {
 
    public static int distance(String a, String b) {
        a = a.toLowerCase();
        b = b.toLowerCase();
        // i == 0
        int [] costs = new int [b.length() + 1];
        for (int j = 0; j < costs.length; j++)
            costs[j] = j;
        for (int i = 1; i <= a.length(); i++) {
            // j == 0; nw = lev(i - 1, j)
            costs[0] = i;
            int nw = i - 1;
            for (int j = 1; j <= b.length(); j++) {
                int cj = Math.min(1 + Math.min(costs[j], costs[j - 1]), a.charAt(i - 1) == b.charAt(j - 1) ? nw : nw + 1);
                nw = costs[j];
                costs[j] = cj;
            }
        }
        return costs[b.length()];
    }
 
    public static void main(String [] args) {
        String [] data = { "kitten", "sitting", "saturday", "sunday", "rosettacode", "raisethysword" };
        for (int i = 0; i < data.length; i += 2)
            System.out.println("distance(" + data[i] + ", " + data[i+1] + ") = " + distance(data[i], data[i+1]));
    }
}

import java.util.Scanner;

public class Game {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.print("Enter values for a, b, and c: ");
        double a = in.nextDouble();
        double b = in.nextDouble();
        double c = in.nextDouble();

        double[] values = new double[]{a, b, c};
        double[] rootVals = new double[2];

        int numRoots = solveQuadratic(values, rootVals);
        System.out.println("The number of real roots is " + numRoots);
        if (numRoots != 0) {
            System.out.print("The real roots values are: ");
            for (double value : rootVals) {
                if (value != 0.0) {
                    System.out.print(value + " ");
                }
            }
        }
        in.close();
    }

    public static int solveQuadratic(double[] eqn, double[] roots) {

        double dis = Math.pow(eqn[1], 2) - 4 * eqn[0] * eqn[2];

        if (dis < 0) {
            return 0;
        } else if (dis == 0) {
            roots[0] = (-1 * eqn[1]) + (Math.pow(dis, 0.5) / (2 * eqn[0]));
            return 1;

        } else {
            roots[0] = (-1 * eqn[1]) + (Math.pow(dis, 0.5) / (2 * eqn[0]));
            roots[1] = (-1 * eqn[1]) - (Math.pow(dis, 0.5) / (2 * eqn[0]));
            return 2;
        }

    }
}

import com.google.api.client.json.GenericJson;
import com.google.api.client.util.Key;

/**
 * Configuration model for specifying characters to exclude during data de-identification processes.
 * Enables preservation of specified characters when using Google Cloud's Data Loss Prevention API.
 */
public class GooglePrivacyDlpV2CharsToIgnore extends GenericJson {

    /**
     * Predefined character groups that can be excluded from de-identification transformations.
     */
    public enum CommonCharactersToIgnore {
        /** Numeric digits (0-9) */
        NUMERIC,
        /** Uppercase alphabetic characters (A-Z) */
        ALPHA_UPPER_CASE,
        /** Lowercase alphabetic characters (a-z) */
        ALPHA_LOWER_CASE,
        /** Common punctuation marks (. , ! ? etc.) */
        PUNCTUATION,
        /** Special symbols (@, #, $, etc.) */
        SYMBOL,
        /** Whitespace characters (space, tab, newline) */
        WHITESPACE
    }

    /** Custom sequence of characters to preserve during processing */
    @Key
    private String charactersToSkip;

    /** Selection of predefined character group to preserve */
    @Key
    private CommonCharactersToIgnore commonCharactersToIgnore;

    /**
     * Retrieves the custom characters excluded from transformation.
     * @return Directly specified characters to skip
     */
    public String getCharactersToSkip() {
        return charactersToSkip;
    }

    /**
     * Defines a custom set of characters to preserve during de-identification.
     * @param charactersToSkip String containing characters to exclude
     * @return Modified configuration instance
     */
    public GooglePrivacyDlpV2CharsToIgnore setCharactersToSkip(String charactersToSkip) {
        this.charactersToSkip = charactersToSkip;
        return this;
    }

    /**
     * Retrieves the predefined character group exclusion setting.
     * @return Selected common character group to ignore
     */
    public CommonCharactersToIgnore getCommonCharactersToIgnore() {
        return commonCharactersToIgnore;
    }

    /**
     * Specifies a predefined character group to preserve during processing.
     * @param commonCharactersToIgnore Enum value indicating character group
     * @return Modified configuration instance
     */
    public GooglePrivacyDlpV2CharsToIgnore setCommonCharactersToIgnore(
            CommonCharactersToIgnore commonCharactersToIgnore) {
        this.commonCharactersToIgnore = commonCharactersToIgnore;
        return this;
    }

