import org.eclipse.ui.IWorkbenchActionConstants;
import org.eclipse.ui.IWorkbenchWindow;
import org.eclipse.ui.actions.ActionFactory;
import org.eclipse.ui.actions.ActionFactory.IWorkbenchAction;
import org.eclipse.ui.application.ActionBarAdvisor;
import org.eclipse.ui.application.IActionBarConfigurer;

public class ApplicationActionBarAdvisor extends ActionBarAdvisor {

    private IWorkbenchAction exitAction;
    private IWorkbenchAction newWindowAction;

    public ApplicationActionBarAdvisor(IActionBarConfigurer configurer) {
        super(configurer);
    }

    @Override
    protected void makeActions(IWorkbenchWindow window) {
        // Create and register actions
        exitAction = ActionFactory.QUIT.create(window);
        register(exitAction);

        newWindowAction = ActionFactory.OPEN_NEW_WINDOW.create(window);
        register(newWindowAction);
    }

    @Override
    protected void fillMenuBar(IMenuManager menuBar) {
        // Create a "File" menu and add actions to it
        MenuManager fileMenu = new MenuManager("&File", IWorkbenchActionConstants.M_FILE);
        menuBar.add(fileMenu);

        fileMenu.add(newWindowAction);
        fileMenu.add(exitAction);
    }

    @Override
    protected void fillCoolBar(IToolBarManager coolBar) {
        // Create a toolbar and add actions to it
        ToolBarManager toolbarManager = new ToolBarManager(coolBar.getStyle());
        coolBar.add(new ToolBarContributionItem(toolbarManager, "main"));

        toolbarManager.add(newWindowAction);
    }

    @Override
    public void dispose() {
        // Clean up actions
        if (exitAction != null) {
            exitAction.dispose();
        }
        if (newWindowAction != null) {
            newWindowAction.dispose();
        }
        super.dispose();
    }
}

