        for (int t = 0; t < tc; t++) {
            int n = in.nextInt();
            List<Integer> scores = new ArrayList<>();
            for (int i = 0; i < n - 1; i++) {
                scores.add(i, 1);
            }
            for (int i = 0; i < n - 1; i++) {
                scores.add(i, i + 1);
            }
            System.out.print(n * (n - 1) / 2 + " ");
            for (int i = 0; i < scores.size(); i++) {
                System.out.print(scores.get(i) + " ");
            }
            System.out.println();
        }
        in.close();
    }
}

