class Graph {
    public int distinctIntegers(int n) {
        boolean newNum = true;
        Set<Integer> set = new HashSet<Integer>();
        set.add(n);
        while(newNum){
            newNum = false;
            List<Integer> list = new ArrayList<Integer>();
            for(Integer val: set){
                for(int i=1;i<=n;i++){
                    if(val%i==1){
                        list.add(i);
                    }
                }
            }
            for(Integer val: list){
                if(!set.contains(val)){
                    set.add(val);
                    newNum = true;
                }
            }
        }
        return set.size();
    }
}

import java.awt.Color;

public static Color colorFromRbgString(String rbgString) {
    String[] parts = rbgString.split(",");
    if (parts.length != 4) {
        throw new IllegalArgumentException("Invalid RGBA string: " + rbgString);
    }
    try {
        int r = Integer.parseInt(parts[0].trim());
        int g = Integer.parseInt(parts[1].trim());
        int b = Integer.parseInt(parts[2].trim());
        int a = Integer.parseInt(parts[3].trim());
        return new Color(r, g, b, a);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid RGBA string: " + rbgString, e);
    }
}

