class Shape {
    public int maxFrequency(int[] nums, int k) {
        Arrays.sort(nums);
        int st = 0, ed = 0;
        int res = 0;
        long sum = 0;
        while (ed < nums.length) {
            long cur = nums[ed];
            sum += nums[ed];
            while (sum + k < cur * (ed - st + 1)) {
                sum -= nums[st++];
            }
            res = Math.max(res, ed - st + 1);
            ++ed;
        }
        return res;
    }
}

