class Vector {
  public int minDays(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;
    if (bfs5501(grid)) {
      return 0;
    }
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] == 1) {
          grid[i][j] = 0;
          if (bfs5501(grid)) {
            return 1;
          }
          grid[i][j] = 1;
        }
      }
    }
    return 2;
  }

  // return true if the grid is disconnected (have 0 or more island)
  static boolean bfs5501(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;
    int[][] dirs = new int[][] {{0, 1},{1,0},{0,-1},{-1,0}};
    int numIslands = 0;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] == 0 || grid[i][j] == 2) {
          continue;
        }
        numIslands++;
        if (numIslands >= 2) {
          reset5501(grid);
          return true;
        }
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[] {i, j});
        while (!q.isEmpty()) {
          int[] p = q.poll();
          int x = p[0];
          int y = p[1];
          grid[x][y] = 2;
          for (int[] dir : dirs) {
            int ii = x + dir[0];
            int jj = y + dir[1];
            if (ii >= 0 && ii < m && jj >= 0 && jj < n && grid[ii][jj] != 0) {
              if (grid[ii][jj] == 1) {
                q.add(new int[] {ii, jj});
                grid[ii][jj] = 2;
              }
            }
          }
        }
      }
    }
    reset5501(grid);
    return numIslands != 1;
  }

  static void reset5501(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] > 0) {
          grid[i][j] = 1;
        }
      }
    }
  }

}

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import javax.xml.transform.stream.StreamResult;
import org.jpedal.examples.simpleviewer.SimpleViewer;
import au.gov.naa.digipres.xena.kernel.view.XenaView;
import au.gov.naa.digipres.xena.kernel.normalise.BinaryDeNormaliser;

public class PdfView extends XenaView {

    private SimpleViewer simpleViewer;
    private File pdfFile;
    private BinaryDeNormaliser base64Handler;

    public PdfView() {
        base64Handler = new BinaryDeNormaliser();
    }

    @Override
    public boolean canShowTag(String tag) {
        return "pdf".equalsIgnoreCase(tag);
    }

    @Override
    public String getViewName() {
        return "PDF Viewer";
    }

    @Override
    public void show(StreamResult streamResult) {
        try {
            // Create a temporary file to store the PDF content
            pdfFile = File.createTempFile("xena_pdf_", ".pdf");
            pdfFile.deleteOnExit();

            // Decode the binary data and write it to the temporary file
            byte[] pdfData = base64Handler.decode(streamResult.getOutputStream().toString());
            try (FileOutputStream fos = new FileOutputStream(pdfFile)) {
                fos.write(pdfData);
            }

            // Initialize and configure the PDF viewer
            simpleViewer = new SimpleViewer();
            simpleViewer.setupViewer(pdfFile.getAbsolutePath(), null);
            simpleViewer.setVisible(true);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void doClose() {
        if (simpleViewer != null) {
            simpleViewer.dispose();
        }
        if (pdfFile != null && pdfFile.exists()) {
            pdfFile.delete();
        }
    }

    @Override
    public BinaryDeNormaliser getContentHandler() {
        return base64Handler;
    }

    public static void main(String[] args) {
        PdfView pdfView = new PdfView();
        // Example usage: pdfView.show(new StreamResult(new ByteArrayOutputStream()));
    }
}

import sun.hotspot.WhiteBox;

public class SetDontInlineMethodTest extends CompilerWhiteBoxTest {

    private static final WhiteBox WHITE_BOX = WhiteBox.getWhiteBox();
    private static final Method METHOD = SetDontInlineMethodTest.class.getDeclaredMethod("testMethod");

    public SetDontInlineMethodTest() throws NoSuchMethodException {
        super();
    }

    @Override
    protected void runTest() {
        // Step 1: Verify the method is initially inlineable
        assertTrue("Method should be inlineable initially", WHITE_BOX.isMethodCompilable(METHOD));

        // Step 2: Mark the method as non-inlineable
        WHITE_BOX.setDontInlineMethod(METHOD, true);
        assertFalse("Method should be non-inlineable after marking", WHITE_BOX.isMethodCompilable(METHOD));

        // Step 3: Revert the method back to being inlineable
        WHITE_BOX.setDontInlineMethod(METHOD, false);
        assertTrue("Method should be inlineable after reverting", WHITE_BOX.isMethodCompilable(METHOD));
    }

    private void testMethod() {
        // Dummy method for testing inlining behavior
        System.out.println("Executing testMethod");
    }

    public static void main(String[] args) throws NoSuchMethodException {
        SetDontInlineMethodTest test = new SetDontInlineMethodTest();
        test.runTest();
    }
}

import java.io.BufferedReader;

import java.io.IOException;

import java.io.InputStreamReader;

import java.io.PrintWriter;

public class Caninepoetry {

    public static void main(String[] args) throws IOException {

        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));

        PrintWriter pr=new PrintWriter(System.out);

        int t=Integer.parseInt(br.readLine());

        while(t!=0){

            solve(br,pr);

            t--;

        }

        pr.flush();

        pr.close();

    }

    public static void solve(BufferedReader br,PrintWriter pr) throws IOException{

        String s=br.readLine();

        int n=s.length();

        int res=0;

        char[] letters=s.toCharArray();

        for(int i=1;i<n;i++){

            if(letters[i]=='!'){

                continue;

            }

            if((i>=2&&letters[i]==letters[i-2])||letters[i]==letters[i-1]){

                letters[i]='!';

                res++;

                continue;

            }

        }

        pr.println(res);

    }

}

import java.util.Iterator;
import java.util.List;
import java.util.Objects;
 
public class StreamMerge {
    private static <T extends Comparable<T>> void merge2(Iterator<T> i1, Iterator<T> i2) {
        T a = null, b = null;
 
        while (i1.hasNext() || i2.hasNext()) {
            if (null == a && i1.hasNext()) {
                a = i1.next();
            }
            if (null == b && i2.hasNext()) {
                b = i2.next();
            }
 
            if (null != a) {
                if (null != b) {
                    if (a.compareTo(b) < 0) {
                        System.out.print(a);
                        a = null;
                    } else {
                        System.out.print(b);
                        b = null;
                    }
                } else {
                    System.out.print(a);
                    a = null;
                }
            } else if (null != b) {
                System.out.print(b);
                b = null;
            }
        }
 
        if (null != a) {
            System.out.print(a);
        }
        if (null != b) {
            System.out.print(b);
        }
    }
 
    @SuppressWarnings("unchecked")
    @SafeVarargs
    private static <T extends Comparable<T>> void mergeN(Iterator<T>... iter) {
        Objects.requireNonNull(iter);
        if (iter.length == 0) {
            throw new IllegalArgumentException("Must have at least one iterator");
        }
 
        Object[] pa = new Object[iter.length];
        boolean done;
 
        do {
            done = true;
 
            for (int i = 0; i < iter.length; i++) {
                Iterator<T> t = iter[i];
                if (null == pa[i] && t.hasNext()) {
                    pa[i] = t.next();
                }
            }
 
            T min = null;
            int idx = -1;
            for (int i = 0; i < pa.length; ++i) {
                T t = (T) pa[i];
                if (null != t) {
                    if (null == min) {
                        min = t;
                        idx = i;
                        done = false;
                    } else if (t.compareTo(min) < 0) {
                        min = t;
                        idx = i;
                        done = false;
                    }
                }
            }
            if (idx != -1) {
                System.out.print(min);
                pa[idx] = null;
            }
        } while (!done);
    }
 
