import org.zoodb.internal.server.StorageChannel;

public interface LongLongIndex {
    void put(long key, long value);
    long get(long key);
    boolean contains(long key);
    void remove(long key);

    interface LongLongUIndex extends LongLongIndex {}
}

final class LongLongIndexFactory {
    public static LongLongIndex createIndex(StorageChannel channel, int pageType) {
        return new PagedLongLong(channel, pageType, -1);
    }

    public static LongLongIndex loadIndex(StorageChannel channel, int pageType, int pageId) {
        return new PagedLongLong(channel, pageType, pageId);
    }

    public static LongLongIndex.LongLongUIndex createUniqueIndex(StorageChannel channel, int pageType) {
        return new PagedUniqueLongLong(channel, pageType, -1);
    }

    public static LongLongIndex.LongLongUIndex loadUniqueIndex(StorageChannel channel, int pageType, int pageId) {
        return new PagedUniqueLongLong(channel, pageType, pageId);
    }

    public static LongLongIndex createExperimentalIndex(StorageChannel channel, int pageType,
            int keySize, int valSize) {
        PagedLongLong index = new PagedLongLong(channel, pageType, -1);
        index.setKeySize(keySize);
        index.setValSize(valSize);
        index.initialize();
        return index;
    }

    public static LongLongIndex loadExperimentalIndex(StorageChannel channel, int pageType,
            int pageId, int keySize, int valSize) {
        PagedLongLong index = new PagedLongLong(channel, pageType, pageId);
        index.setKeySize(keySize);
        index.setValSize(valSize);
        index.reconstruct();
        return index;
    }

    public static LongLongIndex.LongLongUIndex createExperimentalUniqueIndex(StorageChannel channel, int pageType,
            int keySize, int valSize) {
        PagedUniqueLongLong index = new PagedUniqueLongLong(channel, pageType, -1);
        index.setKeySize(keySize);
        index.setValSize(valSize);
        index.initialize();
        return index;
    }

    public static LongLongIndex.LongLongUIndex loadExperimentalUniqueIndex(StorageChannel channel, int pageType,
            int pageId, int keySize, int valSize) {
        PagedUniqueLongLong index = new PagedUniqueLongLong(channel, pageType, pageId);
        index.setKeySize(keySize);
        index.setValSize(valSize);
        index.reconstruct();
        return index;
    }
}

class PagedLongLong implements LongLongIndex {
    private final StorageChannel channel;
    private final int pageType;
    private final int pageId;
    private int keySize;
    private int valSize;

public class Prob{
    static long TRIALS= 1000000;
 
    private static class Expv{
        public String name;
        public int probcount;
        public double expect;
        public double mapping;
 
        public Expv(String name, int probcount, double expect, double mapping){
            this.name= name;
            this.probcount= probcount;
            this.expect= expect;
            this.mapping= mapping;
        }
    }
 
    static Expv[] items=
            {new Expv("aleph", 0, 0.0, 0.0), new Expv("beth", 0, 0.0, 0.0),
                    new Expv("gimel", 0, 0.0, 0.0),
                    new Expv("daleth", 0, 0.0, 0.0),
                    new Expv("he", 0, 0.0, 0.0), new Expv("waw", 0, 0.0, 0.0),
                    new Expv("zayin", 0, 0.0, 0.0),
                    new Expv("heth", 0, 0.0, 0.0)};
 
    public static void main(String[] args){
        int i, j;
        double rnum, tsum= 0.0;
 
        for(i= 0, rnum= 5.0;i < 7;i++, rnum+= 1.0){
            items[i].expect= 1.0 / rnum;
            tsum+= items[i].expect;
        }
        items[7].expect= 1.0 - tsum;
 
        items[0].mapping= 1.0 / 5.0;
        for(i= 1;i < 7;i++){
            items[i].mapping= items[i - 1].mapping + 1.0 / ((double)i + 5.0);
        }
        items[7].mapping= 1.0;
 
 
        for(i= 0;i < TRIALS;i++){
            rnum= Math.random();
            for(j= 0;j < 8;j++){
                if(rnum < items[j].mapping){
                    items[j].probcount++;
                    break;
                }
            }
        }
 
        System.out.printf("Trials: %d\n", TRIALS);
        System.out.printf("Items:          ");
        for(i= 0;i < 8;i++)
            System.out.printf("%-8s ", items[i].name);
        System.out.printf("\nTarget prob.:   ");
        for(i= 0;i < 8;i++)
            System.out.printf("%8.6f ", items[i].expect);
        System.out.printf("\nAttained prob.: ");
        for(i= 0;i < 8;i++)
            System.out.printf("%8.6f ", (double)(items[i].probcount)
                    / (double)TRIALS);
        System.out.printf("\n");
 
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class RamerDouglasPeucker {
    public static void main(String[] args) {
        List<Point> points = new ArrayList<>();
        points.add(new Point(0.0, 0.0));
        points.add(new Point(1.0, 0.1));
        points.add(new Point(2.0, -0.1));
        points.add(new Point(3.0, 5.0));
        points.add(new Point(4.0, 6.0));
        points.add(new Point(5.0, 7.0));
        points.add(new Point(6.0, 8.1));
        points.add(new Point(7.0, 9.0));
        points.add(new Point(8.0, 9.0));
        points.add(new Point(9.0, 9.0));
        List<Point> result = ramerDouglasPeucker(points, 1.0);
        for (Point p : result) {
            System.out.println(p);
        }
    }
 
    public static List<Point> ramerDouglasPeucker(List<Point> points, double epsilon) {
        List<Point> result = new ArrayList<>();
        if (points.size() > 0 && epsilon >= 0.0) {
            result.add(points.get(0));
            rdp(points, epsilon, result);
        }
        return result;
    }
 
    private static void rdp(List<Point> points, double epsilon, List<Point> result) {
        int n = points.size();
        if (n < 2) {
            return;
        }
        double maxDist = 0.0;
        int index = 0;
        for (int i = 1; i < n - 1; i++) {
            double dist = perpendicularDistance(points.get(i), points.get(0), points.get(n - 1));
            if (dist > maxDist) {
                maxDist = dist;
                index = i;
            }
        }
        if (maxDist > epsilon) {
            rdp(points.subList(0, index + 1), epsilon, result);
            rdp(points.subList(index, n), epsilon, result);
        } else {
            result.add(points.get(n - 1));
        }
    }
 
    private static double perpendicularDistance(Point p, Point p1, Point p2) {
        double dx = p2.x - p1.x;
        double dy = p2.y - p1.y;
        return Math.abs(p.x * dy - p.y * dx + p2.x * p1.y - p2.y * p1.x) / Math.hypot(dx, dy);
    }
 
    public static class Point {
        public double x;
        public double y;
 
        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
 
        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.input.KeyCode;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

public class LineDrawing extends Application {

    private double centerX;
    private double centerY;
    private double currentX;
    private double currentY;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create a canvas to draw on
        Canvas canvas = new Canvas(400, 400);
        GraphicsContext gc = canvas.getGraphicsContext2D();

        // Set the initial position of the line to the center of the canvas
        centerX = canvas.getWidth() / 2;
        centerY = canvas.getHeight() / 2;
        currentX = centerX;
        currentY = centerY;

        // Create a pane to hold the canvas
        Pane root = new Pane(canvas);

        // Create a scene and add it to the stage
        Scene scene = new Scene(root);
        primaryStage.setScene(scene);
        primaryStage.show();

        // Set up the key event handler
        scene.setOnKeyPressed(event -> {
            KeyCode keyCode = event.getCode();
            switch (keyCode) {
                case RIGHT:
                    drawLine(gc, currentX, currentY, currentX + 50, currentY);
                    currentX += 50;
                    break;
                case UP:
                    drawLine(gc, currentX, currentY, currentX, currentY - 50);
                    currentY -= 50;
                    break;
                case LEFT:
                    drawLine(gc, currentX, currentY, currentX - 50, currentY);
                    currentX -= 50;
                    break;
                case DOWN:
                    drawLine(gc, currentX, currentY, currentX, currentY + 50);
                    currentY += 50;
                    break;
            }
        });
    }

    private void drawLine(GraphicsContext gc, double startX, double startY, double endX, double endY) {
        gc.setStroke(Color.BLACK);
        gc.setLineWidth(2);
        gc.strokeLine(startX, startY, endX, endY);
    }

    public static void main(String[] args) {
        launch(args);
    }
}

@Override
    public void close() throws IOException {

        super.close();

        synchronized (logBuffer) {
            if(logBuffer.length() > 0) {
                log.info(logBuffer.toString());
                logBuffer.setLength(0);
                lastFlush = System.currentTimeMillis();
            }
        }
    }

