import java.io.*;
import java.nio.file.Files;

public class Solution {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("No parameters were passed....");
            System.out.println("Usage: java Solution SourceFile numberOfPieces");
            return;
        }

        File sourceFile = new File("ch_17/exercise17_10", args[0]);

        int numberOfPieces = Integer.parseInt(args[1]);
        File outDirectory = new File(sourceFile.getParent(),"Result_Dir");
        outDirectory.mkdir();

        File[] outFiles = new File[numberOfPieces];
        String outFilesBaseName = sourceFile.getName() + "_bak_";
        for (int i = 0; i < outFiles.length; i++) {
            outFiles[i] = new File(outDirectory,outFilesBaseName + (i + 1) + ".dat");
        }
        try {

            byte[] bytes = Files.readAllBytes(sourceFile.toPath());
            int bytePerFile = bytes.length / numberOfPieces;
            int masterByteArrayIndex = 0;
            for (File file : outFiles) {
                BufferedOutputStream outputStream = new BufferedOutputStream(new FileOutputStream(file));
                for (int i = 0; i < bytePerFile; i++) {
                    outputStream.write(bytes[masterByteArrayIndex]);
                    masterByteArrayIndex++;
                }
                outputStream.flush();
                outputStream.close();
            }

        } catch (Exception exception) {
            exception.printStackTrace();
        }

    }

}

private final void appendNumericCEs(int ce32, boolean forward) {

        StringBuilder digits = new StringBuilder();
        if(forward) {
            for(;;) {
                char digit = Collation.digitFromCE32(ce32);
                digits.append(digit);
                if(numCpFwd == 0) { break; }
                int c = nextCodePoint();
                if(c < 0) { break; }
                ce32 = data.getCE32(c);
                if(ce32 == Collation.FALLBACK_CE32) {
                    ce32 = data.base.getCE32(c);
                }
                if(!Collation.hasCE32Tag(ce32, Collation.DIGIT_TAG)) {
                    backwardNumCodePoints(1);
                    break;
                }
                if(numCpFwd > 0) { --numCpFwd; }
            }
        } else {
            for(;;) {
                char digit = Collation.digitFromCE32(ce32);
                digits.append(digit);
                int c = previousCodePoint();
                if(c < 0) { break; }
                ce32 = data.getCE32(c);
                if(ce32 == Collation.FALLBACK_CE32) {
                    ce32 = data.base.getCE32(c);
                }
                if(!Collation.hasCE32Tag(ce32, Collation.DIGIT_TAG)) {
                    forwardNumCodePoints(1);
                    break;
                }
            }

            digits.reverse();
        }
        int pos = 0;
        do {

            while(pos < (digits.length() - 1) && digits.charAt(pos) == 0) { ++pos; }

            int segmentLength = digits.length() - pos;
            if(segmentLength > 254) { segmentLength = 254; }
            appendNumericSegmentCEs(digits.subSequence(pos, pos + segmentLength));
            pos += segmentLength;
        } while(pos < digits.length());
    }

import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.Timer;
import java.util.TimerTask;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.WindowConstants;
 
public class Rotate {
 
    private static class State {
        private final String text = "Hello World! ";
        private int startIndex = 0;
        private boolean rotateRight = true;
    }
 
    public static void main(String[] args) {
        State state = new State();
 
        JLabel label = new JLabel(state.text);
        label.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent event) {
                state.rotateRight = !state.rotateRight;
            }
        });
 
        TimerTask task = new TimerTask() {
            public void run() {
                int delta = state.rotateRight ? 1 : -1;
                state.startIndex = (state.startIndex + state.text.length() + delta) % state.text.length();
                label.setText(rotate(state.text, state.startIndex));
            }
        };
        Timer timer = new Timer(false);
        timer.schedule(task, 0, 500);
 
        JFrame rot = new JFrame();
        rot.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        rot.add(label);
        rot.pack();
        rot.setLocationRelativeTo(null);
        rot.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosed(WindowEvent e) {
                timer.cancel();
            }
        });
        rot.setVisible(true);
    }
 
    private static String rotate(String text, int startIdx) {
        char[] rotated = new char[text.length()];
        for (int i = 0; i < text.length(); i++) {
            rotated[i] = text.charAt((i + startIdx) % text.length());
        }
        return String.valueOf(rotated);
    }
}

