import org.apache.log4j.Logger;

public class SynchronizationEvent {

    private static final Logger s_logger = Logger.getLogger(SynchronizationEvent.class);
    private boolean signalled = false;

    public SynchronizationEvent() {
        this.signalled = false;
    }

    public synchronized void setEvent() {
        s_logger.debug("Setting event...");
        this.signalled = true;
        notifyAll();
        s_logger.debug("Event set and all waiting threads notified.");
    }

    public synchronized void resetEvent() {
        s_logger.debug("Resetting event...");
        this.signalled = false;
        s_logger.debug("Event reset.");
    }

    public synchronized boolean waitEvent(long timeoutMillis) throws InterruptedException {
        s_logger.debug("Waiting for event with timeout: " + timeoutMillis + "ms");
        if (timeoutMillis < 0) {
            throw new IllegalArgumentException("Timeout value is negative");
        }

        long startTime = System.currentTimeMillis();
        long remainingTime = timeoutMillis;

        while (!signalled && remainingTime > 0) {
            try {
                wait(remainingTime);
            } catch (InterruptedException e) {
                s_logger.warn("Wait interrupted.");
                throw e;
            }

            if (!signalled) {
               s_logger.debug("Wait timed out.");
               return false;
            }

            remainingTime = timeoutMillis - (System.currentTimeMillis() - startTime);
        }
        if (!signalled)
            return false;

        s_logger.debug("Event received.");
        return true;
    }

     public synchronized void waitEvent() throws InterruptedException {
        s_logger.debug("Waiting for event indefinitely...");
        while (!signalled) {
            try {
                wait();
            } catch (InterruptedException e) {
                s_logger.warn("Wait interrupted.");
                throw e;
            }
        }
        s_logger.debug("Event received.");
    }

    public synchronized boolean isSignalled() {
        return signalled;
    }
}

