        double c = input.nextDouble();
        double d = input.nextDouble();
        double e = input.nextDouble();
        double f = input.nextDouble();
        double y = 0;
        double x = 0;

        if (a * d - b * c < 0.000000001) {
            System.out.println("The equation has no solution :(");
            System.out.println(a + " * " + c + " - " + b + " * " + c + " = " + " 0 ");

        } else {

            x = (e * d - b * f) / (a * d - b * c);
            y = (a * f - e * c) / (a * d - b * c);

            System.out.print("(" + e + " * " + d + " - " + b + " * " + f + ""
                    + ") / (" + a + " * " + d + " - " + b + " * " + c + ")");

            System.out.print(" = x = " + x);

            System.out.print("\nand");

            System.out.print("\n(" + a + " * " + f + " - " + e + " * " + c + ""
                    + ") / (" + a + " * " + d + " - " + b + " * " + c + ")");

            System.out.print(" = y = " + y);

        }
    }

}

 
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class LeftTruncatablePrimes {
 
    public static List<BigInteger> nextLeftTruncatablePrimes(BigInteger n, int radix, int certainty) {
        List<BigInteger> probablePrimes = new ArrayList<>();
        String baseString = n.equals(BigInteger.ZERO)? "" : n.toString(radix);
        for (int i = 1; i < radix; i++) {
            BigInteger p = new BigInteger(i + baseString, radix);
            if (p.isProbablePrime(certainty)) probablePrimes.add(p);
        }
        return probablePrimes;
    }
 
    public static BigInteger largestLeftTruncatablePrime(int radix, int certainty) {
        List<BigInteger> lastList = null;
        List<BigInteger> list = nextLeftTruncatablePrimes(BigInteger.ZERO, radix, certainty);
        while (!list.isEmpty()) {
            lastList = list;
            list = new ArrayList<>();
            for (BigInteger n : lastList) list.addAll(nextLeftTruncatablePrimes(n, radix, certainty));
        }
        if (lastList == null) return null;
        return lastList.stream().sorted().reduce((a, b) -> b).get();
    }
 
    public static void main(String[] args) {
        System.out.print("Enter maximum radix : ");
        int maxRadix = new java.util.Scanner(System.in).nextInt();
        System.out.print("Enter certainty     : ");
        int certainty = new java.util.Scanner(System.in).nextInt();
        System.out.println();
        for (int radix = 3; radix <= maxRadix; radix++) {
            BigInteger largest = largestLeftTruncatablePrime(radix, certainty);
            System.out.print("Base = " + String.format("%-2d", radix) + " : ");
            if (largest == null)
                System.out.println("No left truncatable prime");
            else
                System.out.println(largest.toString().padEnd(35) + " -> " + largest.toString(radix));
        }
    }
}

