import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * An English-Vietnamese dictionary backed by a text file.
 */
public class Dictionary {

    public static ArrayList<String> listwords = new ArrayList<>();

    public static void readDataFormFile() {
        File file = new File("D:\\FPT UNIVERSITY\\STUDY\\KY 2\\PRO\\BIN\\STRING WORK SHOP\\String_workshop\\src\\Dictionary\\en-vi.txt");
        try {
            if (file.exists()) {
                Scanner scanner = new Scanner(file);
                while (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    listwords.add(line.trim().replaceAll("\\s+", " "));
                }
            } else {
                try {
                    file.createNewFile();
                } catch (IOException ex) {
                    System.out.println("Can not create file");
                }
            }
        } catch (FileNotFoundException ex) {
            System.out.println("File data not found");
        }
    }

    public Dictionary() {
        readDataFormFile();
    }

    public String lookup(String word) {
        for (String entry : listwords) {
            StringTokenizer tokenizer = new StringTokenizer(entry, ":");
            String english = tokenizer.nextToken().toLowerCase().trim();
            String vietnamese = tokenizer.nextToken().toLowerCase().trim();
            if (word.equalsIgnoreCase(english)) {
                return vietnamese;
            }
        }
        return "not found";
    }
}

public class PointOperation {
    public static Point pointOperation(Operator op, Point... args) {
        if (op == null) {
            throw new IllegalArgumentException("Operator cannot be null");
        }

        if (args == null || args.length == 0) {
            throw new IllegalArgumentException("Arguments cannot be null or empty");
        }

        Point result = args[0];

        for (int i = 1; i < args.length; i++) {
            switch (op) {
                case ADD:
                    result = result.add(args[i]);
                    break;
                case SUBTRACT:
                    result = result.subtract(args[i]);
                    break;
                case MULTIPLY:
                    result = result.multiply(args[i]);
                    break;
                case DIVIDE:
                    result = result.divide(args[i]);
                    break;
                default:
                    throw new IllegalArgumentException("Unsupported operator: " + op);
            }
        }

        return result;
    }

    public enum Operator {
        ADD,
        SUBTRACT,
        MULTIPLY,
        DIVIDE
    }
}

