    @Test
    public void testInDocker() throws Exception {
        Location dockerLoc = mgmt.getLocationRegistry().resolve("docker");
        doTest(dockerLoc);
    }

    protected void doTest(Location loc) {
        TestApplication app = mgmt.getEntityManager().createEntity(EntitySpec.create(TestApplication.class));

        JBoss7Server server = app.createAndManageChild(EntitySpec.create(JBoss7Server.class)
            .configure(JBoss7Server.WAR_URL, WAR_URL));

        server.start(ImmutableMap.of("locations", ImmutableList.of(loc)));

        assertTrue(server.waitForServiceUp(Duration.THIRTY_SECONDS));

        String appUrl = server.getAttribute(Attributes.MAIN_URI) + "/hello-world";
        HttpAsserts.assertHttpStatusCodeEventuallyEquals(appUrl, 200);

        assertEventually(Asserts.supplier(() ->
            server.getAttribute(Attributes.REQUEST_COUNT) >= 0), Duration.TEN_SECONDS);

        assertEventually(Asserts.supplier(() ->
            server.getAttribute(Attributes.ERROR_COUNT) == 0), Duration.TEN_SECONDS);

        Entities.deprovision(server, true);
    }

