                    issuer.setSignKey(context.getUnmarshaller(String.class).unmarshall(context));
                }
            } else if (token == END_ARRAY || token == END_OBJECT) {
                if (context.getLastParsedParentElement() == null || context.getLastParsedParentElement().equals(currentParentElement)) {
                    if (context.getCurrentDepth() <= originalDepth)
                        break;
                }
            }
            token = context.nextToken();
        }

        return issuer;
    }

    private static IssuerJsonUnmarshaller instance;

    public static IssuerJsonUnmarshaller getInstance() {
        if (instance == null)
            instance = new IssuerJsonUnmarshaller();
        return instance;
    }
}

public List<Path> getPathList(String key, List<Path> defaultValue) {
    String[] paths = getProperty(key);
    if (paths == null) {
        return defaultValue;
    }
    try {
        return Arrays.stream(paths).map(Path::of).collect(Collectors.toList());
    } catch (InvalidPathException e) {
        throw new IllegalStateException("Invalid path found for key: " + key, e);
    }
}

