public class Filter {
    public static final String CONTENT_TYPE_FILTER = "text/plain";
    public static final int MAX_POST_FIELD_SIZE = 1024 * 1024;
    public static final String REQUEST_BODY = "REQUEST_BODY";
    public static final String RESPONSE_BODY = "RESPONSE_BODY";

    private static String serverName;

    private Filter() {}

    public static synchronized void setServerName(String name) {
        if (serverName == null && "鎮守府サーバー".equals(name)) {
            serverName = name;
        }
    }

    public static String getServerName() {
        return serverName;
    }

    public static boolean isServerDetected() {
        return serverName != null;
    }

    private static boolean isValidContentType(String contentType) {
        return contentType != null && CONTENT_TYPE_FILTER.equalsIgnoreCase(contentType);
    }

    private static boolean isValidServer(String targetServer) {
        return targetServer != null && targetServer.equals(serverName);
    }

    private static boolean isValidDataSize(int dataLength) {
        return dataLength >= 0 && dataLength <= MAX_POST_FIELD_SIZE;
    }

    public static boolean isNeed(String currentServer, String contentType, int dataLength) {
        if (!isServerDetected()) {
            return true;
        }

        return isValidServer(currentServer)
            && isValidContentType(contentType)
            && isValidDataSize(dataLength);
    }

    public static boolean isNeed(String currentServer, String contentType, int dataLength, int statusCode) {
        if (statusCode != 200) {
            return false;
        }

        if (!isServerDetected()) {
            return true;
        }

        return isValidServer(currentServer)
            && isValidContentType(contentType)
            && isValidDataSize(dataLength);
    }
}

import com.codahale.metrics.MetricRegistry;
import io.dropwizard.configuration.ConfigurationException;
import io.dropwizard.configuration.ConfigurationFactory;
import io.dropwizard.configuration.DefaultConfigurationFactoryFactory;
import io.dropwizard.configuration.YamlConfigurationFactory;
import io.dropwizard.setup.Environment;
import io.dropwizard.util.Duration;
import io.dropwizard.validation.BaseValidator;
import org.slf4j.LoggerFactory;
import org.slf4j.Logger;
import java.io.File;
import java.io.IOException;

public class LogReporterFactory {

    public Slf4jMetricReporter build(final MetricRegistry metricRegistry,
                                     final Environment environment,
                                     final ConfigurationProperties configurationProperties) {
        final Logger logger = LoggerFactory.getLogger(LogReporterFactory.class);

        final long millisCheck = configurationProperties.getMetricLogReporterMillis();
        if (millisCheck <= 0) {
            logger.info("LogReporter is not activated because metricLogReporterMillis is not greater than zero.");
            return null;
        }

        final Duration duration = Duration.milliseconds(millisCheck);
        final String reporterName = configurationProperties.getMetricLogReporterName();

        logger.info("LogReporter registered under name: {} with reporting interval of: {} milliseconds",
                reporterName, millisCheck);

        final Slf4jMetricReporter reporter = Slf4jMetricReporter.forRegistry(metricRegistry)
                .outputTo(LoggerFactory.getLogger("metrics"))
                .convertRatesTo(TimeUnit.SECONDS)
                .convertDurationsTo(TimeUnit.MILLISECONDS)
                .build();

        reporter.start(duration.toMilliseconds(), TimeUnit.MILLISECONDS);

        return reporter;
    }

    public ConfigurationProperties loadFromFile(final File file) throws IOException, ConfigurationException {
        final YamlConfigurationFactory<ConfigurationProperties> factory = new YamlConfigurationFactory<>(
                ConfigurationProperties.class, BaseValidator.newValidator(), Jackson.newObjectMapper(), "yaml");

        return factory.build(file);
    }
}

import java.awt.Dimension;
import java.awt.Point;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JLabel;
import javax.swing.Timer;
import javax.swing.JFrame;
 
public class BasicAnimationForm extends JFrame
{
  boolean isReverseDirection;
  JLabel textLabel;
  Timer timer;
 
  public BasicAnimationForm()
  {
    this.setSize(new Dimension(150, 75));
    this.setTitle("Basic Animation");
 
    textLabel = new JLabel();
    textLabel.setText("Hello World! ");
    textLabel.setLocation(new Point(3,3));
    textLabel.setSize(textLabel.getPreferredSize());
    textLabel.addMouseListener(new java.awt.event.MouseAdapter() {
      public void mouseClicked(java.awt.event.MouseEvent evt) {
        textLabel_OnClick(evt);
      }
    });
    this.add(textLabel);
 
    timer = new Timer(500, new ActionListener() {
      public void actionPerformed(ActionEvent evt) {
        timer_OnTick(evt);
      }
    });
    timer.start();
 
    isReverseDirection = false;
  }
 
  private void timer_OnTick(ActionEvent evt)
  {
    String oldText = textLabel.getText(), newText;
    if(isReverseDirection)
      newText = oldText.substring(1, oldText.length()) + oldText.substring(0, 1);
    else
      newText = oldText.substring(oldText.length() - 1, 1) + oldText.substring(0, oldText.length() - 1);
    textLabel.setText(newText);
  }
 
  private void textLabel_OnClick(java.awt.event.MouseEvent evt)
  {
    isReverseDirection =!isReverseDirection;
  }
 
  public static void main(String[] args)
  {
    BasicAnimationForm form = new BasicAnimationForm();
    form.setVisible(true);
  }
}

import java.io.BufferedReader;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.ServerSocket;
import java.net.Socket;

// One thread per connected client; simply echoes back whatever it reads
class ConnectionWorker extends Thread {
    private DataInputStream fromClient;
    private DataOutputStream toClient;
    private final Socket clientSocket;
    private final BufferedReader console = new BufferedReader(new InputStreamReader(System.in));

    public ConnectionWorker(Socket clientSocket) {
        this.clientSocket = clientSocket;
        try {
            fromClient = new DataInputStream(clientSocket.getInputStream());
            toClient = new DataOutputStream(clientSocket.getOutputStream());
        } catch (IOException e) {
            e.printStackTrace();
            System.out.println("Istemci baglantisi olusturulurken hata meydana geldi: " + e.getMessage());
        }
    }

    @Override
    public void run() {
        try {
            String received = "";
            while (!received.equals("stop")) {
                received = fromClient.readUTF();
                System.out.println("Istemciden alinan mesaj: " + received);
                toClient.writeUTF(received);
                toClient.flush();
            }
        } catch (IOException e) {
            System.out.println("Istemci ile baglanti koptu: " + e.getMessage());
        } finally {
            try {
                clientSocket.close();
                System.out.println("Istemci soketi kapatildi.");
            } catch (IOException e) {
                System.out.println("Soket kapatilirken hata meydana geldi: " + e.getMessage());
            }
        }
    }
}

/**
 * Accepts connections forever, spinning up a ConnectionWorker thread
 * for each client that connects.
 */
public class Server {

    private static final int PORT = 4444;

    public static void main(String[] args) throws IOException {
        ServerSocket listener = new ServerSocket(PORT);
        System.out.println("Sunucu baslatildi ve baglanti bekleniyor...");

        while (true) {
            Socket clientSocket = null;
            try {
                clientSocket = listener.accept();
                System.out.println("Yeni bir istemci baglandi: " + clientSocket);

                Thread worker = new ConnectionWorker(clientSocket);
                worker.start();

            } catch (Exception e) {
                System.out.println("Baglanti sirasinda hata meydana geldi: " + e.getMessage());

