import javax.vecmath.Point3d;
import java.util.List;
import java.util.ArrayList;
import java.awt.Color;

class S3DOrganism extends AbstractOrganism {
    private List<Node> _roots;
    private float[] _color;  // HSV color
    private static final double COLOR_DRIFT = 0.05;
    private static final double VALUE = 0.7;

    public S3DOrganism(List<Node> roots, float[] color) {
        _roots = roots;
        _color = color;
    }

    public Point3d evaluate(UV uv) {
        double x = _roots.get(0).evaluate(new Pixel(uv.u, uv.v));
        double y = _roots.get(1).evaluate(new Pixel(uv.u, uv.v));
        double z = _roots.get(2).evaluate(new Pixel(uv.u, uv.v));
        return new Point3d(x, y, z);
    }

    public S3DOrganism mutateAsexually(Mutator mutator) {
        List<Node> newRoots = new ArrayList<>();
        for (Node root : _roots) {
            newRoots.add(mutator.mutateNodeTree(root));
        }

        float[] newColor = _color.clone();
        newColor[0] += (float) (Utils.RANDOM.nextGaussian() * COLOR_DRIFT);
        newColor[0] = (newColor[0] + 1.0f) % 1.0f;
        newColor[1] += (float) (Utils.RANDOM.nextGaussian() * COLOR_DRIFT);
        newColor[1] = Math.min(1.0f,Math.max(0.0f,newColor[1] ));

        return new S3DOrganism(newRoots, newColor);
    }

    public S3DOrganism mutateSexually(Mutator mutator, AbstractOrganism otherParent) {
        S3DOrganism other = (S3DOrganism) otherParent;
        List<Node> newRoots = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            newRoots.add(mutator.mateNodeTrees(_roots.get(i), other._roots.get(i)));
        }

        int[] rgb1 = RgbHsv.HSVtoRGB(_color[0], _color[1], VALUE);
        int[] rgb2 = RgbHsv.HSVtoRGB(other._color[0], other._color[1], VALUE);

        int[] newRgb = new int[3];
        for (int i = 0; i < 3; i++) {
            newRgb[i] = (rgb1[i] + rgb2[i]) / 2;
        }
        float [] hsv = RgbHsv.RGBtoHSV(newRgb[0], newRgb[1],newRgb[2] );

        return new S3DOrganism(newRoots, new float[]{hsv[0],hsv[1],(float)VALUE});
    }

    public Color color() {
        int[] rgb = RgbHsv.HSVtoRGB(_color[0], _color[1], VALUE);
        return new Color(rgb[0], rgb[1], rgb[2]);
    }
    public List<Node> nodes(){
        return _roots;
    }
}

