import java.util.*;

public class Service {
    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);
        System.out.println("Enter three points for a triangle: ");

        double x1 = input.nextDouble();
        double y1 = input.nextDouble();
        double x2 = input.nextDouble();
        double y2 = input.nextDouble();
        double x3 = input.nextDouble();
        double y3 = input.nextDouble();

        double s1 = findSide(x1, y1, x2, y2);
        double s2 = findSide(x2, y2, x3, y3);
        double s3 = findSide(x1, y1, x3, y3);

        double s = (s1 + s2 + s3) / 2;

        double area = Math.sqrt((s * (s - s1) * (s - s2) * (s - s3)));

        System.out.println("The area of the triangle is: " + area);
    }

    public static double findSide(double x0, double y0, double x1, double y1) {
        return Math.pow(Math.pow(x0 - x1, 2) + Math.pow(y0 - y1, 2), 0.5);
    }

}

public class MyCharacter {
    private char ch;

    public MyCharacter(char ch) {
        this.ch = ch;
    }

    public char getChar() {
        return ch;
    }

    public int compareTo(MyCharacter otherChar) {
        return (int) ch - (int) otherChar.getChar();
    }

    public static MyCharacter valueOf(char ch) {
        return new MyCharacter(ch);
    }

    public boolean isDigit() {
        return ch >= '0' && ch <= '9';
    }

    public boolean isLetter() {
        return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
    }

    public boolean isLowerCase() {
        return ch >= 'a' && ch <= 'z';
    }

    public boolean isUpperCase() {
        return ch >= 'A' && ch <= 'Z';
    }

    public boolean isWhitespace() {
        return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' || ch == '\f';
    }

    public MyCharacter toLowerCase() {
        if (isUpperCase()) {
            return new MyCharacter((char) (ch + 32));
        } else {
            return this;
        }
    }

    public MyCharacter toUpperCase() {
        if (isLowerCase()) {
            return new MyCharacter((char) (ch - 32));
        } else {
            return this;
        }
    }
}

import com.jroossien.boxx.options.SingleOption;
import com.jroossien.boxx.util.entity.EntityParser;
