import org.bukkit.command.CommandSender;

public class EntityStackO extends SingleOption<EntityStack, EntityStackO> {

    private Integer maxEntities = null;
    private boolean allowStacked = true;

    public EntityStackO max(Integer maxEntities) {
        this.maxEntities = maxEntities;
        return this;
    }

    public EntityStackO allowStacked(boolean allowStacked) {
        this.allowStacked = allowStacked;
        return this;
    }

    @Override
    public boolean parse(CommandSender sender, String input) {
        EntityParser parser = new EntityParser(input, sender, false, maxEntities, allowStacked);
        if (!parser.isValid()) {
            error = parser.getError();
            return false;
        }
        value = parser.getEntities();
        return true;
    }

    @Override
    public String serialize() {
        return serialize(getValue());
    }

    public static String serialize(EntityStack entityStack) {
        return entityStack == null ? null : new EntityParser(entityStack.getBottom()).getString();
    }

    @Override
    public String getTypeName() {
        return "EntityStack";
    }

    @Override
    public EntityStackO clone() {
        return super.cloneData(new EntityStackO().max(maxEntities).allowStacked(allowStacked));
    }
}

public Cell convertBsonToCell(BsonObject bsonObject, String tableName) throws IllegalAccessException, InstantiationException, InvocationTargetException {
    Cell cell = new Cell(tableName);
    for (Map.Entry<String, Object> entry : bsonObject.entrySet()) {
        String fieldName = entry.getKey();
        Object fieldValue = entry.getValue();
        DeepAnnotation deepAnnotation = getDeepAnnotation(fieldValue);
        if (deepAnnotation != null) {
            String nestedTableName = deepAnnotation.tableName();
            Cell nestedCell = convertBsonToCell((BsonObject) fieldValue, nestedTableName);
            cell.addCell(nestedCell);
            fieldValue = nestedCell.getId();
        }
        cell.addValue(fieldName, fieldValue);
    }
    return cell;
}

private DeepAnnotation getDeepAnnotation(Object fieldValue) {
    if (fieldValue instanceof BsonObject) {
        BsonObject bsonObject = (BsonObject) fieldValue;
        if (bsonObject.containsKey(DEEP_FIELD_NAME)) {
            return bsonObject.getValue(DEEP_FIELD_NAME, DeepAnnotation.class);
        }
    }
    return null;
}

