private static final int CAMERA_PERMISSION_CODE = 100;

private void requestCameraPermission() {
    if (ActivityCompat.shouldShowRequestPermissionRationale(this, Manifest.permission.CAMERA)) {
        new android.app.AlertDialog.Builder(this)
                .setTitle("Permission needed")
                .setMessage("This permission is needed because of this and that")
                .setPositiveButton("ok", new DialogInterface.OnClickListener() {
                    @Override
                    public void onClick(DialogInterface dialog, int which) {
                        dialog.cancel();
                        ActivityCompat.requestPermissions(MainActivity.this, new String[]{Manifest.permission.CAMERA}, CAMERA_PERMISSION_CODE);
                    }
                })
                .setNegativeButton("cancel", new DialogInterface.OnClickListener() {
                    @Override
                    public void onClick(DialogInterface dialog, int which) {
                        dialog.cancel();
                    }
                })
                .show();
    } else {
        ActivityCompat.requestPermissions(MainActivity.this, new String[]{Manifest.permission.CAMERA}, CAMERA_PERMISSION_CODE);
    }
}

import java.io.PrintWriter;
import java.net.Socket;
import java.util.Scanner;

/**
 * Reads lines from the console, sends each one to the uppercasing
 * server, and prints back whatever the server replies with.
 */
public class CapitalizeClient {

    private static final String HOST = "localhost";
    private static final int PORT = 59898;

    public static void main(String[] args) throws Exception {

        try (var connection = new Socket(HOST, PORT)) {

            System.out.println("Metin satirlarini girin, cikis yapmak icin Ctrl+D veya Ctrl+C kullanin");

            try (var keyboard = new Scanner(System.in)) {
                var fromServer = new Scanner(connection.getInputStream());
                var toServer = new PrintWriter(connection.getOutputStream(), true);

                while (keyboard.hasNextLine()) {
                    toServer.println(keyboard.nextLine());
                    System.out.println(fromServer.nextLine());
                }
            }
        }
    }
}

