import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Class CartController
 */
@WebServlet(urlPatterns="/orders/view/*")
public class ViewController extends BaseOrderController {
    @Override
    protected void processRequest(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        UserUtil userUtil = new UserUtil(request.getSession());

        Order order = findResource(request);
        if (order == null) {
            forward404(request, response);
            return;
        }

        // Check permission
        if (!userUtil.isAdmin() && order.getUserId() != userUtil.getUser().getId()) {
            forward403(request, response);
            return;
        }

        OrderBookDAO orderBookDAO = DbUtil.getDAO(OrderBookDAO.class);
        BookDAO bookDAO = DbUtil.getDAO(BookDAO.class);
        UserDAO userDAO = DbUtil.getDAO(UserDAO.class);

        double orderAmount = 0d;

        // Set order books and book detail
        List<OrderBook> orderBookList = orderBookDAO.findAllByOrder(order.getId());
        for (OrderBook book : orderBookList) {
            Book bookDetail;
            if ((bookDetail = bookDAO.find(book.getBookId())) != null) {
                book.setBook(bookDetail);
            } else {
                book.setBook(new Book(0, 0, "Removed Book", "", "", 0, 0, "", ""));
            }
            orderAmount += book.getCount() * book.getBook().getPrice();
        }
        order.setBookList(orderBookList);

        User orderUser = userDAO.find(order.getUserId());

        request.setAttribute("order", order);
        request.setAttribute("orderBookList", orderBookList);
        request.setAttribute("orderAmount", orderAmount);
        request.setAttribute("orderUser", orderUser);
        forward(request, response, "/orders/view.jsp");
    }
}

import java.util.*;
 
abstract class HuffmanTree implements Comparable<HuffmanTree> {
    public final int frequency; // the frequency of this tree
    public HuffmanTree(int freq) { frequency = freq; }
 
    // compares on the frequency
    public int compareTo(HuffmanTree tree) {
        return frequency - tree.frequency;
    }
}
 
class HuffmanLeaf extends HuffmanTree {
    public final char value; // the character this leaf represents
 
    public HuffmanLeaf(int freq, char val) {
        super(freq);
        value = val;
    }
}
 
class HuffmanNode extends HuffmanTree {
    public final HuffmanTree left, right; // subtrees
 
    public HuffmanNode(HuffmanTree l, HuffmanTree r) {
        super(l.frequency + r.frequency);
        left = l;
        right = r;
    }
}
 
public class HuffmanCode {
    // input is an array of frequencies, indexed by character code
    public static HuffmanTree buildTree(int[] charFreqs) {
        PriorityQueue<HuffmanTree> trees = new PriorityQueue<HuffmanTree>();
        // initially, we have a forest of leaves
        // one for each non-empty character
        for (int i = 0; i < charFreqs.length; i++)
            if (charFreqs[i] > 0)
                trees.offer(new HuffmanLeaf(charFreqs[i], (char)i));
 
        assert trees.size() > 0;
        // loop until there is only one tree left
        while (trees.size() > 1) {
            // two trees with least frequency
            HuffmanTree a = trees.poll();
            HuffmanTree b = trees.poll();
 
            // put into new node and re-insert into queue
            trees.offer(new HuffmanNode(a, b));
        }
        return trees.poll();
    }
 
    public static void printCodes(HuffmanTree tree, StringBuffer prefix) {
        assert tree != null;
        if (tree instanceof HuffmanLeaf) {
            HuffmanLeaf leaf = (HuffmanLeaf)tree;
 
            // print out character, frequency, and code for this leaf (which is just the prefix)
            System.out.println(leaf.value + "\t" + leaf.frequency + "\t" + prefix);
 
        } else if (tree instanceof HuffmanNode) {
            HuffmanNode node = (HuffmanNode)tree;
 
            // traverse left
            prefix.append('0');
            printCodes(node.left, prefix);
            prefix.deleteCharAt(prefix.length()-1);
 
            // traverse right
            prefix.append('1');
            printCodes(node.right, prefix);
            prefix.deleteCharAt(prefix.length()-1);
        }
    }
 
    public static void main(String[] args) {
        String test = "this is an example for huffman encoding";

