        }
    }

 
public class Unbiased {
    public static boolean biased(int n) {
        return Math.random() < 1.0 / n;
    }
 
    public static boolean unbiased(int n) {
        boolean a;
        boolean b;
        do {
            a = biased(n);
            b = biased(n);
        } while (a == b);
        return a;
    }
 
    public static void main(String[] args) {
        int m = 50_000;
        String f = "%d: %2.2f%%  %2.2f%%";
        for (int n = 3; n <= 6; n++) {
            int c1 = 0;
            int c2 = 0;
            for (int i = 0; i < m; i++) {
                if (biased(n)) c1++;
                if (unbiased(n)) c2++;
            }
            System.out.println(String.format(f, n, 100.0 * c1 / m, 100.0 * c2 / m));
        }
    }
}

private int getIndex(CharSequence name) {
        if (length() == 0 || name == null) {
            return -1;
        }
        int h = AsciiString.hashCode(name);
        int i = index(h);
        for (HeaderEntry e = headerFields[i]; e != null; e = e.next) {
            if (e.hash == h && equalsConstantTime(name, e.name) != 0) {
                return getIndex(e.index);
            }
        }
        return -1;
    }

import java.lang.ref.Reference;
import java.lang.ref.ReferenceQueue;
import java.lang.ref.WeakReference;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.function.Function;

public class ConcurrentWeakKeyWeakValueHashMap<K, V> extends ConcurrentHashMap<K, ConcurrentWeakKeyWeakValueHashMap.WeakValue<V>> {

    private final ReferenceQueue<K> myKeyQueue = new ReferenceQueue<>();
    private final ReferenceQueue<V> myValueQueue = new ReferenceQueue<>();
    private final Function<? super K, ? extends K> myHashingStrategy;

    public ConcurrentWeakKeyWeakValueHashMap(Function<? super K, ? extends K> hashingStrategy) {
        this.myHashingStrategy = hashingStrategy;
    }

    @Override
    public WeakValue<V> put(K key, WeakValue<V> value) {
        if (key == null || value == null || value.get() == null) {
            throw new NullPointerException();
        }
        processQueue(myKeyQueue);
        processQueue(myValueQueue);
        return super.put(createKeyReference(key, myKeyQueue), value);
    }

    @Override
    public WeakValue<V> get(Object key) {
        processQueue(myKeyQueue);
        processQueue(myValueQueue);
        return super.get(createKeyReference((K) key, null));
    }

    @Override
    public WeakValue<V> remove(Object key) {
        processQueue(myKeyQueue);
        processQueue(myValueQueue);
        return super.remove(createKeyReference((K) key, null));
    }

    private void processQueue(ReferenceQueue<?> queue) {
        Reference<?> ref;
        while ((ref = queue.poll()) != null) {
            remove(ref);
        }
    }

    private WeakReference<K> createKeyReference(K key, ReferenceQueue<K> queue) {
        return new WeakReference<>(myHashingStrategy.apply(key), queue);
    }

    public static class WeakValue<V> extends WeakReference<V> {
        private final int hashCode;

        public WeakValue(V referent, ReferenceQueue<V> q) {
            super(referent, q);
            hashCode = System.identityHashCode(referent);
        }

        @Override
        public int hashCode() {
            return hashCode;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            WeakValue<?> weakValue = (WeakValue<?>) obj;
            V v = get(), v1 = weakValue.get();
            return v != null && v.equals(v1);
        }
    }

import com.google.gson.JsonObject;

public class SlackMessage {
    private String _username;
    private String _icon;
    private String _content;

    // Default icon provided by SlackAPI
    private static final String DEFAULT_ICON = ":robot_face:";

    // Constructor initializing content only
    public SlackMessage(String content) {
        this(null, null, content);
    }

    // Constructor initializing content and username
    public SlackMessage(String username, String content) {
        this(username, null, content);
    }

    // Constructor initializing content, username, and icon
    public SlackMessage(String username, String icon, String content) {
        this._username = username;
        this._icon = (icon != null) ? ":" + icon + ":" : DEFAULT_ICON;
        this._content = content;
    }

    // Getter for username
    public String getUsername() {
        return _username;
    }

    // Setter for username
    public void setUsername(String username) {
        this._username = username;
    }

    // Getter for icon
    public String getIcon() {
        return _icon;
    }

    // Setter for icon
    public void setIcon(String icon) {
        this._icon = (icon != null) ? ":" + icon + ":" : DEFAULT_ICON;
    }

    // Getter for content
    public String getContent() {
        return _content;
    }

    // Setter for content
    public void setContent(String content) {
        this._content = content;
    }

    // Method to convert the message to a JSON object
    public JsonObject toJson() {
        JsonObject jsonObject = new JsonObject();

        if (_username != null && !_username.isEmpty()) {
            jsonObject.addProperty("username", _username);
        }

        if (_icon != null && !_icon.isEmpty()) {
            jsonObject.addProperty("icon_emoji", _icon);
        }

        if (_content != null && !_content.isEmpty()) {
            jsonObject.addProperty("text", _content);
        }

        return jsonObject;
    }

    // Main method for testing purposes
    public static void main(String[] args) {
        // Test with content only
        SlackMessage message1 = new SlackMessage("Hello, Slack!");
        System.out.println("Message 1: " + message1.toJson().toString());

        // Test with content and username
        SlackMessage message2 = new SlackMessage("JohnDoe", "Hello, Slack!");
        System.out.println("Message 2: " + message2.toJson().toString());

        // Test with content, username, and icon
        SlackMessage message3 = new SlackMessage("JohnDoe", "smiley", "Hello, Slack!");

