import java.util.Arrays;
import java.util.Comparator;

public class Validator {
    public static int maxEqualFreq(int[] nums) {
        int pre = 0;
        Arrays.sort(nums);
        int min = nums[0], max = 0, max_count = 1, min_count = 1;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] != nums[i - 1]) {
                max = Math.max(max, min);
                min++; // Ensure record the frequent of current number
                min_count += i - pre - 1; // record all possible less frequent
                max_count = 0;
            }
            max_count++;
            pre = i;
        }

        int sum = 0;
        if (max_count >= min_count && max == min) {
            return sum + max;
        }
        if (max_count >= max_count && max == max) {
            return sum + max;
        }
        if (max_count + 1 >= min_count && max == min && max == (max_count + 1)) {
            return sum + max;
        }

        int[] freqArr = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            freqArr[i] = Arrays.binarySearch(nums, 0, i + 1, nums[i]);
            if (freqArr[i] < 0) freqArr[i] = ~freqArr[i];
        }

        Arrays.sort(freqArr, Comparator.reverseOrder());

        for (int i = 1; i < nums.length; i++) {
            if (freqArr[i] < max_count || freqArr[i] > max_count + 1) return sum;
            if (freqArr[i] >= max_count + 2) {
                sum += max * (i - 1);
                break;
            }
            sum += max;
        }
        return sum + nums[nums.length - 1];
    }

    public static void main(String[] args) {
        int[] nums = { 2, 1, 3, 4, 5, 2 };
        System.out.println(maxEqualFreq(nums));

        nums = new int[] { 2, 3, 5, 1, 3, 2 };
        System.out.println(maxEqualFreq(nums));

    }
}

