import java.util.Iterator;
import java.util.List;
import java.util.ArrayList;
import java.util.ListIterator;
import java.util.Comparator;
import java.util.Collections;
import java.util.Arrays;
 
// helper struct
class referring<T> {
  referring(T t) { value = t; }
  boolean operator(Pair<Iterator<T>, Integer> p) {
    return p.first.equals(value);
  }
  T value;
}
 
// requires:
// FwdIterator is a ForwardIterator
// The value_type of FwdIterator is EqualityComparable
// OutIterator is an output iterator
// the value_type of FwdIterator is convertible to the value_type of OutIterator
// [first, last) is a valid range
// provides:
// the mode is written to result
public static <FwdIterator, OutIterator> void mode(FwdIterator first, FwdIterator last, OutIterator result) {
  // count elements
  List<Pair<FwdIterator, Integer>> counts = new ArrayList<Pair<FwdIterator, Integer>>();
 
  while (first!= last) {
    Iterator<Pair<FwdIterator, Integer>> element = Collections.find(counts, new referring<FwdIterator>(first));
    if (element == null)
      counts.add(new Pair<FwdIterator, Integer>(first, 1));
    else
      element.second++;
    first++;
  }
 
  // find maximum
  int max = 0;
  for (Iterator<Pair<FwdIterator, Integer>> i = counts.iterator(); i.hasNext(); ) {
    Pair<FwdIterator, Integer> p = i.next();
    if (p.second > max)
      max = p.second;
  }
 
  // copy corresponding elements to output sequence
  for (Iterator<Pair<FwdIterator, Integer>> i = counts.iterator(); i.hasNext(); ) {
    Pair<FwdIterator, Integer> p = i.next();
    if (p.second == max)
      result.add(p.first);
  }
}
 
// example usage
public static void main(String[] args) {
  int[] values = { 1, 2, 3, 1, 2, 4, 2, 5, 2, 3, 3, 1, 3, 6 };
  mode(values, values + values.length, System.out);
  System.out.println();
}

public class SumSeries {
    public static void main(String[] args) {
        int n = 50000;
        double sumLR = 0.0; // sum from left to right
        double sumRL = 0.0; // sum from right to left

        // Compute sum from left to right
        for (int i = 1; i <= n; i += 2) {
            sumLR += (double)i / (i + 2);
        }

        // Compute sum from right to left
        for (int i = n; i >= 1; i -= 2) {
            sumRL += (double)i / (i + 2);
        }

        // Display results
        System.out.printf("Sum from left to right: %.5f\n", sumLR);
        System.out.printf("Sum from right to left: %.5f\n", sumRL);
    }
}

public class Intersection {
    private static class Point {
        double x, y;
 
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
 
        @Override
        public String toString() {
            return String.format("{%f, %f}", x, y);
        }
    }
 
    private static class Line {
        Point s, e;
 
        Line(Point s, Point e) {
            this.s = s;
            this.e = e;
        }
    }
 
    private static Point findIntersection(Line l1, Line l2) {
        double a1 = l1.e.y - l1.s.y;
        double b1 = l1.s.x - l1.e.x;
        double c1 = a1 * l1.s.x + b1 * l1.s.y;
 
        double a2 = l2.e.y - l2.s.y;
        double b2 = l2.s.x - l2.e.x;
        double c2 = a2 * l2.s.x + b2 * l2.s.y;
 
        double delta = a1 * b2 - a2 * b1;
        return new Point((b2 * c1 - b1 * c2) / delta, (a1 * c2 - a2 * c1) / delta);
    }
 
    public static void main(String[] args) {
        Line l1 = new Line(new Point(4, 0), new Point(6, 10));
        Line l2 = new Line(new Point(0, 3), new Point(10, 7));
        System.out.println(findIntersection(l1, l2));
 
        l1 = new Line(new Point(0, 0), new Point(1, 1));
        l2 = new Line(new Point(1, 2), new Point(4, 5));
        System.out.println(findIntersection(l1, l2));
    }
}

