class Order {
    public boolean canMakeAllElementsZero(int[] nums, int k) {
        Arrays.sort(nums);
        for(int i=k;i<nums.length;i++){
            int j = i-k, val = nums[j], cnt = 1, sum = 0;
            while(j < nums.length && nums[j] == val){
                sum += nums[j]-val;
                cnt++;
                j++;
            }
            if(sum/cnt >= val) return true;
        }
        return false;
    }
}

import com.l2fprod.common.swing.AbstractPropertyEditor;
import com.l2fprod.common.swing.ComponentFactory;
import com.l2fprod.common.swing.PercentLayout;
import com.l2fprod.common.swing.font.JFontChooser;
import com.l2fprod.common.util.ResourceManager;

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class FontPropertyEditor extends AbstractPropertyEditor {

    private JLabel label;
    private JButton button;
    private JButton clearButton;
    private Font font;
    private DefaultCellRenderer renderer;

    public FontPropertyEditor() {
        super(new JPanel());
        ((JPanel) getEditor()).setLayout(new PercentLayout(PercentLayout.VERTICAL, 0));
        ((JPanel) getEditor()).add(buildLabel(), "50%");
        ((JPanel) getEditor()).add(buildButtons(), "50%");
        renderer = new DefaultCellRenderer();
        setValue(null);
    }

    private Component buildLabel() {
        label = new JLabel();
        label.setHorizontalAlignment(JLabel.CENTER);
        label.setVerticalAlignment(JLabel.CENTER);
        return label;
    }

    private Component buildButtons() {
        JPanel panel = new JPanel(new PercentLayout(PercentLayout.HORIZONTAL, 0));
        button = ComponentFactory.createSmallButton();
        button.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                selectFont();
            }
        });
        button.setText("Select Font");

        clearButton = ComponentFactory.createSmallButton();
        clearButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                selectNull();
            }
        });
        clearButton.setText("Clear");

        panel.add(button, "50%");
        panel.add(clearButton, "50%");
        return panel;
    }

    @Override
    public Object getValue() {
        return font;
    }

    @Override
    public void setValue(Object value) {
        if (value instanceof Font) {
            font = (Font) value;
            updateLabel();
        } else {
            font = null;
            label.setText("No Font Selected");
        }
        firePropertyChange();
    }

    private void selectFont() {
        JFontChooser chooser = new JFontChooser();
        chooser.setSelectedFont(font);
        int result = chooser.showDialog(getEditor());
        if (result == JFontChooser.OK_OPTION) {
            setValue(chooser.getSelectedFont());
        }
    }

