public class LALParserTest {
    private LALParser parser;
    private File simpleFile;
    private File complexFile;
    private Login expectedSimpleLogin;
    private List<Login> expectedComplexLogins;

    @Before
    public void setUp() {
        parser = new LALParser();
        simpleFile = new File("testdata/simple_login.txt");
        complexFile = new File("testdata/complex_logins.txt");

        expectedSimpleLogin = new Login(
            "basic_user",
            "plain_pass",
            null,
            false
        );

        expectedComplexLogins = Arrays.asList(
            new Login("admin", "P@ssw0rd!", "System Administrator", true),
            new Login("john_doe", "j0hnd03!", "John Doe", false),
            new Login("guest", "guest1234", null, true),
            new Login("audit_user", "audit_sec", "Audit Account", false)
        );
    }

    @Test(expected = IllegalArgumentException.class)
    public void testNullInputHandling() {
        parser.parse(null);
    }

    @Test
    public void testFileParseSimple() throws Exception {
        List<Login> parsedLogins = parser.parse(simpleFile);
        assertEquals("Should parse exactly 1 login entry", 1, parsedLogins.size());
        assertTrue("Parsed login mismatch",
            parsedLogins.get(0).strictEquals(expectedSimpleLogin));
    }

    @Test
    public void testFileParseComplex() throws Exception {
        List<Login> parsedLogins = parser.parse(complexFile);
        assertEquals("Incorrect number of parsed entries",
            expectedComplexLogins.size(), parsedLogins.size());

        for (int i = 0; i < expectedComplexLogins.size(); i++) {
            Login expected = expectedComplexLogins.get(i);
            Login actual = parsedLogins.get(i);
            assertTrue(String.format(
                "Entry %d mismatch\nExpected: %s\nActual: %s",
