import org.springframework.shell.core.annotation.CliCommand;

import org.apache.geode.management.cli.CliMetaData;
import org.apache.geode.management.internal.cli.LogWrapper;
import org.apache.geode.management.internal.cli.i18n.CliStrings;
import org.apache.geode.management.internal.cli.result.model.InfoResultModel;
import org.apache.geode.management.internal.cli.result.model.ResultModel;
import org.apache.geode.management.internal.cli.shell.Gfsh;
import org.apache.geode.management.internal.cli.shell.OperationInvoker;

public class DisconnectCommand extends OfflineGfshCommand {
  @CliCommand(value = {CliStrings.DISCONNECT}, help = CliStrings.DISCONNECT__HELP)
  @CliMetaData(shellOnly = true, relatedTopic = {CliStrings.TOPIC_GFSH, CliStrings.TOPIC_GEODE_JMX,
      CliStrings.TOPIC_GEODE_MANAGER})
  public ResultModel disconnect() {

    if (getGfsh() != null && !getGfsh().isConnectedAndReady()) {
      return ResultModel.createInfo("Not connected.");
    }

    ResultModel result = new ResultModel();
    InfoResultModel infoResultData = result.addInfo();

    Gfsh gfshInstance = getGfsh();
    if (gfshInstance.isConnectedAndReady()) {
      OperationInvoker operationInvoker = gfshInstance.getOperationInvoker();
      Gfsh.println("Disconnecting from: " + operationInvoker);
      operationInvoker.stop();
      infoResultData.addLine(CliStrings.format(CliStrings.DISCONNECT__MSG__DISCONNECTED,
          operationInvoker.toString()));
      LogWrapper.getInstance().info(CliStrings
          .format(CliStrings.DISCONNECT__MSG__DISCONNECTED, operationInvoker.toString()));
      if (!gfshInstance.isHeadlessMode()) {
        gfshInstance.setPromptPath(gfshInstance.getEnvAppContextPath());
      }
    } else {
      infoResultData.addLine(CliStrings.DISCONNECT__MSG__NOTCONNECTED);
    }

    return result;
  }
}

private static String getCharsetFromMeta(byte buffer[], int maxlength) {

        int len = buffer.length;
        if (maxlength > 0 && maxlength < len) {
            len = maxlength;
        }
        String html = new String(buffer, 0, len, DEFAULT_CHARSET);
        Document doc = Parser.htmlParser().parseInput(html, "dummy");

        Elements metaElements = doc
                .select("meta[http-equiv=content-type], meta[charset]");
        String foundCharset = null;
        for (Element meta : metaElements) {
            if (meta.hasAttr("http-equiv"))
                foundCharset = getCharsetFromContentType(meta.attr("content"));
            if (foundCharset == null && meta.hasAttr("charset"))
                foundCharset = meta.attr("charset");
            if (foundCharset != null)
                return foundCharset;
        }
        return foundCharset;
    }

/*
 * Represents a post office with a name and phone number, and
 * demonstrates wiring it together with Kisi and Adres objects.
 */
public class Postane {

    private String kurumAdi;
    private String iletisimNumarasi;

    public Postane(String kurumAdi, String iletisimNumarasi) {
        this.kurumAdi = kurumAdi;
        this.iletisimNumarasi = iletisimNumarasi;
    }

    public String getAd() {
        return kurumAdi;
    }

    public String getTelefonNumarasi() {
        return iletisimNumarasi;
    }

    // Prints the post office's name and contact number.
    public void postaneyiTanit() {
        System.out.println("Postane Adi: " + kurumAdi + ", Telefon Numarasi: " + iletisimNumarasi);
    }

    public static void main(String[] args) {

        // Person details
        String kisiIsmi = "Ahmet";
        int kisiYasi = 30;

        // Address details
        String caddeBilgisi = "Mevlana Caddesi No:5";
        String sehirBilgisi = "Konya";
        String postaKoduBilgisi = "42030";
        String ulkeBilgisi = "Turkiye";

        Adres adresBilgisi = new Adres(caddeBilgisi, sehirBilgisi, postaKoduBilgisi, ulkeBilgisi);

        Kisi kisiBilgisi = new Kisi(kisiIsmi, kisiYasi, adresBilgisi);

        kisiBilgisi.kisiyiTanit();

        // Post office details
        String postaneIsmi = "Konya Postanesi";
        String postaneTelefonu = "0332 123 45 67";

        Postane postaneBilgisi = new Postane(postaneIsmi, postaneTelefonu);

        postaneBilgisi.postaneyiTanit();

        adresBilgisi.adresiYazdir();

        System.out.println("Kisinin yasini kontrol edelim. 18 yasindan buyuk mu?");
        if (kisiBilgisi.getYas() > 18) {
            System.out.println(kisiBilgisi.getIsim() + " 18 yasindan buyuk.");
        } else {
            System.out.println(kisiBilgisi.getIsim() + " 18 yasindan kucuk.");
        }
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Tree {
    public boolean leafSimilar(TreeNode root1, TreeNode root2) {
        List<Integer> leaves1 = new ArrayList<>();
        List<Integer> leaves2 = new ArrayList<>();
        getLeaves(root1, leaves1);
        getLeaves(root2, leaves2);
        return leaves1.equals(leaves2);
    }

    private void getLeaves(TreeNode node, List<Integer> leaves) {
        if (node == null) return;
        if (node.left == null && node.right == null) leaves.add(node.val);
        getLeaves(node.left, leaves);
        getLeaves(node.right, leaves);
    }
}

import java.lang.StringBuilder;

public class Gapful {
    private static String commatize(long n) {
        StringBuilder sb = new StringBuilder(Long.toString(n));
        int le = sb.length();
        int i = le - 3;
        while (i >= 1) {
            sb.insert(i, ',');
            i -= 3;
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        long[] starts = {100, 1000000, 10000000, 1000000000, 7123};
        int[] counts = {30, 15, 15, 10, 25};
        for (int i = 0; i < starts.length; i++) {
            int count = 0;
            long j = starts[i];
            long pow = 100;
            while (j >= pow * 10) {
                pow *= 10;
            }
            System.out.printf(
                "First %d gapful numbers starting at %s:\n",
                counts[i],
                commatize(starts[i])
            );
            while (count < counts[i]) {
                long fl = j / pow * 10 + j % 10;
                if (j % fl == 0L) {
                    System.out.printf("%d ", j);
                    count++;
                }
                j++;
                if (j >= 10 * pow) {
                    pow *= 10;
                }
            }
            System.out.println();
        }
    }
}

class Calculator {
    public int returnToBoundaryCount(int[] nums) {

        int count = 0;

        int sum = 0;

        for (int num : nums) {
            sum += num;

            if (sum == 0)
                ++count;
        }

        return count;
    }
}

