import java.util.Scanner;

public class MaxAdjacentPairTime {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n];

        // Read array input
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        // Initialize variables
        int maxValue = 0;
        int currentValue = 0;
        int lastNonZero = -1;

        // Fill array with maximum possible values
        for (int i = 0; i < n; i++) {
            if (a[i] != 0 && i > 0) {
                // When encountering adjacent non-zero elements, select the larger one
                currentValue = Math.max(currentValue + 1, a[i]);
            } else {
                // Assign value to elements equal to lastNonZero + 1
                currentValue = lastNonZero + 1;
                if (lastNonZero != -1) {
                    maxValue += (int) Math.pow(2, lastNonZero - 1);
                }
            }

            // Update lastNonZero to the current non-zero element
            lastNonZero = a[i];

            // Fill remaining elements with remaining count of powers of 2
            int remainingPowersOfTwo = 0;
            while (remainingPowersOfTwo <= n - i - 1) {
                remainingPowersOfTwo *= 2;
            }
            currentValue += remainingPowersOfTwo;

            // Assign currentValue to the current index
            a[i] = currentValue;
        }

        // Output the array with maximum value
        for (int value : a) {
            System.out.print(value + " ");
        }
    }
}

import java.util.Scanner;

public class Reader {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter three integers
        System.out.print("Enter three integers: ");
        int num1 = input.nextInt();
        int num2 = input.nextInt();
        int num3 = input.nextInt();

        // Determine the order of the integers
        int temp;
        if (num1 > num2) {
            temp = num1;
            num1 = num2;
            num2 = temp;
        }
        if (num2 > num3) {
            temp = num2;
            num2 = num3;
            num3 = temp;
        }
        if (num1 > num2) {
            temp = num1;
            num1 = num2;
            num2 = temp;
        }

        // Display the integers in non-decreasing order
        System.out.println("The integers in non-decreasing order are: " + num1 + " " + num2 + " " + num3);
    }
}

