import java.util.*;

public class Library {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] w = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            w[i] = sc.nextInt();
        }
        List<Friend> friends = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            friends.add(new Friend(x, y, i + 1));
        }
        friends.sort(Comparator.comparingInt(Friend::getTypeMin));
        boolean survived = true;
        List<Integer> order = new ArrayList<>();
        for (Friend friend : friends) {
            if (w[friend.getType1()] > 0 && w[friend.getType2()] > 0) {
                w[friend.getType1()]--;
                w[friend.getType2()]--;
                order.add(friend.getId());
            } else if (w[friend.getType1()] > 0 || w[friend.getType2()] > 0) {
                w[Math.max(friend.getType1(), friend.getType2())]--;
                order.add(friend.getId());
            } else {
                survived = false;
                break;
            }
        }
        if (survived) {
            System.out.println("ALIVE");
            System.out.println(order.stream().map(String::valueOf).collect(Collectors.joining(" ")));
        } else {
            System.out.println("DEAD");
        }
        sc.close();
    }

    static class Friend {
        private final int type1;
        private final int type2;
        private final int id;

        public Friend(int type1, int type2, int id) {
            this.type1 = type1;
            this.type2 = type2;
            this.id = id;
        }

        public int getType1() {
            return type1;
        }

        public int getType2() {
            return type2;
        }

        public int getTypeMin() {
            return Math.min(type1, type2);
        }

        public int getId() {
            return id;
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class KaprekarNumbers {

    /**
     * The entry point of the program, where the program control starts and ends.
     */
    public static void main(String[] args) {
        int count = 0;

        for (Long i : _kaprekarGenerator(999999)) {
            System.out.println(i);
            count++;
        }

        System.out.println("There are " + count + " Kaprekar numbers less than 1000000.");
    }

    /**
     * Generator function which generates the Kaprekar numbers.
     *
     * @return The generator.
     * @param max The maximum value of the numbers generated.
     */
    private static List<Long> _kaprekarGenerator(long max) {

        List<Long> result = new ArrayList<Long>();

        long next = 1;

        // 1 is always a Kaprekar number.
        result.add(next);

        for (next = 2; next <= max; next++) {

            long square = next * next;

            for (long check = 10; check <= 10000000000000000000L; check *= 10) {
                // Check the square against each power of 10 from 10^1 to 10^19 (highest which can be
                // represented by a long)

                // If the power of 10 to be checked against is greater than or equal to the square, stop checking
                if (square <= check)
                    break;

                // Given a power of 10 as 10^n, the remainder when dividing the square number by that power
                // of 10 is equal to the last n digits of the number (starting from the right) and the
                // quotient gives the remaining digits.
                // If the last n digits are all zeroes, then the remainder will be zero, which is not
                // accepted.

                long r = square % check;
                long q = (square - r) / check;

                if (r!= 0 && q + r == next) {
                    result.add(next);
                    break;
                }
            }

        }

        return result;

    }

}

