import com.google.common.base.Preconditions;
import com.google.common.io.ByteStreams;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.CRC32;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

class ZipOutputFileProvider implements OutputFileProvider {

  private final Path root;
  private final ZipOutputStream out;
  private boolean closed = false;

  public ZipOutputFileProvider(Path root) throws IOException {
    this.root = root;
    Files.createDirectories(root.getParent());
    this.out = new ZipOutputStream(Files.newOutputStream(root));
  }

  @Override
  public void copyFrom(String entryName, InputFileProvider input) throws IOException {
    Preconditions.checkState(!closed);
    try (InputStream is = input.getInput(entryName)) {
      ZipEntry entry = new ZipEntry(entryName);
      entry.setTime(0); // Use stable timestamp.
      out.putNextEntry(entry);
      ByteStreams.copy(is, out);
      out.closeEntry();
    }
  }

  @Override
  public void write(String entryName, byte[] content) throws IOException {
    writeStoredEntry(entryName, content, 0);
  }

  private void writeStoredEntry(String entryName, byte[] content, long time) throws IOException {
    Preconditions.checkState(!closed);
    CRC32 crc = new CRC32();
    crc.update(content);
    ZipEntry entry = new ZipEntry(entryName);
    entry.setTime(time); // Use stable timestamp.
    entry.setSize(content.length);
    entry.setCrc(crc.getValue());
    entry.setMethod(ZipEntry.STORED);
    entry.setCompressedSize(content.length);

    out.putNextEntry(entry);
    out.write(content);
    out.closeEntry();
  }

  @Override
  public void close() throws IOException {
    if (!closed) {
      out.close();
      closed = true;
    }
  }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.input.KeyCode;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

public class Service extends Application {
    static final double WIDTH = 400;
    static final double HEIGHT = 250;
    double x;
    double y;

    @Override
    public void start(Stage primaryStage) throws Exception {
        x = WIDTH / 2; // Start at the Center X
        y = HEIGHT / 2; // Start at the Center Y
        Pane pane = new Pane();
        Canvas canvas = new Canvas(WIDTH, HEIGHT);
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.moveTo(x, y);
        gc.setFill(Color.BLACK);
        gc.setLineWidth(3);
        pane.getChildren().add(canvas);
        Scene scene = new Scene(pane, WIDTH, HEIGHT);

        scene.setOnKeyPressed(e -> {
            KeyCode keyCode = e.getCode();
            double addX = 0, addY = 0;
            if (keyCode == KeyCode.UP) {
                addY -= 2;
            } else if (keyCode == KeyCode.DOWN) {
                addY += 2;
            } else if (keyCode == KeyCode.LEFT) {
                addX -= 2;
            } else if (keyCode == KeyCode.RIGHT) {
                addX += 2;
            }
            gc.lineTo(x + addX, y + addY);
            x += addX;
            y += addY;
            gc.stroke();

        });
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

