import java.io.IOException;
import java.io.PrintWriter;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Scanner;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Listens for client connections and hands each one off to a pooled
 * worker that echoes back every line in upper case.
 */
public class CapitalizeServer {

    private static final int PORT = 59898;
    private static final int MAX_WORKERS = 20;

    public static void main(String[] args) throws Exception {
        try (var serverSocket = new ServerSocket(PORT)) {
            System.out.println("Buyuk harfe cevirme sunucusu calisiyor...");

            ExecutorService workers = Executors.newFixedThreadPool(MAX_WORKERS);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                workers.execute(new UppercaseWorker(clientSocket));
            }
        }
    }

    // Handles a single client connection: reads lines, replies uppercased
    private static class UppercaseWorker implements Runnable {
        private final Socket clientSocket;

        UppercaseWorker(Socket clientSocket) {
            this.clientSocket = clientSocket;
        }

        @Override
        public void run() {
            System.out.println("Baglantili: " + clientSocket);
            try (var reader = new Scanner(clientSocket.getInputStream())) {
                var writer = new PrintWriter(clientSocket.getOutputStream(), true);

                while (reader.hasNextLine()) {
                    writer.println(reader.nextLine().toUpperCase());
                }
            } catch (Exception e) {
                System.out.println("Hata: " + clientSocket);
            } finally {
                try {
                    clientSocket.close();
                } catch (IOException e) {
                    System.out.println("Hata: " + clientSocket);
                }
                System.out.println("Kapatildi: " + clientSocket);
            }
        }
    }
}

