public interface ProcessesXml {

    class ProcessEngineXml {
        private String name;
        private String configuration;
        private boolean isDefault;

        public ProcessEngineXml(String name, String configuration, boolean isDefault) {
            this.name = name;
            this.configuration = configuration;
            this.isDefault = isDefault;
        }

        public String getName() {
            return name;
        }

        public String getConfiguration() {
            return configuration;
        }

        public boolean isDefault() {
            return isDefault;
        }
    }

    class ProcessArchiveXml {
        private String name;
        private String location;
        private boolean deploymentIsolation;
        private List<String> processResourceNames;

        public ProcessArchiveXml(String name, String location, boolean deploymentIsolation) {
            this.name = name;
            this.location = location;
            this.deploymentIsolation = deploymentIsolation;
            this.processResourceNames = new ArrayList<>();
        }

        public String getName() {
            return name;
        }

        public String getLocation() {
            return location;
        }

        public boolean isDeploymentIsolation() {
            return deploymentIsolation;
        }

        public List<String> getProcessResourceNames() {
            return processResourceNames;
        }

        public void addProcessResourceName(String resourceName) {
            processResourceNames.add(resourceName);
        }
    }

    List<ProcessEngineXml> getProcessEngines();

    List<ProcessArchiveXml> getProcessArchives();

    ProcessesXml EMPTY_PROCESSES_XML = new ProcessesXml() {
        @Override
        public List<ProcessEngineXml> getProcessEngines() {
            ProcessEngineXml defaultEngine = new ProcessEngineXml(
                "default",
                "org.camunda.bpm.engine.impl.cfg.StandaloneProcessEngineConfiguration",
                true
            );
            return Collections.singletonList(defaultEngine);
        }

        @Override
        public List<ProcessArchiveXml> getProcessArchives() {
            ProcessArchiveXml emptyArchive = new ProcessArchiveXml(
                "default-archive",
                "classpath:*/*.bpmn",
                false
            );
            return Collections.singletonList(emptyArchive);
        }
    };
}

