    catch (RecognitionException re) {
        reportError(re);
        recover(input,re);
    }
    finally {
        // do for sure before leaving
    }
}

import java.util.HashMap;
import java.util.Map;
 
public class ChineseZodiac {
 
    private static final Map<String, String> pinyin = new HashMap<String, String>();
    private static final String[] celestial = { "甲", "乙", "丙", "丁", "戊", "己", "庚", "辛", "壬", "癸" };
    private static final String[] terrestrial = { "子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥" };
    private static final String[] animals = { "Rat", "Ox", "Tiger", "Rabbit", "Dragon", "Snake", "Horse", "Goat", "Monkey", "Rooster", "Dog", "Pig" };
    private static final String[] elements = { "Wood", "Fire", "Earth", "Metal", "Water" };
    private static final String[] aspects = { "yang", "yin" };
 
    private static final int BASE = 4;
 
    public static void main(String[] args) {
        if (args.length == 0) {
            args = new String[] { String.valueOf(java.util.Calendar.getInstance().get(java.util.Calendar.YEAR)) };
        }
 
        for (String arg : args) {
            int ceYear = Integer.parseInt(arg);
            System.out.print(ceYear + ": ");
            int cycleYear = ceYear - BASE;
 
            int stemNumber = cycleYear % 10;
            String stemHan = celestial[stemNumber];
            String stemPinyin = pinyin.get(stemHan);
 
            int elementNumber = stemNumber / 2;
            String element = elements[elementNumber];
 
            int branchNumber = cycleYear % 12;
            String branchHan = terrestrial[branchNumber];
            String branchPinyin = pinyin.get(branchHan);
            String animal = animals[branchNumber];
 
            int aspectNumber = cycleYear % 2;
            String aspect = aspects[aspectNumber];
 
            int index = cycleYear % 60 + 1;
 
            System.out.println(stemHan + branchHan + " (" + stemPinyin + "-" + branchPinyin + ", " + element + " " + animal + "; " + aspect + " - year " + index + " of the cycle)");
        }
    }
}

