import java.io.*;
import java.util.List;
import java.util.stream.Collectors;

public class Handler {
    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: java Exercise18_30 dirName word");
            System.exit(0);
        }

        String directory = args[0];
        String oldWord = args[1];
        String newWord = args[2];

        File dir = new File(directory);

        if (dir.isDirectory()) {
            File[] files = dir.listFiles();
            if (files != null && files.length > 0) {
                try {
                    replaceWords(files, oldWord, newWord, 0);
                } catch (IOException ioException) {
                    ioException.printStackTrace();
                }
            }

        } else {
            System.out.println("Please specify a Directory for 'dirName'. ");
        }
        System.out.println("The word: \"" + oldWord + "\" has been replaced with \"" + newWord + "\" for files in " +
                "directory: " + dir.getName());

    }

    static void replaceWords(File[] files, String oldWord, String newWord, int fileIndex) throws IOException {
        if (files.length == fileIndex) {
            return;
        }
        runReplace(oldWord, newWord, files[fileIndex]);
        replaceWords(files, oldWord, newWord, fileIndex + 1); // Recurse
    }

    /* Method to perform replacement logic */
    static void runReplace(String oldWord, String newWord, File file) throws IOException {
        if (file.isFile()) {
            FileReader fileReader = new FileReader(file);
            BufferedReader bufferedReader = new BufferedReader(fileReader);
            List<String> resultList = bufferedReader.lines()
                    .map(s -> s.replace(oldWord, newWord))
                    .collect(Collectors.toList());

            bufferedReader.close();
            FileWriter fileWriter = new FileWriter(file);
            BufferedWriter bufferedWriter = new BufferedWriter(fileWriter);
            for (String line : resultList) {
                bufferedWriter.write(line);
                bufferedWriter.newLine();
            }
            bufferedWriter.close();
        }

    }

}

public class MyStringBuilder2 {
    private char[] value;
    private int count;

    public MyStringBuilder2() {
        value = new char[16];
    }

    public MyStringBuilder2(char[] chars) {
        value = chars;
        count = chars.length;
    }

    public MyStringBuilder2(String s) {
        value = s.toCharArray();
        count = s.length();
    }

    public MyStringBuilder2 insert(int offset, MyStringBuilder2 s) {
        if (offset < 0 || offset > count) {
            throw new StringIndexOutOfBoundsException(offset);
        }
        int len = s.length();
        ensureCapacity(count + len);
        System.arraycopy(value, offset, value, offset + len, count - offset);
        System.arraycopy(s.value, 0, value, offset, len);
        count += len;
        return this;
    }

    public MyStringBuilder2 reverse() {
        for (int i = 0, j = count - 1; i < j; i++, j--) {
            char temp = value[i];
            value[i] = value[j];
            value[j] = temp;
        }
        return this;
    }

    public MyStringBuilder2 substring(int begin) {
        return substring(begin, count);
    }

    public MyStringBuilder2 substring(int begin, int end) {
        if (begin < 0 || begin > end || end > count) {
            throw new StringIndexOutOfBoundsException();
        }
        int len = end - begin;
        char[] newvalue = new char[len];
        System.arraycopy(value, begin, newvalue, 0, len);
        return new MyStringBuilder2(newvalue);
    }

    public MyStringBuilder2 toUpperCase() {
        for (int i = 0; i < count; i++) {
            value[i] = Character.toUpperCase(value[i]);
        }
        return this;
    }

    private void ensureCapacity(int minimumCapacity) {
        if (minimumCapacity > value.length) {
            expandCapacity(minimumCapacity);
        }
    }

    private void expandCapacity(int minimumCapacity) {
        int newCapacity = value.length * 2 + 2;
        if (newCapacity < minimumCapacity) {
            newCapacity = minimumCapacity;
        }
        char[] newValue = new char[newCapacity];
        System.arraycopy(value, 0, newValue, 0, count);
        value = newValue;
    }

    public int length() {
        return count;
    }

    public char charAt(int index) {
        if (index < 0 || index >= count) {
            throw new StringIndexOutOfBoundsException(index);
        }
        return value[index];
    }

    public String toString() {
        return new String(value, 0, count);
    }
}

import java.util.Arrays;
 
public class PhraseRev{
    private static String reverse(String x){
        return new StringBuilder(x).reverse().toString();
    }
 
    private static <T> T[] reverse(T[] x){
        T[] rev = Arrays.copyOf(x, x.length);
        for(int i = x.length - 1; i >= 0; i--){
            rev[x.length - 1 - i] = x[i];
        }
        return rev;
    }
 
    private static String join(String[] arr, String joinStr){
        StringBuilder joined = new StringBuilder();
        for(int i = 0; i < arr.length; i++){
            joined.append(arr[i]);
            if(i < arr.length - 1) joined.append(joinStr);
        }
        return joined.toString();
    }
 
    public static void main(String[] args){
        String str = "rosetta code phrase reversal";
 
        System.out.println("Straight-up reversed: " + reverse(str));
        String[] words = str.split(" ");
        for(int i = 0; i < words.length; i++){
            words[i] = reverse(words[i]);
        }
        System.out.println("Reversed words: " + join(words, " "));
        System.out.println("Reversed word order: " + join(reverse(str.split(" ")), " "));
    }
}

