import org.w3c.dom.Node;
import org.w3c.dom.Element;

import abstractdocument.AbstractDocument;
import constants.SVG12Constants;

/**
 * MultiImageElement is a specialized SVG element for handling multi-image support.
 * It extends StylableSVGElement for additional pixel dimension attributes and child elements
 * management to support both inline SVG content and external images.
 */
public class MultiImageElement extends StylableSVGElement {

    // Additional pixel dimension attributes.
    protected int maxPixelWidth;
    protected int maxPixelHeight;

    // Constant representing the multi-image tag in the SVG vocabulary.
    public static final String MULTI_IMAGE_TAG = SVG12Constants.SVG_MULTI_IMAGE_TAG;

    /**
     * Default constructor for uninitialized instances.
     */
    public MultiImageElement() {
        super();
        this.maxPixelWidth = -1; // -1 indicates not set.
        this.maxPixelHeight = -1;
    }

    /**
     * Constructs a MultiImageElement associated with an AbstractDocument.
     *
     * @param ownerDocument The owning AbstractDocument instance.
     */
    public MultiImageElement(AbstractDocument ownerDocument) {
        super(ownerDocument, MULTI_IMAGE_TAG);
        this.maxPixelWidth = -1;
        this.maxPixelHeight = -1;
    }

    /**
     * Retrieves the local name of this element.
     *
     * @return The local name constant representing the SVG multi-image tag.
     */
    public String getLocalName() {
        return MULTI_IMAGE_TAG;
    }

    /**
     * Sets the maximum pixel width for rendering.
     *
     * @param width Maximum width in pixels.
     */
    public void setMaxPixelWidth(int width) {
        this.maxPixelWidth = width;
    }

    /**
     * Sets the maximum pixel height for rendering.
     *
     * @param height Maximum height in pixels.
     */
    public void setMaxPixelHeight(int height) {
        this.maxPixelHeight = height;
    }

    /**
     * Gets the maximum pixel width.
     *
     * @return Maximum width in pixels.
     */
    public int getMaxPixelWidth() {
        return this.maxPixelWidth;
    }

    /**
     * Gets the maximum pixel height.
     *
     * @return Maximum height in pixels.
     */
    public int getMaxPixelHeight() {
        return this.maxPixelHeight;
    }

    /**
     * Creates a new uninitialized instance for DOM cloning operations.
     *
     * @return A new instance of MultiImageElement.
     */
    @Override
    public Node newNode() {
        return new MultiImageElement();
    }

