import org.kuali.coeus.sys.api.model.ScaleTwoDecimal;
import java.io.Serializable;

public class LineItemObject extends LineItem implements Serializable {
    private static final long serialVersionUID = 1L;

    private String lineItemId;
    private String name;
    private ScaleTwoDecimal amount;

    public LineItemObject() {
        super();
    }

    public LineItemObject(String lineItemId, String name, ScaleTwoDecimal amount) {
        this.lineItemId = lineItemId;
        this.name = name;
        this.amount = amount;
    }

    public String getLineItemId() {
        return lineItemId;
    }

    public void setLineItemId(String lineItemId) {
        this.lineItemId = lineItemId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public ScaleTwoDecimal getAmount() {
        return amount;
    }

    public void setAmount(ScaleTwoDecimal amount) {
        this.amount = amount;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        LineItemObject that = (LineItemObject) o;

        if (lineItemId != null ? !lineItemId.equals(that.lineItemId) : that.lineItemId != null) return false;
        if (name != null ? !name.equals(that.name) : that.name != null) return false;
        return amount != null ? amount.equals(that.amount) : that.amount == null;
    }

    @Override
    public int hashCode() {
        int result = lineItemId != null ? lineItemId.hashCode() : 0;
        result = 31 * result + (name != null ? name.hashCode() : 0);
        result = 31 * result + (amount != null ? amount.hashCode() : 0);
        return result;
    }

    @Override
    public String toString() {
        return "LineItemObject{" +
                "lineItemId='" + lineItemId + '\'' +
                ", name='" + name + '\'' +
                ", amount=" + amount +
                '}';
    }
}

public int findTheDistanceValue(int[] arr1, int[] arr2, int d) {
    int count = 0;
    outerLoop:
    for (int num1 : arr1) {
        for (int num2 : arr2) {
            if (Math.abs(num1 - num2) <= d) {
                continue outerLoop;
            }
        }
        count++;
    }
    return count;
}

