class Writer {
    public long minimumSteps(String s) {
        long res = 0L;
        int oneCount = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0') {
                res += oneCount;

            } else {
                oneCount++;
            }
        }
        return res;
    }
}

class Builder {
    public int repeatedStringMatch(String A, String B) {
        StringBuilder sb=new StringBuilder(A);
        int m=A.length();
        int n=B.length();
        int k=1;
        while(true){
            if(sb.indexOf(B)!=-1) return k;
            else{
                if((k-1)*m+1>=n) return -1;
                sb.append(A);
            }
            k++;
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

public class Tree {
    public static void main(String[] args) {
        System.out.println("Exercise nil objects:");
        status();

        // initialize objects
        s = new int[1];
        p = s; // yes, reference element of slice just created
        f = () -> System.out.println("function call");
        i = new User(0); // see user defined type just below
        m = new HashMap<Integer, Integer>();
        c = new Channel<Integer>();

        System.out.println("\nExercise objects after initialization:");
        status();
    }

    static int[] s;
    static int p;
    static Consumer<Void> f;
    static Object i;
    static Map<Integer, Integer> m;
    static Channel<Integer> c;

    static void status() {
        trySlice();
        tryPointer();
        tryFunction();
        tryInterface();
        tryMap();
        tryChannel();
    }

    static void reportPanic() {
        if (x!= null) {
            System.out.println("panic:" + x);
        }
    }

    static void trySlice() {
        try {
            System.out.println("s[0] =" + s[0]);
        } catch (Exception e) {
            reportPanic();
        }
    }

    static void tryPointer() {
        try {
            System.out.println("*p =" + p);
        } catch (Exception e) {
            reportPanic();
        }
    }

    static void tryFunction() {
        try {
            f.accept(null);
        } catch (Exception e) {
            reportPanic();
        }
    }

    static void tryInterface() {
        try {
            // normally the nil identifier accesses a nil value for one of
            // six predefined types.  In a type switch however, nil can be used
            // as a type.  In this case, it matches the nil interface.
            if (i == null) {
                System.out.println("i is nil interface");
            } else if (i instanceof User) {
                System.out.println("i has method m");
            }

            // assert type with method and then call method
            ((User) i).m();
        } catch (Exception e) {
            reportPanic();
        }
    }

    static void tryMap() {
        try {
            m.put(0, 0);
            System.out.println("m[0] =" + m.get(0));
        } catch (Exception e) {
            reportPanic();
        }
    }

    static void tryChannel() {
        try {
            c.close();
            System.out.println("channel closed");
        } catch (Exception e) {
            reportPanic();
        }
    }

