     */
    public String getName() {
        return name;
    }

    /**
     * @see #getName()
     */
    public void setName(String name) {
        this.name = name;
    }

    /**
     * The amount in ScaleTwoDecimal format
     *
     * @return the amount
     */
    public ScaleTwoDecimal getAmount() {
        return amount;
    }

    /**
     * @see #getAmount()
     */
