        long numeroConta = (long) (Math.random() * 1000000);
        if (depositoInicial >= 50) {
            return new ContaPoupanca(numeroConta, cliente, depositoInicial, new Date(), numero);
        } else {
            return new Conta(numeroConta, cliente, depositoInicial, numero);
        }
    }

    public void ajustarLimites(ContaEspecial[] contasEspeciais) {
        for (ContaEspecial conta : contasEspeciais) {
            if (conta.getAgencia().equals(numero)) {
                ajustarLimiteIndividual(conta);
            }
        }
    }

    public abstract void ajustarLimiteIndividual(ContaEspecial conta);

    public void imprimeDados() {
        System.out.println("Agência: " + numero);
        System.out.println("Banco associado:");
        banco.imprimeDados();
    }
}

