import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class Finder {
    public static List<Integer> primeFactors(int number) {
        List<Integer> primes = new ArrayList<>();
        for (int div = 2; div <= number; div++) {
            while (number % div == 0) {
                primes.add(div);
                number = number / div;
            }
        }
        return primes;
    }
 
    public static void main(String[] args) {
        int[] n = { 12757923, 12878611, 12757923, 15808973, 15780709, 197622519 };
        // Calculate each of those numbers' prime factors, in parallel
        List<List<Integer>> factors = IntStream.of(n).parallel().mapToObj(Finder::primeFactors).collect(Collectors.toList());
        // Make a new list showing the smallest factor for each
        List<Integer> smallestFactors = factors.stream().map(thisNumbersFactors -> thisNumbersFactors.stream().min(Integer::compareTo).get()).collect(Collectors.toList());
        // Find the index that corresponds with the largest of those factors
        int biggestFactor = smallestFactors.stream().max(Integer::compareTo).get();
        int whatIndexIsThat = smallestFactors.indexOf(biggestFactor);
        System.out.println(String.format("%d has the largest minimum prime factor: %d", n[whatIndexIsThat], biggestFactor));
        System.out.println(factors.get(whatIndexIsThat).stream().map(Object::toString).collect(Collectors.joining(" ")));
    }
}

