import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import com.sleepycat.persist.evolve.Conversion;
import com.sleepycat.persist.evolve.Converter;

/**
 * Please see the documentation.
 */
public class EntityConverter extends Converter {

    private static final long serialVersionUID = 123456789L;

    private final Set<String> deletedKeys;

    public EntityConverter(String className, int classVersion,
                           Conversion conversion, Set<String> deletedKeys) {
        super(className, classVersion, conversion);
        if (deletedKeys != null) {
            this.deletedKeys = Collections.unmodifiableSet(new HashSet<>(deletedKeys));
        } else {
            this.deletedKeys = Collections.emptySet();
        }
    }

    public final Set<String> getDeletedKeys() {
        return deletedKeys;
    }

    @Override
    public boolean equals(Object o) {
        if (!super.equals(o)) {
            return false;
        }
        if (!(o instanceof EntityConverter)) {
            return false;
        }
        EntityConverter other = (EntityConverter) o;
        return deletedKeys.equals(other.deletedKeys);
    }

    @Override
    public int hashCode() {
        return super.hashCode() + deletedKeys.hashCode();
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("[EntityConverter ");
        sb.append(super.toString());
        sb.append(" deletedKeys=");
        sb.append(deletedKeys);
        sb.append(']');
        return sb.toString();
    }
}

public class Approximate {
    private static boolean approxEquals(double value, double other, double epsilon) {
        return Math.abs(value - other) < epsilon;
    }
 
    private static void test(double a, double b) {
        double epsilon = 1e-18;
        System.out.printf("%f, %f => %s\n", a, b, approxEquals(a, b, epsilon));
    }
 
    public static void main(String[] args) {
        test(100000000000000.01, 100000000000000.011);
        test(100.01, 100.011);
        test(10000000000000.001 / 10000.0, 1000000000.0000001000);
        test(0.001, 0.0010000001);
        test(0.000000000000000000000101, 0.0);
        test(Math.sqrt(2.0) * Math.sqrt(2.0), 2.0);
        test(-Math.sqrt(2.0) * Math.sqrt(2.0), -2.0);
        test(3.14159265358979323846, 3.14159265358979324);
    }
}

