@WebServlet("/BenchmarkTest18518")
public class BenchmarkTest18518 extends HttpServlet {

    private static final long serialVersionUID = 1L;

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        doPost(request, response);
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        response.setContentType("text/html;charset=UTF-8");
        PrintWriter out = response.getWriter();

        String foo = request.getParameter("foo");
        if (foo != null) {
            String bar = ESAPI.encoder().encodeForHTML(foo);
            try {
                doSomething(bar, out);
            } catch (Exception e) {
                out.println("Error occurred: " + e.getMessage());
            }
        } else {
            out.println("foo parameter is missing");
        }
    }

    private void doSomething(String input, PrintWriter out) throws Exception {

        Provider provider = Security.getProvider("SunJCE");
        String transformation = "DES/ECB/PKCS5Padding";

        try {
            Cipher cipher = Cipher.getInstance(transformation, provider);
            out.println("Cipher instantiation successful!");
        } catch (Exception e) {
            out.println("Cipher instantiation failed: " + e.getMessage());
        }

        out.println("Crypto test completed.");

    }
}

