public class F {

    InputStream is;

    FastWriter out;

    String INPUT = "";

    long[] ft0;

    long[] ft1;

    void add(int l, int r, int x)

    {

        addRangeFenwick(ft0, ft1, l, r-1, x);

    }

    long sum(int l, int r)

    {

        return sumRangeFenwick(ft0, ft1, r-1) - sumRangeFenwick(ft0, ft1, l-1);

    }

    int kth(int K)

    {

        int n = ft0.length - 3;

        int low = 0, high = n;

        while(high - low > 1){

            int h = high+low>>1;

            if(sumRangeFenwick(ft0, ft1, h-1) < K){

                low = h;

            }else{

                high = h;

            }

        }

        return low;

    }

    void solve()

    {

        int n = ni(), K = ni();

        int[] a = na(n);

        a = radixSort2(a);

        int x = 0;

        int min = Integer.MAX_VALUE;

        long all = 1;

        int D = 500000;

        ft0 = new long[D];

        ft1 = new long[D];

        add(0, 1, 1);

        if(all >= K){

            min = Math.min(min, kth(K));

        }

        for(int i = n-1;i >= 0;i--){

            int v = a[i];

            while(sum(x, x+1) == 0){

                x++;

            }

            add(x, x+1, -1);

            add(x+2, x+v/2+2, 1);

            add(x+2, x+(v-1)/2+2, 1);

            all += v - 2;

            if(all >= K){

                min = Math.min(min, kth(K));

            }

//          tr(restoreRangeFenwick(ft0, ft1));

        }

