                    SheetToolBar sheetToolBar = new  SheetToolBar();
                    toolbar.add(sheetToolBar);
                    toolbar.layout();
            }

             LayoutContainer wrapper = (LayoutContainer) Registry.get(AppView.CENTER_PANEL);
              wrapper.removeAll();
              wrapper.add(container);
