public class KyoceraMakernoteDescriptor extends TagDescriptor<KyoceraMakernoteDirectory> {

    public KyoceraMakernoteDescriptor(@NotNull KyoceraMakernoteDirectory directory) {
        super(directory);
    }

    @Nullable
    @Override
    public String getDescription(int tagType) {
        switch (tagType) {
            case KyoceraMakernoteDirectory.TAG_PRINT_IMAGE_MATCHING_INFO:
                return getPrintImageMatchingInfoDescription();
            case KyoceraMakernoteDirectory.TAG_PROPRIETARY_THUMBNAIL_DATA:
                return getProprietaryThumbnailDataDescription();
            case KyoceraMakernoteDirectory.TAG_MAKERNOTE_VERSION:
                return getMakernoteVersionDescription();
            case KyoceraMakernoteDirectory.TAG_CAMERA_MODE:
                return getCameraModeDescription();
            case KyoceraMakernoteDirectory.TAG_QUALITY_LEVEL:
                return getQualityLevelDescription();
