            return null;
        }
        return String.format("Print Image Matching Info (%d bytes)", bytes.length);
    }

    @Nullable
    private String getProprietaryThumbnailDataDescription() {
        byte[] bytes = _directory.getByteArray(KyoceraMakernoteDirectory.TAG_PROPRIETARY_THUMBNAIL_DATA);
        if (bytes == null) {
            return null;
        }
        return String.format("Proprietary Thumbnail Data (%d bytes)", bytes.length);
    }

    @Nullable
    private String getMakernoteVersionDescription() {
