import de.undercouch.citeproc.BibliographyFileReader;
import de.undercouch.citeproc.CSLTool;
import de.undercouch.citeproc.CSLToolContext;
import de.undercouch.citeproc.exception.BibliographyFileReaderException;
import de.undercouch.underline.CommandDesc;
import de.undercouch.underline.InputReader;
import de.undercouch.underline.OptionDesc;
import de.undercouch.underline.command.AbstractCommand;

import java.io.File;
import java.util.List;

@CommandDesc(name = "load", description = "Load a bibliography file")
public class ShellLoadCommand extends AbstractCSLToolCommand {
    private List<String> files;

    @OptionDesc(longName = "file", shortName = "f", description = "The bibliography file to load", argumentName = "FILE")
    public void setFiles(List<String> files) {
        this.files = files;
    }

    @Override
    public boolean checkArguments() {
        if (files == null || files.isEmpty()) {
            error("No bibliography file specified");
            return false;
        }
        if (files.size() > 1) {
            error("Only one bibliography file can be specified");
            return false;
        }
        return true;
    }

    @Override
    public int doRun(String[] remainingArgs, InputReader in, StringBuilder out) {
        String filePath = files.get(0);
        File file = new File(filePath);

        if (!file.exists()) {
            error("File not found: " + filePath);
            return 1;
        }

        CSLToolContext context = getCSLTool().getContext();
        BibliographyFileReader reader = ((ShellContext) context).getBibliographyFileReader();

        try {
            String format = reader.determineFormat(file);
            if (format == null) {
                error("Unsupported file format: " + filePath);
                return 1;
            }

            reader.read(file);
            ((ShellContext) context).setLoadedBibliographyFile(filePath);
            out.append("Loaded bibliography file: ").append(filePath).append("\n");
        } catch (BibliographyFileReaderException e) {
            error("Error reading bibliography file: " + e.getMessage());
            return 1;
        }

        return 0;
    }

    @Override
    public void printHelp(InputReader in, StringBuilder out) {
        super.printHelp(in, out);
        out.append("\nSupported file formats: BibTeX, RIS, YAML\n");
    }
}

static void formatMessage2(final StringBuilder buffer, final String messagePattern,
            final Object[] arguments, final int argCount, final int[] indices) {
        if (messagePattern == null || arguments == null || argCount == 0) {
            buffer.append(messagePattern);
            return;
        }
        int previous = 0;
        for (int i = 0; i < argCount; i++) {
            buffer.append(messagePattern, previous, indices[i]);
            previous = indices[i] + 2;
            recursiveDeepToString(arguments[i], buffer, null);
        }
        buffer.append(messagePattern, previous, messagePattern.length());
    }

class Cache {
  public boolean containsPattern(int[] arr, int m, int k) {
    final int N = m * k;
    if (N > arr.length)
      return false;
    if (k == 1)
      return true;
    for (int i = 0; i != arr.length; i++) {
      if (arr.length - i < N)
        break;
      boolean found = true;
      for (int j = 1; j != k; j++) {
        final int tempstart = i + j * m, tempend = i + (j + 1) * m;
        if (Arrays.equals(arr, i, i + m, arr, tempstart, tempend) == false) {
          found = false;
          break;
        }
      }
      if (found)
        return true;
    }
    return false;
  }
}

