class Student {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        if (initial.length == 1) {
            return initial[0];
        }
        int n = graph.length;
        int min = Integer.MAX_VALUE;
        int ans = -1;
        for (int i : initial) {
            int sum = bfs(graph, initial, i);
            if (min == sum) {
                ans = Math.min(i, ans);
            } else if (min > sum) {
                min = sum;
                ans = i;
            }

        }
        return ans;

    }

    private int bfs(int[][] graph, int[] initial, int m) {
        int n = graph.length;

        for (int i = 0; i < graph.length; i++) {
            if (graph[i][m] == 1) {
                graph[i][m] = -1;
                graph[m][i] = -1;
            }
        }

        Queue<Integer> queue = new LinkedList<>();
        Set<Integer> set = new HashSet<>();
        for (int j : initial) {
            if (j != m) {
                queue.offer(j);
                set.add(j);
            }
        }

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int i = 0; i < n; i++) {
                if (i == cur) {
                    continue;
                }
                if (graph[i][cur] == 1 && set.add(i)) {
                    queue.offer(i);
                }
            }
        }

        for (int i = 0; i < graph.length; i++) {
            if (graph[i][m] == -1) {
                graph[i][m] = 1;
                graph[m][i] = 1;
            }
        }

        return set.size();
    }
}

public int countUsersWithGlobalPermissionExcludingUser(DbSession dbSession, String organizationUuid, String permission, int excludedUserId) {
    String sql = "SELECT COUNT(*) FROM users " +
                 "WHERE organization_uuid = ? " +
                 "AND permission = ? " +
                 "AND user_id != ?";

    try (PreparedStatement stmt = dbSession.prepareStatement(sql)) {
        stmt.setString(1, organizationUuid);
        stmt.setString(2, permission);
        stmt.setInt(3, excludedUserId);

        try (ResultSet rs = stmt.executeQuery()) {
            if (rs.next()) {
                return rs.getInt(1);
            }
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }

    return 0;
}

import java.util.*;

public class Handler {
    public static void main(String[] args) {
        for (int number = 6; number <= 10000; number++) {
            int total = 0;
            int divisor = number - 1;

            while (divisor > 0) {

                if (number % divisor == 0) {
                    total += divisor;
                }
                divisor--;
            }

            if (number == total) {
                System.out.println(number);
            }

        }
    }
}

