import com.googlecode.pongo.runtime.querying.NumericalQueryProducer;
import com.googlecode.pongo.runtime.querying.StringQueryProducer;

public class DatetimeMeasurement extends Measurement {

    public DatetimeMeasurement() {
        super();
        super.setSuperTypes("org.ossmeter.metricprovider.rascal.trans.model.Measurement");
        URI.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
        VALUE.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
        TIME_ZONE_HOURS.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
        TIME_ZONE_MINS.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
    }

    private static final String VALUE_KEY = "value";
    private static final String TIME_ZONE_HOURS_KEY = "tz_hours";
    private static final String TIME_ZONE_MINS_KEY = "tz_mins";

    public static StringQueryProducer URI = new StringQueryProducer("uri");
    public static NumericalQueryProducer VALUE = new NumericalQueryProducer(VALUE_KEY);
    public static NumericalQueryProducer TIME_ZONE_HOURS = new NumericalQueryProducer(TIME_ZONE_HOURS_KEY);
    public static NumericalQueryProducer TIME_ZONE_MINS = new NumericalQueryProducer(TIME_ZONE_MINS_KEY);

    public long getValue() {
        return parseLong(dbObject.get(VALUE_KEY)+"", 0);
    }

    public int getTimezoneHours() {
        if (dbObject.containsField(TIME_ZONE_HOURS_KEY)) {
            return parseInteger(dbObject.get(TIME_ZONE_HOURS_KEY) + "", 0);
        }
        else {
            return 0;
        }
    }

    public int getTimezoneMinutes() {
        if (dbObject.containsField(TIME_ZONE_MINS_KEY)) {
            return parseInteger(dbObject.get(TIME_ZONE_MINS_KEY) + "", 0);
        }
        else {
            return 0;
        }
    }

    public DatetimeMeasurement setValue(long value, int timezoneHours, int timezoneMinutes) {
        dbObject.put(VALUE_KEY, value);
        dbObject.put(TIME_ZONE_HOURS_KEY, timezoneHours);
        dbObject.put(TIME_ZONE_MINS_KEY, timezoneMinutes);
        notifyChanged();
        return this;
    }
}

class Account {

    public int numJewelsInStones(String j, String s) {
        if (j == null || s == null) {
            return 0;
        }

        Set<Character> stones = new HashSet<>();
        for (int i = 0; i < j.length(); i++) {
            stones.add(j.charAt(i));
        }

        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            if (stones.contains(s.charAt(i))) {
                count += 1;
            }
        }

        return count;
    }

}

@Expose
    protected List<Exception> getExceptions() {
        List<Exception> exceptions = new ArrayList<Exception>();
        exceptions.add(exception);
        Throwable currentThrowable = exception.getThrowable().getCause();
        while (currentThrowable != null) {
            exceptions.add(new Exception(config, currentThrowable));
            currentThrowable = currentThrowable.getCause();
        }
        return exceptions;
    }

import com.google.common.annotations.GwtCompatible;
import com.google.common.annotations.VisibleForTesting;
import org.checkerframework.checker.nullness.compatqual.NullableDecl;

/**
 * Implementation of {@link ImmutableSet} with two or more elements.
 *
 */
@GwtCompatible(serializable = true, emulated = true)
@SuppressWarnings("serial") // uses writeReplace(), not default serialization
final class RegularImmutableSet<E> extends ImmutableSet<E> {
  static final RegularImmutableSet<Object> EMPTY =
      new RegularImmutableSet<>(new Object[0], 0, null, 0, 0);

  @VisibleForTesting final transient Object[] elements;
  // the same elements in hashed positions (plus nulls)
  @VisibleForTesting final transient Object[] table;
  // 'and' with an int to get a valid table index.
  private final transient int mask;
  private final transient int hashCode;
  private final transient int size;

  RegularImmutableSet(Object[] elements, int hashCode, Object[] table, int mask, int size) {
    this.elements = elements;
    this.table = table;
    this.mask = mask;
    this.hashCode = hashCode;
    this.size = size;
  }

  @Override
  public boolean contains(@NullableDecl Object target) {
    Object[] table = this.table;
    if (target == null || table == null) {
      return false;
    }
    for (int i = Hashing.smearedHash(target); ; i++) {
      i &= mask;
      Object candidate = table[i];
      if (candidate == null) {
        return false;
      } else if (candidate.equals(target)) {
        return true;
      }
    }
  }

  @Override
  public int size() {
    return size;
  }

  @Override
  public UnmodifiableIterator<E> iterator() {
    return asList().iterator();
  }

  @Override
  int copyIntoArray(Object[] dst, int offset) {
    System.arraycopy(elements, 0, dst, offset, size);
    return offset + size;
  }

  @Override
  ImmutableList<E> createAsList() {
    return ImmutableList.asImmutableList(elements, size);
  }

  @Override
  boolean isPartialView() {
    return false;
  }

  @Override
  public int hashCode() {
    return hashCode;
  }

  @Override
  boolean isHashCodeFast() {
    return true;
  }
}

@CheckReturnValue
  LocalSyncWriteModelContainer desyncDocumentsFromRemote(
      final NamespaceSynchronizationConfig nsConfig,
      final BsonValue... documentIds) {
    this.waitUntilInitialized();
    final MongoNamespace namespace = nsConfig.getNamespace();
    final Lock lock = this.syncConfig.getNamespaceConfig(namespace).getLock().writeLock();
    lock.lock();
    final DeleteManyModel<CoreDocumentSynchronizationConfig> configsToDelete;
    try {
      ongoingOperationsGroup.enter();
      configsToDelete = syncConfig.removeSynchronizedDocuments(namespace, documentIds);
    } finally {
      lock.unlock();
      ongoingOperationsGroup.exit();
    }
    LocalSyncWriteModelContainer container = null;
    if (configsToDelete != null) {
      container = newWriteModelContainer(nsConfig);
      container.addDocIDs(documentIds);
      container.addLocalWrite(new DeleteManyModel<>(
          new BsonDocument("_id",
              new BsonDocument("$in", new BsonArray(Arrays.asList(documentIds))))
      ));
      container.addConfigWrite(configsToDelete);
    }
    return container;
  }

public void setTupleSize( int tupleSize)
    {
    Integer onceSize =
      onceTuples_.isEmpty()
      ? null
      : getOnceTuples().next().size();
    if( !(onceSize == null || onceSize == tupleSize))
      {
      throw new IllegalArgumentException( "Tuple size=" + tupleSize + " is not compatible with existing once-only tuple size=" + onceSize);
      }

    tupleSize_ = tupleSize;
    }

