import java.util.logging.Logger;
import net.sf.mzmine.datamodel.*;
import net.sf.mzmine.modules.MZmineModule;
import net.sf.mzmine.parameters.ParameterSet;
import net.sf.mzmine.taskcontrol.*;
import net.sf.mzmine.util.ExitCode;
import org.apache.commons.lang3.ArrayUtils;
import net.sf.mzmine.modules.rawdataexport.scans.parameters.ExportScansFromRawFilesParameters;

public class ExportScansFromRawFilesModule implements MZmineModule {

  private static final String MODULE_NAME = "Export scans from raw data files";
  private Logger logger = Logger.getLogger(this.getClass().getName());

  @Override
  public String getName() {
    return MODULE_NAME;
  }

  @Override
  public Class<? extends ParameterSet> getParameterSetClass() {
    return ExportScansFromRawFilesParameters.class;
  }

  @Override
  public ExitCode runModule(
      final MZmineProject project,
      final ParameterSet parameters,
      final TaskController taskController) {

    RawDataFile[] dataFiles =
        parameters.getParameter(ExportScansFromRawFilesParameters.rawDataFiles).getValue();
    ScanSelection select =
        parameters.getParameter(ExportScansFromRawFilesParameters.scanSelection).getValue();

    Scan[] scans = new Scan[0];

    for (RawDataFile dataFile : dataFiles) {
      Scan[] matchingScans = select.getMatchingScans(dataFile);
      scans = ArrayUtils.addAll(scans, matchingScans);
      logger.info(
          "Selected " + matchingScans.length + " scan(s) from " + dataFile.getName() + ".");
    }

    if (scans.length == 0) {
      logger.warning("No scans were selected for export.");
      return ExitCode.OK;
    }

    logger.info("Total " + scans.length + " scan(s) selected for export.");

    Task task = new ExportScansTask(parameters, scans, taskController.getAddTaskQueue());
    taskController.addTask(task);

    return ExitCode.OK;
  }
}

