import java.io.IOException;
import java.util.Collection;
import java.util.Collections;

/**
 * A {@link Scorer} which wraps another scorer and caches the score of the
 * current document. Successive calls to {@link #score()} will return the same
 * result and will not invoke the wrapped Scorer's score() method, unless the
 * current document has changed.<br>
 * This class might be useful due to the changes done to the {@link Collector}
 * interface, in which the score is not computed for a document by default, only
 * if the collector requests it. Some collectors may need to use the score in
 * several places, however all they have in hand is a {@link Scorer} object, and
 * might end up computing the score of a document more than once.
 */
public class ScoreCachingWrappingScorer extends Scorer {

  private final Scorer scorer;
  private int curDoc = -1;
  private float curScore;

  /** Creates a new instance by wrapping the given scorer. */
  public ScoreCachingWrappingScorer(Scorer scorer) {
    super(scorer.weight);
    this.scorer = scorer;
  }

  @Override
  public boolean score(Collector collector, int max, int firstDocID) throws IOException {
    return scorer.score(collector, max, firstDocID);
  }

  @Override
  public float score() throws IOException {
    int doc = scorer.docID();
    if (doc != curDoc) {
      curScore = scorer.score();
      curDoc = doc;
    }

    return curScore;
  }

  @Override
  public int freq() throws IOException {
    return scorer.freq();
  }

  @Override
  public int docID() {
    return scorer.docID();
  }

  @Override
  public int nextDoc() throws IOException {
    return scorer.nextDoc();
  }

  @Override
  public void score(Collector collector) throws IOException {
    scorer.score(collector);
  }

  @Override

private static int getDay(Calendar cal, int dayOfWeek, int orderNum){
        int day = cal.getActualMaximum(Calendar.DAY_OF_MONTH);
        cal.set(Calendar.DAY_OF_MONTH, day);
        int lastWeekday = cal.get(Calendar.DAY_OF_WEEK);
        int shift = lastWeekday >= dayOfWeek ? (lastWeekday - dayOfWeek) : (lastWeekday + 7 - dayOfWeek);

        day -= shift;
        if(orderNum < 0)
            return day;
        cal.set(Calendar.DAY_OF_MONTH, day);
        int lastOrderNum = (cal.get(Calendar.DAY_OF_MONTH) - 1) / 7;
        if(orderNum >= lastOrderNum)
            return day;
        return day - (lastOrderNum - orderNum) * 7;
    }

import com.fasterxml.jackson.annotation.JsonIgnore;

/** The circular shape of selected region on the UI for comparison */
public class Circular extends Region {

  private int centerX;
  private int centerY;
  private int radius;

  public Circular() {}

  public Circular(int centerX, int centerY, int radius) {
    this.centerX = centerX;
    this.centerY = centerY;
    this.radius = radius;
  }

  public int getCenterX() {
    return centerX;
  }

  public void setCenterX(int centerX) {
    this.centerX = centerX;
  }

  public int getCenterY() {
    return centerY;
  }

  public void setCenterY(int centerY) {
    this.centerY = centerY;
  }

  public int getRadius() {
    return radius;
  }

  public void setRadius(int radius) {
    this.radius = radius;
  }

  @Override
  public boolean checkIfWithinBounds(int x, int y) {
    return Math.hypot(x - centerX, y - centerY) < radius;
  }

  @JsonIgnore
  @Override
  public Rectangular getBoundingBox() {
    return new Rectangular(centerX - radius, centerY - radius, radius * 2, radius * 2);
  }

  @JsonIgnore
  @Override
  public Region getOffsetRemovedRegion() {
    return new Circular(radius, radius, radius);
  }

  @JsonIgnore
  @Override
  public Region copy() {
    return new Circular(centerX, centerY, radius);
  }

  @JsonIgnore
  @Override
  public Region addOffset(int x, int y) {
    return new Circular(centerX + x, centerY + y, radius);
  }

  @JsonIgnore
  @Override
  public Region getScaledRegion(
      int hostScrnWidth, int hostScrnHeight, int devPhyWidth, int devPhyHeight) {
    int radiusEndX = centerX + radius;
    int scaledRadiusEndX = ImageUtil.scaleToTargetPx(radiusEndX, hostScrnWidth, devPhyWidth);
    int scaledCenterX = ImageUtil.scaleToTargetPx(centerX, hostScrnWidth, devPhyWidth);
    int scaledRadius = Math.abs(scaledRadiusEndX - scaledCenterX);
    int scaledCenterY = ImageUtil.scaleToTargetPx(centerY, hostScrnHeight, devPhyHeight);
    return new Circular(scaledCenterX, scaledCenterY, scaledRadius);
  }
}

