import com.google.gson.JsonObject;

public class SlackMessage {

    private String _username;
    private String _icon;
    private String _content;

    public SlackMessage(String content) {
        this._content = content;
        this._username = null;
        this._icon = null;
    }

    public SlackMessage(String content, String username) {
        this._content = content;
        this._username = username;
        this._icon = null;
    }

    public SlackMessage(String content, String username, String icon) {
        this._content = content;
        this._username = username;
        this._icon = icon;
    }

    public String getUsername() {
        return _username;
    }

    public void setUsername(String username) {
        this._username = username;
    }

    public String getIcon() {
        return _icon;
    }

    public void setIcon(String icon) {
        this._icon = icon;
    }

    public String getContent() {
        return _content;
    }

    public void setContent(String content) {
        this._content = content;
    }

    public JsonObject toJson() {
        JsonObject json = new JsonObject();
        json.addProperty("text", _content);

        if (_username != null && !_username.isEmpty()) {
            json.addProperty("username", _username);
        }

        if (_icon != null && !_icon.isEmpty()) {
            json.addProperty("icon_emoji", _icon);
        }
        else{
            json.addProperty("icon_emoji", ":robot_face:"); // Default
        }
        return json;
    }

     public static void main(String[] args) {
        // Example usage
        SlackMessage message1 = new SlackMessage("Hello, world!");
        System.out.println(message1.toJson());

        SlackMessage message2 = new SlackMessage("Greetings!", "MyBot");
        System.out.println(message2.toJson());

        SlackMessage message3 = new SlackMessage("Update:", "Updater", ":warning:");
        System.out.println(message3.toJson());

        message3.setIcon(":heavy_check_mark:");
        System.out.println(message3.toJson());

        message1.setContent("This is an updated content");
        message1.setUsername("new_user");
         System.out.println(message1.toJson());
    }
}

class Sorter {
    public String bestHand(int[] ranks, char[] suits) {
//         Map<Integer,Integer> map=new HashMap<>();
//         int ma=0;
//         for(int a:ranks){
//             map.put(a,map.getOrDefault(a,0)+1);
//             ma=Math.max(ma,map.get(a));
//         }
//         if(ma==5) return "Flush";
//         else if(ma==4) return "Three of a Kind";
//         else if(ma==2) return "Pair";
//         return "High Card";

        int n=ranks.length,ans=0;
        boolean flag=true;
        if(n==1) return "High Card";
        Map<Integer,Integer> map=new HashMap<>();
        map.put(ranks[0],map.getOrDefault(ranks[0],0)+1);
        for(int i=1;i<n;++i)
        {
            if(suits[i]!=suits[i-1])
                flag=false;
            map.put(ranks[i],map.getOrDefault(ranks[i],0)+1);
            ans=Math.max(ans,map.get(ranks[i]));
        }
        if(flag) return "Flush";
        if(ans==2) return "Pair";
        else if(ans>=3) return "Three of a Kind";
        return "High Card";
    }
}

