import java.util.Scanner;

public class Product {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();

        while (t-- > 0) {
            int a1 = scanner.nextInt();
            int a2 = scanner.nextInt();
            int a3 = scanner.nextInt();

            int d = Math.abs(a1 + a3 - 2 * a2);

            if (d % 3 == 0) {
                System.out.println(0);
            } else {
                System.out.println(1);
            }
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class LZW {
    public static void main(String[] args) {
        String uncompressed = "TOBEORNOTTOBEORTOBEORNOT";
        System.out.println(compress(uncompressed));
        System.out.println(decompress(compress(uncompressed)));
    }

    public static int[] compress(String uncompressed) {
        // Build the dictionary.
        Map<String, Integer> dictionary = new HashMap<String, Integer>();
        for (int i = 0; i < 256; i++) {
            dictionary.put("" + (char) i, i);
        }

        String w = "";
        String c = "";
        int wc = 0;
        int dictSize = 256;
        int[] result = new int[uncompressed.length()];
        int idx = 0;
        for (int i = 0; i < uncompressed.length(); i++) {
            c = "" + uncompressed.charAt(i);
            wc = dictionary.get(w + c);
            if (wc!= null) {
                w = w + c;
            } else {
                result[idx++] = dictionary.get(w);
                // Add wc to the dictionary.
                dictionary.put(w + c, dictSize++);
                w = c;
            }
        }

        // Output the code for w.
        if (!w.equals("")) {
            result[idx++] = dictionary.get(w);
        }
        return result;
    }

    public static String decompress(int[] compressed) {
        // Build the dictionary.
        Map<Integer, String> dictionary = new HashMap<Integer, String>();
        for (int i = 0; i < 256; i++) {
            dictionary.put(i, "" + (char) i);
        }

        String w = "" + (char) (int) compressed[0];
        String result = w;
        String entry = "";
        int k = 0;
        for (int i = 1; i < compressed.length; i++) {
            k = compressed[i];
            if (dictionary.containsKey(k)) {
                entry = dictionary.get(k);
            } else {
                if (k == dictSize) {
                    entry = w + w.charAt(0);
                } else {
                    return null;
                }
            }

            result += entry;

            // Add w+entry[0] to the dictionary.
            dictionary.put(dictSize++, w + entry.charAt(0));

            w = entry;
        }
        return result;
    }
}

import java.util.Arrays;
import java.util.Random;

/*
 * Fills an array with random integers, then reports the total,
 * mean, median and mode of the generated values.
 */
public class DiziyiRastgeleDoldur {

    private static final int BOYUT = 20;
    private static final int UST_SINIR = 20;

    public static void main(String[] args) {
        Random uretici = new Random();
        int[] veriler = new int[BOYUT];

        System.out.print("Rastgele Dizi Elemanlari: ");
        for (int i = 0; i < BOYUT; i++) {
            veriler[i] = uretici.nextInt(UST_SINIR);
            System.out.print(veriler[i] + " ");
        }

        System.out.println("\nDizinin Toplami: " + toplamHesapla(veriler));
        System.out.println("Dizinin Ortalamasi: " + ortalamaHesapla(veriler));
        System.out.println("Dizinin Ortancasi: " + medyanHesapla(veriler));
        System.out.println("Dizinin Modu: " + modHesapla(veriler));
    }

    public static int toplamHesapla(int[] veriler) {
        int toplam = 0;
        for (int deger : veriler) {
            toplam += deger;
        }
        return toplam;
    }

    public static double ortalamaHesapla(int[] veriler) {
        return (double) toplamHesapla(veriler) / veriler.length;
    }

    public static double medyanHesapla(int[] veriler) {
        Arrays.sort(veriler);
        System.out.println("Sirali Dizi Elemanlari: " + Arrays.toString(veriler));

        int orta = veriler.length / 2;
        if (veriler.length % 2 == 0) {
            return (veriler[orta - 1] + veriler[orta]) / 2.0;
        }
        return veriler[orta];
    }

    public static int modHesapla(int[] veriler) {
        Arrays.sort(veriler);

        int enSikGorulen = veriler[0];
        int enYuksekTekrar = 1;
        int suankiTekrar = 1;

        for (int i = 1; i < veriler.length; i++) {
            if (veriler[i] == veriler[i - 1]) {
                suankiTekrar++;
            } else {
                suankiTekrar = 1;
            }

            if (suankiTekrar > enYuksekTekrar) {
                enYuksekTekrar = suankiTekrar;
                enSikGorulen = veriler[i];
            }
        }

        return enSikGorulen;
    }
}

class Handler {
    int max = -1;
    HashMap<Integer, HashSet<Integer>> map;
    int[] cost;
    public int numOfMinutes(int n, int headID, int[] manager, int[] informTime) {
        map = new HashMap<>();
        cost = informTime;
        for(int i = 0; i < n; ++i) {
            map.putIfAbsent(manager[i], new HashSet<>());
            map.get(manager[i]).add(i);
        }
        dfs(headID, 0);
        return max;
    }
    void dfs(int x, int acc) {
        if(cost[x] == 0) {
            if(acc > max) max = acc;
            return;
        }
        for(int y : map.get(x)) {
            dfs(y, acc + cost[x]);
        }
    }
}

import java.util.Scanner;

public class PhoneKeyPads {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a phone number: ");
        String phoneNumber = input.nextLine();

        String translatedNumber = "";
        for (int i = 0; i < phoneNumber.length(); i++) {
            char ch = phoneNumber.charAt(i);
            if (Character.isLetter(ch)) {
                translatedNumber += getNumber(Character.toUpperCase(ch));
            } else {
                translatedNumber += ch;
            }
        }

        System.out.println("The translated phone number is: " + translatedNumber);
    }

    public static int getNumber(char uppercaseLetter) {
        if (uppercaseLetter >= 'A' && uppercaseLetter <= 'C') {
            return 2;
        } else if (uppercaseLetter >= 'D' && uppercaseLetter <= 'F') {
            return 3;
        } else if (uppercaseLetter >= 'G' && uppercaseLetter <= 'I') {
            return 4;
        } else if (uppercaseLetter >= 'J' && uppercaseLetter <= 'L') {
            return 5;
        } else if (uppercaseLetter >= 'M' && uppercaseLetter <= 'O') {
            return 6;
        } else if (uppercaseLetter >= 'P' && uppercaseLetter <= 'S') {
            return 7;
        } else if (uppercaseLetter >= 'T' && uppercaseLetter <= 'V') {
            return 8;
        } else if (uppercaseLetter >= 'W' && uppercaseLetter <= 'Z') {
            return 9;
        } else {
            return -1; // Invalid character
        }
    }
}

