    private ManagedSet<String> createEmptyManagedSet() {
        ManagedSet<String> managedSet = new ManagedSet<>();
        managedSet.setMergeEnabled(true);
        return managedSet;
    }

    public void testMergeSunnyDay() {
        ManagedSet<String> parentSet = createEmptyManagedSet();
        parentSet.add("parent1");
        parentSet.add("parent2");

        ManagedSet<String> childSet = createEmptyManagedSet();
        childSet.add("child1");
        childSet.add("child2");

        childSet.merge(parentSet);

        assertEquals(4, childSet.size());
        assertTrue(childSet.contains("parent1"));
        assertTrue(childSet.contains("parent2"));
        assertTrue(childSet.contains("child1"));
        assertTrue(childSet.contains("child2"));
    }

    public void testMergeWithNullParent() {
        ManagedSet<String> childSet = createEmptyManagedSet();
        childSet.add("child1");

        childSet.merge(null);

        assertEquals(1, childSet.size());
        assertTrue(childSet.contains("child1"));
    }

    public void testMergeNotAllowedWhenMergeNotEnabled() {
        ManagedSet<String> parentSet = createEmptyManagedSet();
        parentSet.add("parent1");
        parentSet.add("parent2");

        ManagedSet<String> childSet = createEmptyManagedSet();
        childSet.setMergeEnabled(false);
        childSet.add("child1");

        try {
            childSet.merge(parentSet);
            fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            assertEquals(1, childSet.size());
            assertTrue(childSet.contains("child1"));
        }
    }

    public void testMergeWithNonCompatibleParentType() {
        ManagedSet<String> parentSet = createEmptyManagedSet();
