public class GetAllUsersDatabaseAction {

    private AuthorizationService authorization;
    private User actingUser;

    public GetAllUsersDatabaseAction(AuthorizationService authorization) {
        this.authorization = authorization;
        this.actingUser = getUserByUoid(authorization.getCurrentUserId());
    }

    public Set<User> execute() {
        Set<User> users = new HashSet<>();
        QueryCondition condition = buildQueryCondition();
        users = query(condition);
        return users;
    }

    private User getUserByUoid(String uoid) {
        // Logic to retrieve a user by unique identifier
        return UserDatabase.getUserByUoid(uoid);
    }

    private QueryCondition buildQueryCondition() {
        QueryCondition condition = new QueryCondition();
        if (actingUser.getRole() == UserRole.ADMIN) {
            // Admins can see all users
            condition.addFilter("systemUser", false);
        } else {
            // Non-admins can see only active users
            condition.addFilter("active", true);
            condition.addFilter("systemUser", false);
        }
        return condition;
    }

    private Set<User> query(QueryCondition condition) {
        // Logic to query the database using the condition
        return UserDatabase.queryUsers(condition);
    }
}

