        int t = sc.nextInt();

        while(t--!=0){

            int n = sc.nextInt();

            long[] arr= new long[n];

            for(int i=0;i<n;i++){

               arr[i] = sc.nextLong() ;

            }

            Arrays.sort(arr);

            int flag = 0;

            for(int i=0;i<n-1;i++){

                if(arr[i+1]-arr[i]>1){

                    flag=1;

                    break;

                }

            }

            if(flag==1){

                System.out.println("No");

            }

            else{

                System.out.println("Yes");

            }

        }

    }

}

