public String convertConditionalsToHeaders(String conditionals) {
    // Assuming conditionals is a string representing a list of conditionals
    // Splitting the conditionals string by comma to separate each conditional
    String[] conditionalList = conditionals.split(",");

    // Creating an empty list to store the real headers
    List<String> realHeaders = new ArrayList<>();

    // Looping through each conditional in the list
    for (String conditional : conditionalList) {
        // Extracting the header from the conditional by splitting it by colon
        String[] parts = conditional.split(":");

        // Adding the header to the real headers list
        realHeaders.add(parts[0]);
    }

    // Joining the real headers list back into a single string separated by commas
    return String.join(",", realHeaders);
}

