class Finder {
    public int countLatticePoints(int[][] circles) {
        int res = 0, n = circles.length;
        for(int i = 0; i <= 200; i++) for(int j = 0; j <= 200; j++) {
            boolean in = false;
            for(int [] c : circles) {
                if( (c[0] - i) * (c[0] - i)  + (c[1] - j) * (c[1] - j) <= c[2] * c[2]) {in = true; break;}
            }
            if(in) res++;
        }
        return res;
    }
}

