import java.util.*;

public class TimeConversion {
    public static int convertTime(String current, String correct) {
        // Split the time into hours and minutes
        String[] currentTime = current.split(":");
        String[] correctTime = correct.split(":");

        // Convert hours and minutes to integers
        int currentHour = Integer.parseInt(currentTime[0]);
        int currentMinute = Integer.parseInt(currentTime[1]);
        int correctHour = Integer.parseInt(correctTime[0]);
        int correctMinute = Integer.parseInt(correctTime[1]);

        // Calculate the total minutes for both times
        int currentTotalMinutes = currentHour * 60 + currentMinute;
        int correctTotalMinutes = correctHour * 60 + correctMinute;

        // Calculate the difference in minutes
        int diff = correctTotalMinutes - currentTotalMinutes;

        // Operations to add minutes
        int[] operations = {60, 15, 5, 1};
        int count = 0;

        // Apply the operations
        for (int op : operations) {
            count += diff / op;
            diff %= op;
        }

        return count;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(convertTime("02:30", "04:35")); // Output: 3
        System.out.println(convertTime("11:00", "11:01")); // Output: 1
    }
}

