import java.util.Scanner;

public class IdenticalArrays {

    public static boolean areIdentical(int[] list1, int[] list2) {
        if (list1.length != list2.length) {
            return false;
        }
        for (int i = 0; i < list1.length; i++) {
            if (list1[i] != list2[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter list1: ");
        int n1 = input.nextInt();
        int[] list1 = new int[n1];
        for (int i = 0; i < n1; i++) {
            list1[i] = input.nextInt();
        }

        System.out.print("Enter list2: ");
        int n2 = input.nextInt();
        int[] list2 = new int[n2];
        for (int i = 0; i < n2; i++) {
            list2[i] = input.nextInt();
        }

        if (areIdentical(list1, list2)) {
            System.out.println("Two lists are strictly identical");
        } else {
            System.out.println("Two lists are not strictly identical");
        }
    }
}

import java.util.Arrays;
 
public class BinarySearch {
    public static int bsearch(int[] a, int n, int x) {
        int i = 0, j = n - 1;
        while (i <= j) {
            int k = i + ((j - i) / 2);
            if (a[k] == x) {
                return k;
            }
            else if (a[k] < x) {
                i = k + 1;
            }
            else {
                j = k - 1;
            }
        }
        return -1;
    }
 
    public static int bsearch_r(int[] a, int x, int i, int j) {
        if (j < i) {
            return -1;
        }
        int k = i + ((j - i) / 2);
        if (a[k] == x) {
            return k;
        }
        else if (a[k] < x) {
            return bsearch_r(a, x, k + 1, j);
        }
        else {
            return bsearch_r(a, x, i, k - 1);
        }
    }
 
    public static void main(String[] args) {
        int[] a = {-31, 0, 1, 2, 2, 4, 65, 83, 99, 782};
        int n = a.length;
        int x = 2;
        int i = bsearch(a, n, x);
        if (i >= 0) {
            System.out.printf("%d is at index %d.\n", x, i);
        }
        else {
            System.out.printf("%d is not found.\n", x);
        }
        x = 5;
        i = bsearch_r(a, x, 0, n - 1);
        if (i >= 0) {
            System.out.printf("%d is at index %d.\n", x, i);
        }
        else {
            System.out.printf("%d is not found.\n", x);
        }
    }
}

