import java.lang.Math;

public class Graph {
    public static void main(String[] args) {
        double radians = Math.PI / 4; // Pi / 4 is 45 degrees. All answers should be the same.
        double degrees = 45.0;
        double sine = Math.sin(radians);
        double cosine = Math.cos(radians);
        double tangent = Math.tan(radians);
        double arcsin = Math.asin(sine);
        double arccos = Math.acos(cosine);
        double arctan = Math.atan(tangent);

        // sine
        System.out.println(sine + " " + Math.sin(degrees * Math.PI / 180));
        // cosine
        System.out.println(cosine + " " + Math.cos(degrees * Math.PI / 180));
        // tangent
        System.out.println(tangent + " " + Math.tan(degrees * Math.PI / 180));
        // arcsine
        System.out.println(arcsin + " " + (arcsin * 180 / Math.PI));
        // arccosine
        System.out.println(arccos + " " + (arccos * 180 / Math.PI));
        // arctangent
        System.out.println(arctan + " " + (arctan * 180 / Math.PI));
    }
}

import com.intellij.psi.PsiElement;
import com.intellij.psi.PsiExpression;
import com.intellij.psi.PsiMethodCallExpression;
import com.intellij.psi.PsiNewExpression;
import com.intellij.psi.PsiType;
import com.intellij.openapi.diagnostic.Logger;

public class JNDIResourceInspection extends ResourceInspection {
    private static final Logger LOGGER = Logger.getInstance(JNDIResourceInspection.class);
    private static final String[] JNDI_METHODS = {
        "InitialContext", "lookup", "createSubcontext", "bind", "rebind"
    };

    @Override
    public String getID() {
        return "JNDIResourceManagement";
    }

    @Override
    public String getDisplayName() {
        return "JNDI Resource Management Inspection";
    }

    @Override
    protected void checkResourceUsage(PsiElement element) {
        if (element instanceof PsiExpression) {
            PsiExpression expression = (PsiExpression) element;
            if (isResourceCreation(expression)) {
                LOGGER.warn("Potentially unclosed JNDI resource detected: " + expression.getText());
            }
        }
    }

    private boolean isResourceCreation(PsiExpression expression) {
        if (expression instanceof PsiNewExpression) {
            return isJNDIClassType(expression.getType());
        } else if (expression instanceof PsiMethodCallExpression) {
            return isJNDIMethodCall((PsiMethodCallExpression) expression);
        }
        return false;
    }

    private boolean isJNDIClassType(PsiType type) {
        return type != null && type.getCanonicalText().startsWith("javax.naming.");
    }

    private boolean isJNDIMethodCall(PsiMethodCallExpression methodCallExpression) {
        String methodName = methodCallExpression.getMethodExpression().getReferenceName();
        for (String jndiMethod : JNDI_METHODS) {
            if (jndiMethod.equals(methodName)) {
                return true;
            }
        }
        return false;
    }
}

