class Task {
    public int minCost(int[] houses, int[][] cost, int m, int n, int target) {
        Integer[][][] dp = new Integer[m][n + 1][target + 1];
        int result = dfs(houses, cost, 0, 0, 0, dp);
        return result == Integer.MAX_VALUE ? -1 : result;
    }

    private int dfs(int[] houses, int[][] cost, int i, int prevColor, int groups, Integer[][][] dp) {
        if (groups > target) return Integer.MAX_VALUE;
        if (i == houses.length) return groups == target ? 0 : Integer.MAX_VALUE;
        if (dp[i][prevColor][groups] != null) return dp[i][prevColor][groups];

        int minCost = Integer.MAX_VALUE;
        if (houses[i] == 0) {
            for (int color = 1; color <= cost[i].length; color++) {
                minCost = Math.min(minCost, cost[i][color - 1] + dfs(houses, cost, i + 1, color, prevColor == color ? groups : groups + 1, dp));
            }
        } else {
            minCost = Math.min(minCost, dfs(houses, cost, i + 1, houses[i], prevColor == houses[i] ? groups : groups + 1, dp));
        }

        return dp[i][prevColor][groups] = minCost;
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeSet;

public class AlphabeticalOrder {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java AlphabeticalOrder <filename>");
            return;
        }

        String filename = args[0];
        File file = new File(filename);
        Set<String> words = new TreeSet<>();

        try (Scanner scanner = new Scanner(file)) {
            while (scanner.hasNext()) {
                String word = scanner.next().toLowerCase().replaceAll("[^a-z]", "");
                if (word.length() > 0) {
                    words.add(word);
                }
            }
        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + filename);
            return;
        }

        for (String word : words) {
            System.out.println(word);
        }
    }
}

