    Sweetmorn, Boomtime, Pungenday, Prickle_Prickle, Setting_Orange;
    public static Weekday from(int i) {
        return values()[i % 5];
    }
}
 
public enum Apostle {
    Mungday, Mojoday, Syaday, Zaraday, Maladay;
    public static Apostle from(int i) {
        return values()[i / 73];
    }
}
 
public enum Holiday {
    Chaoflux, Discoflux, Confuflux, Bureflux, Afflux;
    public static Holiday from(int i) {
        return values()[i / 73];
    }
}
 
public static String discordianDate(GregorianCalendar c) {
    int y = c.get(Calendar.YEAR);
    int yold = y + 1166;
 
    int dayOfYear = c.get(Calendar.DAY_OF_YEAR);
    if (c.isLeapYear(y)) {
        if (dayOfYear == 60)
            return "St. Tib's Day, in the YOLD " + yold;
        else if (dayOfYear > 60)
            dayOfYear--;
    }
 
    int seasonDay = --dayOfYear % 73 + 1;
    switch (seasonDay) {
        case 5:
            return "" + Apostle.from(dayOfYear) + ", in the YOLD " + yold;
        case 50:
            return "" + Holiday.from(dayOfYear) + ", in the YOLD " + yold;
        default:
            return "" + Weekday.from(dayOfYear) + ", day " + seasonDay + " of " + Season.from(dayOfYear) + " in the YOLD " + yold;
    }
}
 
public static void test(int y, int m, int d, String result) {
    assert discordianDate(new GregorianCalendar(y, m, d)).equals(result);
}
 
public static void main(String[] args) {
    System.out.println(discordianDate(new GregorianCalendar()));
 
    test(2010, 6, 22, "Pungenday, day 57 of Confusion in the YOLD 3176");
    test(2012, 1, 28, "Prickle-Prickle, day 59 of Chaos in the YOLD 3178");
    test(2012, 1, 29, "St. Tib's Day, in the YOLD 3178");
    test(2012, 2, 1, "Setting Orange, day 60 of Chaos in the YOLD 3178");
    test(2010, 0, 5, "Mungday, in the YOLD 3176");
    test(2011, 4, 3, "Discoflux, in the YOLD 3177");
    test(2015, 9, 19, "Boomtime, day 73 of Bureaucracy in the YOLD 3181");
}

import omero.model.Pixels;

/**
 * Calculates the various dimensions of an image from a {@link Pixels} instance.
 *
 */

public class ImportSize {

    public final String fileName;
    public final Pixels pixels;
    public final String dimOrder;
    public final int sizeX, sizeY, sizeZ, sizeC, sizeT, imageCount;
    public final int zSize, wSize, tSize;

    public ImportSize(String fileName, Pixels pixels, String dimOrder) {
        this.fileName = fileName;
        this.pixels = pixels;
        this.dimOrder = dimOrder;

        sizeZ = pixels.getSizeZ().getValue();
        sizeC = pixels.getSizeC().getValue();
        sizeT = pixels.getSizeT().getValue();
        sizeX = pixels.getSizeX().getValue();
        sizeY = pixels.getSizeY().getValue();
        imageCount = sizeZ * sizeC * sizeT;

        final int order = getSequenceNumber(dimOrder);

        int smallOffset = 1;
        switch (order) {
        // ZTW sequence
        case 0:
            zSize = smallOffset;
            tSize = zSize * sizeZ;
            wSize = tSize * sizeT;
            break;
        // WZT sequence
        case 1:
            wSize = smallOffset;
            zSize = wSize * sizeC;
            tSize = zSize * sizeZ;
            break;
        // ZWT sequence
        case 2:
            zSize = smallOffset;
            wSize = zSize * sizeZ;
            tSize = wSize * sizeC;
            break;
        // TWZ sequence
        case 3:
            tSize = smallOffset;
            wSize = tSize * sizeT;
            zSize = wSize * sizeC;
            break;
        // WTZ sequence
        case 4:
            wSize = smallOffset;
            tSize = wSize * sizeC;
            zSize = tSize * sizeT;
            break;
        // TZW
        case 5:
            tSize = smallOffset;
            zSize = tSize * sizeT;
            wSize = zSize * sizeZ;
            break;
        default:
            throw new RuntimeException("Bad order");
        }
    }

    private int getSequenceNumber(String dimOrder) {
        if (omero.model.enums.DimensionOrderXYZTC.value.equals(dimOrder))
            return 0;
        if (omero.model.enums.DimensionOrderXYCZT.value.equals(dimOrder))
            return 1;
        if (omero.model.enums.DimensionOrderXYZCT.value.equals(dimOrder))
            return 2;
        if (omero.model.enums.DimensionOrderXYTCZ.value.equals(dimOrder))
            return 3;
        if (omero.model.enums.DimensionOrderXYCTZ.value.equals(dimOrder))
            return 4;
        if (omero.model.enums.DimensionOrderXYTZC.value.equals(dimOrder))
            return 5;

