import static org.junit.Assert.*;
import org.junit.Before;
import org.junit.Test;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;

public class LALFileTest {
    private LALParser parser;
    private String simpleLogin;
    private String simpleFile;
    private String complexFile;
    private List<Login> complexLogins;

    @Before
    public void setUp() {
        parser = new LALParser();
        simpleLogin = "username=testUser\npassword=securePassword";
        simpleFile = getResource("simple.txt");
        complexFile = getResource("complex.txt");
    }

    @Test
    public void testNull() {
        try {
            parser.parse(null);
            fail("Expected an IllegalArgumentException to be thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("Input cannot be null", e.getMessage());
        }
    }

    @Test
    public void testFileParseSimple() {
        List<Login> logins = parser.parse(simpleFile);
        assertEquals(1, logins.size());

        Login login = logins.get(0);
        assertEquals("testUser", login.getUsername());
        assertEquals("securePassword", login.getPassword());
    }

    @Test
    public void testFileParseComplex() {
        complexLogins = parser.parse(complexFile);
        assertEquals(3, complexLogins.size()); // Assume 3 logins in complex file

        Login firstLogin = complexLogins.get(0);
        assertEquals("user1", firstLogin.getUsername());
        assertEquals("pass1", firstLogin.getPassword());

        Login secondLogin = complexLogins.get(1);
        assertEquals("user2", secondLogin.getUsername());
        assertEquals("pass2", secondLogin.getPassword());

        Login thirdLogin = complexLogins.get(2);
        assertEquals("user3", thirdLogin.getUsername());
        assertEquals("pass3", thirdLogin.getPassword());
    }

    private String getResource(String fileName) {
        try {
            return new String(Files.readAllBytes(Paths.get(getClass().getClassLoader().getResource(fileName).toURI())));
        } catch (Exception e) {
            throw new RuntimeException("Could not read resource: " + fileName, e);
        }
    }
}

