public class Eth {
    public static int halve( int n ){  return n/2;  }
    public static int double( int n ){  return 2*n;  }
    public static boolean isEven( int n ){  return n%2 == 0;  }
 
    public static int mult( int a, int b ){
        int sum = 0;
        int[] a = {a};
        int[] b = {b};
 
        while ( a[0]!= 1 ){
            a[0] = halve( a[0] );
            b[0] = double( b[0] );
        }
 
        for( int i = a.length - 1; i > 0 ; i -= 1 ){
 
            if(!isEven( a[i] ) ){
                sum += b[i];
            }
        }
        return sum + b[0];
    }
}
