import koala.dynamicjava.tree.visitor.Visitor;

/**
 * This class represents an or expression
 */

public class OrExpression extends BinaryExpression {
  /**
   * Initializes a type-less or expression
   * @param lexp   the left expression
   * @param rexp   the right expression
   * @exception IllegalArgumentException if lexp or rexp is null
   */
  public OrExpression(Expression lexp, Expression rexp) {
    super(lexp, rexp);
  }

  /**
   * Initializes a or expression
   * @param lexp   the left expression
   * @param rexp   the right expression
   * @param type   the type of the expression
   * @exception IllegalArgumentException if lexp or rexp is null
   */
  public OrExpression(Expression lexp, Expression rexp, Class<?> type) {
    super(lexp, rexp, type);
  }

  /**
   * Allows a visitor to traverse the tree
   * @param visitor the visitor
   */
  public <T> T acceptVisitor(Visitor<T> visitor) {
    return visitor.visit(this);
  }
    /**
     * Returns a string representation of this object.
     * @return a string representation of this object.
     */
    public String toString() {
      return "("+getClass().getName()+": "+getLeftExpression()+" || "+getRightExpression()+")";
    }
}

class Queue {
    public boolean checkIfCanBreak(String s1, String s2) {
        int len = s1.length();
        List<Character> list1 = strToList(s1);
        List<Character> list2 = strToList(s2);
        Collections.sort(list1);
        Collections.sort(list2);
        List<Integer> difs = new ArrayList<>();
        for(int i = 0; i < len; i++){
            difs.add(list1.get(i)-list2.get(i));
        }
        int posCount = 0;
        int negCount = 0;
        for(int dif:difs){
            if(dif > 0){
                posCount ++;
            }
            if(dif < 0){
                negCount ++;
            }
        }
        return posCount == 0 || negCount ==0;
    }
    private List<Character> strToList(String s){
        List<Character> list = new ArrayList<>();
        for(int i = 0; i < s.length(); i++){
            list.add(s.charAt(i));
        }
        return list;
    }
}

public int removeShortestSubarray(int[] arr) {
int lo = 0, hi = arr.length - 1;
while (lo < hi && arr[lo] >= arr[hi]) {
if (arr[lo] == arr[hi]) {
return hi - lo + 1;
} else if (arr[lo] < arr[hi]) {
lo++;
} else {
hi--;
}
while (lo < hi && arr[hi] >= arr[hi - 1]) hi--;
while (lo < hi && arr[lo] <= arr[lo + 1]) lo++;
if (arr[lo] < arr[hi]) break;
}
return hi - lo + 1;
}
}

import java.util.Scanner;

/**
 *
 */
public class Item {

    private int value;
    private String creator;

    public Item() {
    }

    public Item(int value, String creator) {
        this.value = value;
        this.creator = creator;
    }

    public int getValue() {
        return value;
    }

    public void setValue(int value) {
        this.value = value;
    }

    public String getCreator() {
        return creator;
    }

    public void setCreator(String creator) {
        this.creator = creator;
    }

    @Override
    public String toString() {
        return "Item[" + "value=" + value + ",creator=" + creator + ']';
    }

    public void input() {
        Scanner scanner = new Scanner(System.in);
        this.value = 0;
        do {
            System.out.print("Input a value: ");
            this.value = scanner.nextInt();
            scanner.nextLine();
        } while (this.value <= 0);
        do {
            System.out.print("Input a creator: ");
            this.creator = scanner.nextLine();
        } while(this.creator.isEmpty());
    }

    public void output() {
      System.out.println("Value: " + value);
      System.out.println("Creator: " + creator);
    }
}

import koala.dynamicjava.tree.visitor.Visitor;

/**
 * This class represents the or expression nodes of the syntax tree
 *
 */

public class OrExpression extends BinaryExpression {
    /**
     * Initializes the expression
     *
     * @param lexp the LHS expression
     * @param rexp the RHS expression
     * @exception IllegalArgumentException if lexp is null or rexp is null
     */
    public OrExpression(final Expression lexp, final Expression rexp) {
        this(lexp, rexp, null, 0, 0, 0, 0);
    }

    /**
     * Initializes the expression
     *
     * @param lexp the LHS expression
     * @param rexp the RHS expression
     * @param fn the filename
     * @param bl the begin line
     * @param bc the begin column
     * @param el the end line
     * @param ec the end column
     * @exception IllegalArgumentException if lexp is null or rexp is null
     */
    public OrExpression(final Expression lexp, final Expression rexp, final String fn, final int bl, final int bc, final int el, final int ec) {
        super(lexp, rexp, fn, bl, bc, el, ec);
    }

    /**
     * Allows a visitor to traverse the tree
     *
     * @param visitor the visitor to accept
     */
    @Override
    public Object acceptVisitor(final Visitor visitor) {
        return visitor.visit(this);
    }
}

