import java.util.HashSet;
import java.util.Set;

public class BaselineImpl extends AbstractResourceKind {

    private static final BaselineImpl singleton = new BaselineImpl();

    // Constants representing features and properties
    public static final String F_BASELINE = "baseline";
    public static final String P_BASELINE_COLLECTION = "baseline-collection";
    public static final String P_SUBBASELINE_SET = "subbaseline-set";

    // Private constructor to enforce singleton pattern
    private BaselineImpl() {}

    // Factory method to retrieve the singleton instance
    public static BaselineImpl getInstance() {
        return singleton;
    }

    @Override
    public Set<String> getSupportedLiveProperties(Set<String> excludedFeatures) {
        Set<String> supportedProperties = new HashSet<>();

        // Add baseline-specific properties if the feature is not excluded
        if (!excludedFeatures.contains(F_BASELINE)) {
            supportedProperties.add(P_BASELINE_COLLECTION);
            supportedProperties.add(P_SUBBASELINE_SET);
        }

        // Add common properties from the parent class
        supportedProperties.addAll(super.getSupportedLiveProperties(excludedFeatures));
        return supportedProperties;
    }

    @Override
    public Set<String> getSupportedMethods() {
        Set<String> supportedMethods = new HashSet<>();

        // Add baseline-specific methods
        supportedMethods.add("BASELINE-CONTROL");
        supportedMethods.add("MERGE");

        // Add common methods from the parent class
        supportedMethods.addAll(super.getSupportedMethods());
        return supportedMethods;
    }

    @Override
    public Set<String> getSupportedReports() {
        Set<String> supportedReports = new HashSet<>();

        // Add baseline-specific reports
        supportedReports.add("BASELINE-REPORT");
        supportedReports.add("SUBBASELINE-REPORT");

        // Add common reports from the parent class
        supportedReports.addAll(super.getSupportedReports());
        return supportedReports;
    }

    @Override
    public String toString() {
        return "BaselineResourceKind [Supported Live Properties: " + getSupportedLiveProperties(new HashSet<>()) +
                ", Supported Methods: " + getSupportedMethods() +
                ", Supported Reports: " + getSupportedReports() + "]";
    }

    public static void main(String[] args) {
        BaselineImpl baseline = BaselineImpl.getInstance();
        System.out.println(baseline);
    }
}

import simulation.data.PetrolStation;
import simulation.data.Road;

/**
 */

public class PetrolStationGenerator {
    private Road road;
    private int minimalDistanceBetweenStations = 50;
    private int maximumDistanceBetweenStations = 200;
    private float minimalFuelPrice = 3.5f;
    private float maximumFuelPrice = 4f;

    public PetrolStationGenerator(Road road) {
        this.road = road;
    }

    public void generateStationsOnTheRoad(){
        RandomIntegerGenerator generator = new RandomIntegerGenerator();
        int lastStationPosition = 0;
        road.addPetrolStation(generateStation(lastStationPosition));

        while (lastStationPosition < road.getDistance()){
           int nextStationDistance = generator.generateNumberFromRange(minimalDistanceBetweenStations,maximumDistanceBetweenStations);

           if(lastStationPosition+nextStationDistance <= road.getDistance()){
                road.addPetrolStation(generateStation(lastStationPosition+nextStationDistance));
                lastStationPosition += nextStationDistance;
           }else{
               break;
           }

        }
    }

    private PetrolStation generateStation(int positionOnRoad){
        float fuelPrice = new RandomFloatGenerator().generateNumberFromRange(minimalFuelPrice,maximumFuelPrice);

        return new PetrolStation(positionOnRoad,fuelPrice);
    }

    public Road getRoad() {
        return road;
    }

    public void setRoad(Road road) {
        this.road = road;
    }

    public int getMinimalDistanceBetweenStations() {
        return minimalDistanceBetweenStations;
    }

    public void setMinimalDistanceBetweenStations(int minimalDistanceBetweenStations) {
        this.minimalDistanceBetweenStations = minimalDistanceBetweenStations;
    }

    public int getMaximumDistanceBetweenStations() {
        return maximumDistanceBetweenStations;
    }

    public void setMaximumDistanceBetweenStations(int maximumDistanceBetweenStations) {
        this.maximumDistanceBetweenStations = maximumDistanceBetweenStations;
    }

    public float getMinimalFuelPrice() {
        return minimalFuelPrice;
    }

    public void setMinimalFuelPrice(float minimalFuelPrice) {
        this.minimalFuelPrice = minimalFuelPrice;
    }

    public float getMaximumFuelPrice() {
        return maximumFuelPrice;
    }

    public void setMaximumFuelPrice(float maximumFuelPrice) {
        this.maximumFuelPrice = maximumFuelPrice;
    }
}

A:

I would do it as follows:

Sort the array.
Create a new array of size $k$.

For each element $a_i$ in the original array:

Insert $a_i$ into the new array.

If the index of $a_i$ in the new array is $i$, insert $a_i$ into the new array again.

When all elements are inserted, the new array is a partition.

Calculate the sum of each partition.

Find the greatest common divisor of the sums.

The partition is the one with the greatest common divisor.

This algorithm has a time complexity of $O(n \log n)$ and a space complexity of $O(k)$.

A:

Here is a solution in C++. It's pretty fast, but it's not optimal. I've tried to make it as simple as possible, but I'm sure there are ways to make it more efficient.
#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main()
{
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
    }
    sort(a.begin(), a.end());
    int k = a.size() / 2;
    int i = 0;
    while (i < k)
    {
        int x = a[i];
        int y = a[a.size() - i - 1];
        int gcd = gcd(x, y);
        while (x % gcd != 0)
        {
            a[i] = x;
            x = a[i];
            i++;
        }
        while (y % gcd != 0)
        {
            a[a.size() - i - 1] = y;
            y = a[a.size() - i - 1];
            i++;
        }
        a[i] = gcd;
        a.erase(a.begin() + i + 1);
        a.erase(a.begin() + i);
        i = 0;
    }
    cout << a.size() << endl;
    for (int i = 0; i < a.size(); i++)
    {
        cout << a[i] << " ";
    }
    return 0;
}

