    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    sort(a.begin(), a.end());
    int k = a.size() / 2;
    int i = 0;
    while (i < k) {
        int x = a[i];
        int y = a[a.size() - i - 1];
        int gcd = gcd(x, y);
        while (x % gcd != 0) {
            a[i] = x;
            x = a[i];
            i++;
        }
        while (y % gcd != 0) {
            a[a.size() - i - 1] = y;
            y = a[a.size() - i - 1];
            i++;
        }
        a[i] = gcd;
        a.erase(a.begin() + i + 1);
        a.erase(a.begin() + i);
        i = 0;
    }
    cout << a.size() << endl;
    for (int i = 0; i < a.size(); i++) {
        cout << a[i] << " ";
    }
    return 0;
}

