import java.util.stream.Stream;
 
public class NameGame {
    private static void printVerse(String name) {
        StringBuilder sb = new StringBuilder(name.toLowerCase());
        sb.setCharAt(0, Character.toUpperCase(sb.charAt(0)));
        String x = sb.toString();
        String y = "AEIOU".indexOf(x.charAt(0)) > -1 ? x.toLowerCase() : x.substring(1);
        String b = "b" + y;
        String f = "f" + y;
        String m = "m" + y;
        switch (x.charAt(0)) {
            case 'B':
                b = y;
                break;
            case 'F':
                f = y;
                break;
            case 'M':
                m = y;
                break;
            default:
                // no adjustment needed
                break;
        }
        System.out.printf("%s, %s, bo-%s\n", x, x, b);
        System.out.printf("Banana-fana fo-%s\n", f);
        System.out.printf("Fee-fi-mo-%s\n", m);
        System.out.printf("%s!\n\n", x);
    }
 
    public static void main(String[] args) {
        Stream.of("Gary", "Earl", "Billy", "Felix", "Mary", "Steve").forEach(NameGame::printVerse);
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class ConvexHull {
 
    public static void main(String[] args) {
        List<Point> points = new ArrayList<>();
        points.add(new Point(16,3));
        points.add(new Point(12,17));
        points.add(new Point(0,6));
        points.add(new Point(-4,-6));
        points.add(new Point(16,6));
        points.add(new Point(16,-7));
        points.add(new Point(16,-3));
        points.add(new Point(17,-4));
        points.add(new Point(5,19));
        points.add(new Point(19,-8));
        points.add(new Point(3,16));
        points.add(new Point(12,13));
        points.add(new Point(3,-4));
        points.add(new Point(17,5));
        points.add(new Point(-3,15));
        points.add(new Point(-3,-9));
        points.add(new Point(0,11));
        points.add(new Point(-9,-3));
        points.add(new Point(-4,-2));
        points.add(new Point(12,10));
 
        List<Point> hull = calculateConvexHull(points);
 
        hull.forEach(System.out::println);
    }
 
    private static List<Point> calculateConvexHull(List<Point> points) {
        //There must be at least 3 points
        if (points.size() < 3) return points;
 
        List<Point> hull = new ArrayList<>();
 
        //Find the left most point in the polygon
        int leftMostIdx = 0;
        for (int i = 1; i < points.size(); i++) {
            if (points.get(i).x < points.get(leftMostIdx).x) {
                leftMostIdx = i;
            }
        }
 
        int p = leftMostIdx;
        int q = 0;
 
        do {
            //The left most point must be part of the hull
            hull.add(points.get(p));
 
            q = (p + 1) % points.size();
 
            for (int i = 0; i < points.size(); i++) {
                if (orientation(points.get(p), points.get(i), points.get(q)) == 2) {
                    q = i;
                }
            }
 
            p = q;
 
            //Break from loop once we reach the first point again
        } while (p!= leftMostIdx);
 
        return hull;
    }
 
    //Calculate orientation for 3 points
    //0 -> Straight line
    //1 -> Clockwise
    //2 -> Counterclockwise
    private static int orientation(Point p, Point q, Point r) {
        double val = (q.y - p.y) * (r.x - q.x) -
                (q.x - p.x) * (r.y - q.y);
 
        if (val == 0) return 0;
        if (val > 0) return 1; else return 2;
    }
 
    private static class Point {
        double x;
        double y;
 
        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

import java.awt.GraphicsEnvironment;
import java.util.Arrays;
