import net.sourceforge.plantuml.LineLocation;
import net.sourceforge.plantuml.command.CommandExecutionResult;
import net.sourceforge.plantuml.command.SingleLineCommand2;
import net.sourceforge.plantuml.command.regex.IRegex;
import net.sourceforge.plantuml.command.regex.IRegexConcat;
import net.sourceforge.plantuml.command.regex.RegexConcat;
import net.sourceforge.plantuml.command.regex.RegexLeaf;

public class CommandHelpFont extends SingleLineCommand2 {

    public CommandHelpFont() {
        super(getRegexConcat());
    }

    static IRegexConcat getRegexConcat() {
        return RegexConcat.build(CommandHelpFont.class.getName(), RegexLeaf.start(),
                new RegexLeaf("help", "(?i)help"),
                RegexLeaf.spaceOneOrMore(),
                new RegexLeaf("font", "(?i)font"),
                RegexLeaf.end());
    }

    @Override
    protected CommandExecutionResult executeArg(LineLocation lineLocation, Object diagram, String[] arg) {
        try {
            final Help help = (Help) diagram; // Assuming 'diagram' is actually of type 'Help'
            final String[] fontNames = GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames();
            Arrays.sort(fontNames);

            StringBuilder sb = new StringBuilder();
            sb.append("Available Fonts:\n");
            for (String fontName : fontNames) {
                sb.append("* ").append(fontName).append("\n");
            }
            help.addHelp(sb.toString()); // Assuming 'addHelp' method exists
            return CommandExecutionResult.ok();
        } catch (Exception e) {
            return CommandExecutionResult.error("Error getting fonts: " + e.getMessage());
        }
    }
    interface Help {
        void addHelp(String helpMessage);
    }
}

