public class PalindromicPermutations {
    public static void main(String[] args) throws NumberFormatException, IOException {

        Runtime runtime = Runtime.getRuntime();

        try (BufferedReader br=new BufferedReader(new InputStreamReader(System.in))) {
            System.out.println("Enter the string value ->> ");
            String inputString = br.readLine();

            int cLen = inputString.length();

            Hashtable<Character, Integer> table = new Hashtable<Character, Integer>();

            for (int i=0; i<cLen; i++) {
                char character = inputString.charAt(i);
                if (table.containsKey(character)) {
                    int count = table.get(character);
                    table.remove(character);
                    table.put(character, count + 1);
                } else {
                    table.put(character, 1);
                }
            }

            int oddCount=0;
            if (null != table) {
                for (Map.Entry<Character, Integer> ent : table.entrySet()) {
                    System.out.println("Key = " + ent.getKey() + ", Value = " + ent.getValue());

                    if (oddCount == 1 && ent.getValue()%2!=0) {
                        ;
                    } else if (ent.getValue()%2==0 || oddCount==1) {
                        oddCount += ent.getValue();
                    }

                }
            }

            if (oddCount > 1) {
                System.out.println("Map has odd numbers of value ");
            } else {
                System.out.println("Map does not have odd numbers ");
            }
        }

        System.out.println("Free memory =>" + runtime.freeMemory()/1024 + " K or " + runtime.freeMemory()/1024/1024 + " MB");
        System.out.println("Total memory =>" + runtime.totalMemory()/1024 + " K or " + runtime.totalMemory()/1024/1024 + " MB");
    }
}

