public int getShortestAbbreviation(String target, String[] dictionary) {
        // Initialize a Set<String> to store the dicts. This is
        // required to check whether the abbreviation is a suffix of any
        // word in the dicts.
        Set<String> dicts = new HashSet<>();
        for (String word : dictionary) {
            dicts.add(word);
            dicts.add(word.substring(1));
        }
        // Sort the dicts by length. It's not necessary but here we
        // *could* store them as Maps[Length -> List<Word>] to reduce the
        // number of comparisons later on.
        Map<Integer, List<String>> sortedDicts = dicts
            .stream()
            .sorted(Comparator.comparingInt(s -> s.length()))
            .collect(Collectors.groupingBy(s -> s.length()));
        // Sort the letters in `sortedDicts` to ensure that, for abbrevs
        // of shorter words, we first check the shorter words in alphabetical
        // order. For example, "a1" is shorter than "a3" so we first check
        // shorter dicts for "a1" and then "a3".
        sortedDicts.entrySet()
            .stream()
            .sorted(Entry.comparingByValue())
            .forEachOrdered(e -> e.getValue().stream()
                    .sorted(Entry.comparingByKey()))
        // Define a function `isWord` that checks whether the input `s` is
        // a prefix of any word in the dicts.
        boolean isWord(String s) {
            return dicts.stream()
                    .anyMatch(word -> word.startsWith(s));
        }
        // Define a helper function `getAbbreviation` that takes an abbr
        // of the current word and yields all non-adjacent substrings of
        // `s`.
        List<String> getAbbreviation(String s) {
            return s.chars()
                    .boxed()
                    .mapToObj(c -> String.valueOf((char) c))
                    .filter(c -> !isWord(c + s))
                    .collect(Collectors.toList());
        }
        // Define a helper function `getMinLength` that takes an abbre
        // of the current word, filters non-adjacent substrings (if any)
        // from `s`, and checks whether the abbreviation is a suffix of
        // any word in the dicts.
        int getMinLength(String abbr) {
            List<String> possibleUnis = getAbbreviation(abbr);
            return possibleUnis.stream().count() > 0 &&
                   !dicts.stream()
                    .noneMatch(word -> word.endsWith(abbr));
        }
