protected synchronized Link insert(Token newToken, Link insertPoint, Transaction transaction) throws ObjectManagerException {
    if (insertPoint == null) {
        throw new NoSuchElementException("The current element is deleted.");
    }

    Link newLink = new Link(newToken);
    Link previousLink = insertPoint.getPrevious();

    if (previousLink != null) {
        previousLink.setNext(newLink);
        newLink.setPrevious(previousLink);
    }

    newLink.setNext(insertPoint);
    insertPoint.setPrevious(newLink);

    return newLink;
}

