import java.io.IOException;
import java.io.InputStreamReader;
import java.util.PriorityQueue;

public class TossACoinToYourGraph {
    static int[] vertexValues, dist;
    static int n, m, k;
    static PriorityQueue<Integer> pq;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] arr = br.readLine().split(" ");
        n = Integer.parseInt(arr[0]);
        m = Integer.parseInt(arr[1]);
        k = Integer.parseInt(arr[2]);

        vertexValues = new int[n + 1];
        dist = new int[n + 1];
        pq = new PriorityQueue<>();

        for (int i = 1; i <= n; i++) {
            vertexValues[i] = Integer.parseInt(br.readLine());
        }

        for (int i = 0; i < m; i++) {
            int[] uv = new int[2];
            String[] temp = br.readLine().split(" ");
            uv[0] = Integer.parseInt(temp[0]);
            uv[1] = Integer.parseInt(temp[1]);
            vertexValues[uv[1]] = Math.max(vertexValues[uv[0]], vertexValues[uv[1]]);
            dist[uv[1]] = dist[uv[0]] + 1;
            pq.add(uv[1]);
        }

        if (pq.size() < k - 1) {
            System.out.println(-1);
            return;
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            result = Math.max(result, vertexValues[i]);
        }
        System.out.println(result);
    }
}

