import android.accounts.Account;
import android.os.Bundle;
import android.view.View.OnClickListener;

import com.owncloud.android.datamodel.OCFile;
import com.owncloud.android.ui.fragment.FileFragment;
import com.owncloud.android.ui.fragment.OCFileListFragment;

public class UploadPathActivity extends FolderPickerActivity implements FileFragment.ContainerActivity,
        OnClickListener, OnEnforceableRefreshListener {

    public static final String KEY_INSTANT_UPLOAD_PATH = "INSTANT_UPLOAD_PATH";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        String instantUploadPath = getIntent().getStringExtra(KEY_INSTANT_UPLOAD_PATH);

        // The caller activity (Preferences) is not a FileActivity, so it has no OCFile, only a path.
        OCFile folder = new OCFile(instantUploadPath);

        setFile(folder);
    }

    /**
     * Called when the ownCloud {@link Account} associated to the Activity was
     * just updated.
     */
    @Override
    protected void onAccountSet(boolean stateWasRecovered) {
        super.onAccountSet(stateWasRecovered);
        if (getAccount() != null) {

            updateFileFromDB();

            OCFile folder = getFile();
            if (folder == null || !folder.isFolder()) {
                // fall back to root folder
                setFile(getStorageManager().getFileByPath(OCFile.ROOT_PATH));
                folder = getFile();
            }

            onBrowsedDownTo(folder);

            if (!stateWasRecovered) {
                OCFileListFragment listOfFolders = getListOfFilesFragment();
                // TODO Enable when "On Device" is recovered ?
                listOfFolders.listDirectory(folder/*, false*/);

                startSyncFolderOperation(folder, false);
            }

            updateNavigationElementsInActionBar();
        }
    }
}

public class Finder {
    public String splitLoopedString(String[] a) {
        String res = null;
        String[] greater = a.clone();
        for (int i = 0; i < greater.length; i++) {
            String tmp = new StringBuilder(greater[i]).reverse().toString();
            if (tmp.compareTo(greater[i]) > 0) greater[i] = tmp;
        }

        for (int i = 0; i < a.length; i++) {
            StringBuilder builder = new StringBuilder();
            builder.append(a[i]);
            for (int j = 1; j < a.length; j++) {
                builder.append(greater[(i + j) % a.length]);
            }
            String tmp = builder.toString();
            int len = tmp.length();
            tmp = tmp + tmp;
            for (int j = 0; j < a[i].length(); j++) {
                String sub = tmp.substring(j, j + len);
                if (res == null || sub.compareTo(res) > 0) res = sub;
            }

            builder = new StringBuilder();
            builder.append(new StringBuilder(a[i]).reverse().toString());
            for (int j = 1; j < a.length; j++) {
                builder.append(greater[(i + j) % a.length]);
            }
            tmp = builder.toString();
            len = tmp.length();
            tmp = tmp + tmp;
            for (int j = 0; j < a[i].length(); j++) {
                String sub = tmp.substring(j, j + len);
                if (res == null || sub.compareTo(res) > 0) res = sub;
            }
        }

        return res;
    }
}

