public class PerfectShuffle {
    public static void main(String[] args) {
        int[] deckSizes = {8, 24, 52, 100, 1020, 1024, 10000};
        for (int deckSize : deckSizes) {
            System.out.println("Perfect shuffles required for deck size " + deckSize + ": " + perfectShuffle(deckSize));
        }
    }

    public static int perfectShuffle(int deckSize) {
        int[] deck = new int[deckSize];
        for (int i = 0; i < deckSize; i++) {
            deck[i] = i + 1;
        }
        int[] original = deck.clone();
        int half = deckSize / 2;
        for (int i = 1; ; i++) {
            int[] newDeck = new int[deckSize];
            for (int j = 0; j < half; j++) {
                newDeck[2 * j] = deck[j];
                newDeck[2 * j + 1] = deck[j + half];
            }
            deck = newDeck;
            if (Arrays.equals(deck, original)) {
                return i;
            }
        }
    }
}

