public class Binom {
    public static void main(String[] args) {
        System.out.println(binom(5, 3));
    }

    public static int binom(int n, int k) {
        int coeff = 1;
        int i;

        if (k < 0 || k > n) return 0;

        for (i = 0; i < k; i++) {
            coeff = coeff * (n - i) / (i + 1);
        }

        return coeff;
    }
}

public ListNode deleteMiddle(ListNode head) {
    if (head == null || head.next == null) {
        return null;
    }

    ListNode slow = head;
    ListNode fast = head;
    ListNode prev = null;

    while (fast != null && fast.next != null) {
        prev = slow;
        slow = slow.next;
        fast = fast.next.next;
    }

    if (prev != null) {
        prev.next = slow.next;
    }

    return head;
}

