import java.io.*;
import java.util.*;

public class Generator {
    static final long INF = 0x3f3f3f3f3f3f3f3fL;

    public static void main(String[] args) throws Exception {
        PrintWriter out = new PrintWriter(System.out);
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int n = Integer.parseInt(br.readLine());
        int[] a = new int[n + 1], b = new int[n + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            b[i] = Integer.parseInt(st.nextToken());
        }
        int[] x = new int[n + 1], y = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            x[a[i]] = i;
        }
        for (int i = 1; i <= n; i++) {
            y[b[i]] = i;
        }
        BitSet bs = new BitSet(n + 1);
        List<Integer> ans = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (!bs.get(i)) {
                List<Integer> last = new ArrayList<>();
                int now = i;
                while (!bs.get(now)) {
                    bs.set(now);
                    last.add(now);
                    now = x[now];
                }
                now = i;
                while (!bs.get(now)) {
                    bs.set(now);
                    now = y[now];
                }
                if (last.size() > 1) {
                    ans.addAll(last);
                }
            }
        }
        out.println(ans.size());
        for (int e : ans) {
            out.print(e + " ");
        }
        out.println();
        out.close();
    }
}

public static UfsJournalSnapshot getSnapshot(UfsJournal journal) throws IOException {

    List<UfsJournalFile> checkpoints = new ArrayList<>();
    UfsStatus[] statuses = journal.getUfs().listStatus(journal.getCheckpointDir().toString());
    if (statuses != null) {
      for (UfsStatus status : statuses) {
        UfsJournalFile file = UfsJournalFile.decodeCheckpointFile(journal, status.getName());
        if (file != null) {
          checkpoints.add(file);
        }
      }
      Collections.sort(checkpoints);
    }
    List<UfsJournalFile> logs = new ArrayList<>();
    statuses = journal.getUfs().listStatus(journal.getLogDir().toString());
    if (statuses != null) {
      for (UfsStatus status : statuses) {
        UfsJournalFile file = UfsJournalFile.decodeLogFile(journal, status.getName());
        if (file != null) {
          logs.add(file);
        }
      }
      Collections.sort(logs);
    }
    List<UfsJournalFile> tmpCheckpoints = new ArrayList<>();
    statuses = journal.getUfs().listStatus(journal.getTmpDir().toString());
    if (statuses != null) {
      for (UfsStatus status : statuses) {
        tmpCheckpoints.add(UfsJournalFile.decodeTemporaryCheckpointFile(journal, status.getName()));
      }
    }
    return new UfsJournalSnapshot(checkpoints, logs, tmpCheckpoints);
  }

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Writer {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        ArrayList<Integer> one = new ArrayList<>();
        ArrayList<Integer> two = new ArrayList<>();
        System.out.print("Enter 5 integers for list1: ");
        for (int i = 0; i < 5; i++) {
            one.add(in.nextInt());
        }
        System.out.print("Enter 5 integers for list2: ");
        for (int i = 0; i < 5; i++) {
            two.add(in.nextInt());
        }

        System.out.println("The combined list is " + union(one, two).toString());
        in.close();
    }

    public static ArrayList<Integer> union(ArrayList<Integer> list1, ArrayList<Integer> list2) {
        list1.addAll(list2);
        return list1;

    }
}

public static final double signed(double angle) {
    // Normalize the angle to be within 0 - 360
    angle = angle % 360;
    // Convert to signed angle
    if (angle > 180) {
        angle = angle - 360;
    }
    return angle;
}

