public interface IDrillThroughInstance {

    /**
     * Sets the report name
     *
     * @param reportName the report name
     */
    void setReportName(String reportName);

    /**
     * Returns the report name
     *
     * @return the report name
     */
    String getReportName();

    /**
     * Sets parameter bindings
     *
     * @param parameterBindings the parameter bindings
     */
    void setParameterBindings(Map<String, Object> parameterBindings);

    /**
     * Returns parameter bindings
     *
     * @return parameter bindings
     */
    Map<String, Object> getParameterBindings();

    /**
     * Sets search criteria
     *
     * @param searchCriteria the search criteria
     */
    void setSearchCriteria(Map<String, Object> searchCriteria);

    /**
     * Returns search criteria
     *
     * @return search criteria
     */
    Map<String, Object> getSearchCriteria();

    /**
     * Sets the format
     *
     * @param format the format
     */
    void setFormat(String format);

    /**
     * Returns the format
     *
     * @return format
     */
    String getFormat();

    /**
     * Sets if the bookmark is a TOC entry
     *
     * @param isTOC true if the bookmark is a TOC entry
     */
    void setBookmark(boolean isTOC, String bookmark);

     /**
      * Set the target table of content.
      * @param toc the toc
      */
    void setTOC(String toc);

    /**
     * get toc.
     * @return the toc
     */
    String getTOC();

    /**
     * Returns the target window.
     *
     * @return target window
     */
    String getTargetWindow();

    /**
     * Sets the target window.
     *
     * @param targetWindow
     */
    void setTargetWindow(String targetWindow);

    /**
     * Returns if the bookmark is a TOC entry
     *
     * @return true if the bookmark is a TOC entry, false otherwise
     */
    boolean isBookmark();

      /**
     * return bookmark
     * @return
     */
    String getBookmark();

    /**
     * @param targetFileType the targetFileType to set
     */
    void setTargetFileType(String targetFileType);

    /**
     * @return the targetFileType
     */
    String getTargetFileType();
}

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonSubTypes.Type;
import java.util.Map;
import java.util.Objects;

@JsonTypeInfo(
        use = JsonTypeInfo.Id.NAME,
        include = JsonTypeInfo.As.PROPERTY,
        property = "type")
@JsonSubTypes({
        @Type(value = DirectoryGroup.class, name = DirectoryEntity.TYPE_GROUP),
        @Type(value = DirectoryPerson.class, name = DirectoryEntity.TYPE_PERSON)
})
public abstract class DirectoryEntity implements Comparable<DirectoryEntity> {
    public static final String TYPE_GROUP = "group";
    public static final String TYPE_PERSON = "person";
    private String id;
    private String displayName;

    public DirectoryEntity() {
    }

    public String getId() {
        return id;
    }

    public String getDisplayName() {
        return displayName;
    }

    public abstract String getType();

    public static DirectoryEntity fromMap(Map map) {
        String type = (String) map.get("type");
        if (TYPE_GROUP.equals(type)) {
            return new DirectoryGroup(map);
        } else if (TYPE_PERSON.equals(type)) {
            return new DirectoryPerson(map);
        }
        throw new VisalloClientApiException("Unhandled type of DirectoryEntity: " + type);
    }

    public static boolean isEntity(Map map) {
        return map != null && map.containsKey("type");
    }

    public static boolean isValidType(String type) {
        return TYPE_GROUP.equals(type) || TYPE_PERSON.equals(type);
    }

    @Override
    public int compareTo(DirectoryEntity other) {
        int typeComparison = getType().compareTo(other.getType());
        if (typeComparison != 0) {
            return typeComparison;
        }
        return getId().compareTo(other.getId());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        DirectoryEntity that = (DirectoryEntity) o;
        return Objects.equals(id, that.id) && Objects.equals(displayName, that.displayName);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, displayName);
    }
}

