fun distinctNames(ideas: List<String>): Int {
var ans = 0
val count = HashSet<String>()
val perms = HashSet<String>()
val countPerms = HashSet<Char>()
val c = createCount(ideas)
val d = createDistPerms(ideas)
for ((_, char) in d) {
countPerms[char] = 0
for (p in char) {
perms += "" + p
}
}
for ((_, char) in c) {
count[char] = 0
perms.forEach { countPerms[it] += 1 }
perms.forEach {
    countPerms[it] = count[it].toLong() / countPerms[it]?.toLong()!!.toDouble()
    ans += count[it].toLong() / (countPerms[it]?.toLong()?: 1)  - countPerms[it].toLong() - 1
}
return ans.toInt().coerceAtMost(1000000000)
}
fun createCount(ideas: List<String>): HashMap<String, Long> {
var map = HashMap<String, Long>()
var permutations = HashSet<String>()
for (item in ideas) {
var perm = "" + item[0].toString()
for (j in 1 until item.length) {
perm += item[j].toString()
}
}
for (item in permutations) {
map[item] = 0
}
return map
}
fun createDistPerms(ideas: List<String>): HashMap<String, Char> {
var map = HashMap<String, Char>()
return map
}
return ans
}
}

