    private static String render(String s, Font f) {
        String[] rows = new String[f.height];
        if (f.slant!= 0) {
            int start = 0;
            if (f.slant > 0) {
                start = f.height;
            }
            for (int i = 0; i < rows.length; i++) {
                rows[i] = " ".repeat(Math.max(0, (start - i) * f.slant));
            }
        }
        if (f.spacing >= 0) {
            String spacing = " ".repeat(Math.max(0, f.spacing));
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                for (int i = 0; i < f.height; i++) {
                    String r = f.m.get(c)[i];
                    if (j > 0) {
                        r = spacing + r;
                    }
                    rows[i] += r;
                }
            }
        } else {
            int overlap = -f.spacing;
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                for (int i = 0; i < f.height; i++) {
                    String r = f.m.get(c)[i];
                    if (j > 0) {
                        r = r.substring(overlap);
                    }
                    rows[i] += r;
                }
            }
        }
        return String.join("\n", rows);
    }
 
