class Graph {
    public int areaOfMaxDiagonal(int[][] dimensions) {
        int d = 0, area = 0;
        for (int[] rect : dimensions) {
            int diag = rect[0] * rect[0] + rect[1] * rect[1];
            if (diag > d) {
                d = diag;
                area = rect[0] * rect[1];
            }
            else if (diag == d) area = Math.max(area, rect[0] * rect[1]);
        }
        return area;
    }
}

class Reader {
    public int findBestValue(int[] arr, int target) {
        int left = 1, right = 100000;
        int sum = 0;
        while(left < right) {
            int mid = left + (right-left)/2;
            sum = 0;
            for(int i=0; i<arr.length; i++) {
                sum += (arr[i] > mid)? mid : arr[i];
            }
            if(sum < target) {
                left = mid+1;
            }else {
                right = mid;
            }
        }
        int sum1 = 0;
        for(int i=0; i<arr.length; i++) sum1 += (arr[i] > left)? left : arr[i];
        if(sum1 > target) {
            int sum2 = 0;
            for(int i=0; i<arr.length; i++) {
                sum2 += (arr[i] > left-1)? left-1 : arr[i];
            }
            return (abs(sum1, target) < abs(sum2, target))? left : left-1;
        }else if(sum1 < target) {
            int sum2 = 0;
            for(int i=0; i<arr.length; i++) {
                sum2 += (arr[i] > left+1)? left+1 : arr[i];
            }
            return (abs(sum1, target) <= abs(sum2, target))? left : left+1;
        }else {
            return left;
        }
        // return left;
    }
    int abs(int a, int b) {
        return (a > b)? a-b : b-a;
    }
}

