class Converter {
    public int primePalindrome(int N) {
        if (N == 1) {
            return 2;
        }
        long l = N;
        while (l <= Integer.MAX_VALUE) {
            l = nextPalin("" + l);
            if (isPrime(l)) {
                return (int)l;
            }
            l++;
        }
        return -1;
    }
    private long nextPalin(String n) {
        int l = n.length();
        List<Long> cands = new LinkedList<>();
        cands.add((long)Math.pow(10, l) + 1);
        long half = Long.parseLong(n.substring(0, (l + 1) / 2));
        for (long i = half; i <= half + 1; i++) {
            String halfString = "" + i;
            if (l % 2 == 1) {
                halfString = halfString.substring(0, halfString.length() - 1);
            }
            String newString = "" + i + new StringBuilder(halfString).reverse().toString();
            cands.add(Long.parseLong(newString));
        }
        long ori = Long.parseLong(n), diff = Long.MAX_VALUE, result = -1;
        for (long cand : cands) {
            if (cand >= ori && cand - ori < diff) {
                result = cand;
                diff = cand - ori;
            }
        }
        return result;
    }
    private boolean isPrime(long l) {
        for (long i = 2; i * i <= l; i++) {
            if (l % i == 0) {
                return false;
            }
        }
        return true;
    }
}

