import org.apache.commons.lang3.reflect.MethodUtils;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;

public final class ReflectionEventCondition {
    private final Object ruleInstance;
    private final Method method;

    private ReflectionEventCondition(Object ruleInstance, Method method) {
        this.ruleInstance = ruleInstance;
        this.method = method;
    }

    public static ReflectionEventCondition create(Rule rule) {
        validateRule(rule);
        String methodName = extractMethodName(rule);
        Class<?> ruleClass = rule.getClass();
        Method method = resolveMethod(ruleClass, methodName);
        validateMethodSignature(method);
        return new ReflectionEventCondition(rule, method);
    }

    public boolean condition(Event event) {
        validateEvent(event);
        try {
            return invokeMethod(event);
        } catch (ReflectiveOperationException ex) {
            handleReflectionException(ex);
            return false;
        }
    }

    private static void validateRule(Rule rule) {
        if (rule == null) {
            throw new FrameworkException("Rule instance cannot be null");
        }
        if (rule.getMeta() == null) {
            throw new FrameworkException("Rule metadata is missing for rule: " + rule.getClass().getSimpleName());
        }
    }

    private static String extractMethodName(Rule rule) {
        String methodName = rule.getMeta().getName();
        if (methodName == null || methodName.trim().isEmpty()) {
            throw new FrameworkException("Condition method name not specified in rule metadata: " + rule.getClass().getName());
        }
        return methodName;
    }

    private static Method resolveMethod(Class<?> ruleClass, String methodName) {
        Method method = MethodUtils.getMatchingAccessibleMethod(ruleClass, methodName, Event.class);
        if (method == null) {
            throw new FrameworkException(String.format(
                "Condition method '%s' not found in rule class %s with Event parameter",
                methodName, ruleClass.getName()));
        }
        return method;
    }

    private static void validateMethodSignature(Method method) {
        if (method.getReturnType() != boolean.class) {
            throw new FrameworkException(String.format(
                "Invalid return type for method %s. Expected boolean, found %s",
                method.getName(), method.getReturnType().getSimpleName()));
        }
    }

    private void validateEvent(Event event) {
        if (event == null) {

// Digital Root: Bir sayinin basamaklarini tekrarli olarak toplar ve tek bir basamak kalana kadar devam eder.

import java.util.Scanner;

public class DijitalKok {

    public static void main(String[] args) {

        // Kullanicidan bir sayi girdisi al
        Scanner tarayici = new Scanner(System.in);
        System.out.print("Bir sayi giriniz: ");
        int sayi = tarayici.nextInt();

        // Dijital kok hesaplama
        int dijitalKok = sayi;

        // Tek basamak kalana kadar dongu
        while (dijitalKok >= 10) {
            int gecici = dijitalKok; // Gecici degisken
            int toplam = 0; // Basamak toplami

            // Basamaklari toplama islemi
            while (gecici > 0) {
                toplam += gecici % 10; // Son basamagi toplama ekle
                gecici /= 10; // Son basamagi cikar
            }

            dijitalKok = toplam; // Yeni dijital kok degerini guncelle
        }

        // Sonuc yazdir
        System.out.println("Dijital kok: " + dijitalKok);

        tarayici.close(); // Kaynaklari serbest birak
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
 
public class PrintInFrame {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<String> words = new ArrayList<>();
        if (args.length > 0) {
            for (int i = 0; i < args.length; i++) {
                words.add(args[i]);
            }
        } else {
            words.add("Hello");
            words.add("World");
            words.add("in");
            words.add("a");
            words.add("frame");
        }
        printInFrame(words);
    }
 
    public static void printInFrame(List<String> words) {
        int maxLen = 0;
        for (String word : words) {
            if (word.length() > maxLen) {
                maxLen = word.length();
            }
        }
        int width = maxLen + 4;
        int height = words.size() + 2;
        char[][] frame = new char[height][width];
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                frame[i][j] ='';
            }
        }
        for (int i = 0; i < words.size(); i++) {
            String word = words.get(i);
            for (int j = 0; j < word.length(); j++) {
                frame[i + 1][j + 2] = word.charAt(j);
            }
        }
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                System.out.print(frame[i][j]);
            }
            System.out.println();
        }
    }
}

