import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.net.SocketTimeoutException;
import java.util.ArrayList;
import android.os.Handler;
import android.os.Message;

class UDPScanThread extends Thread {

    private ArrayList<String> servers;
    private DatagramSocket dgSocket;
    private Handler handler;
    private DatagramPacket dgPacket;
    private static final int UDPPORT = 8888; // Example port

    public UDPScanThread(ArrayList<String> servers, Handler handler) {
        this.servers = servers;
        this.handler = handler;
    }

    @Override
    public void run() {
        try {
            dgSocket = new DatagramSocket();
            dgSocket.setBroadcast(true);
            dgSocket.setSoTimeout(3000); // 3 seconds timeout

            send();
            receive();

            handler.sendMessage(Message.obtain(handler, 1)); // Success

        } catch (IOException e) {
            handler.sendMessage(Message.obtain(handler, 0)); // Fail
        } finally {
            stopUDP();
        }
    }

    public void stopUDP() {
        if (dgSocket != null) {
            dgSocket.close();
        }
    }

    public void send() throws IOException {
        String messageStr = "DISCOVER_SERVER_REQUEST";
        byte[] message = messageStr.getBytes();
        dgPacket = new DatagramPacket(message, message.length,
                InetAddress.getByName("255.255.255.255"), UDPPORT);
        dgSocket.send(dgPacket);
    }

    public void receive() throws IOException {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                byte[] buffer = new byte[1024];
                DatagramPacket receivedPacket = new DatagramPacket(buffer, buffer.length);
                dgSocket.receive(receivedPacket);

                String receivedData = new String(receivedPacket.getData(), 0, receivedPacket.getLength());
                if (receivedData.startsWith("DISCOVER_SERVER_RESPONSE")) {

                    String serverInfo = receivedData.substring("DISCOVER_SERVER_RESPONSE".length());
                    String[] parts = serverInfo.split("_");
                    if(parts.length>=2){
                        String ipAndPort = parts[1];
                        servers.add("ServerName" + "_" + ipAndPort);
                    }

                }
            } catch (SocketTimeoutException e) {
                break; // Timeout, exit loop
            }
        }
    }
}

import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.MemoryUsage;
import junit.framework.TestCase;

public class MemoryMXBeanTest extends TestCase {
    private MemoryMXBean mb;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        mb = ManagementFactory.getMemoryMXBean();
    }

    public void testHeapMemoryUsage() {
        MemoryUsage heapUsage = mb.getHeapMemoryUsage();
        assertNotNull("Heap Memory Usage should not be null", heapUsage);
        assertTrue("Committed memory should be greater than or equal to used memory",
                heapUsage.getCommitted() >= heapUsage.getUsed());

        long maxHeap = heapUsage.getMax();
        assertTrue("Max memory should be greater than zero", maxHeap > 0);
    }

    public void testNonHeapMemoryUsage() {
        MemoryUsage nonHeapUsage = mb.getNonHeapMemoryUsage();
        assertNotNull("Non-Heap Memory Usage should not be null", nonHeapUsage);
        assertTrue("Committed memory should be greater than or equal to used memory",
                nonHeapUsage.getCommitted() >= nonHeapUsage.getUsed());

        long maxNonHeap = nonHeapUsage.getMax();
        assertTrue("Max non-heap memory should be greater than zero", maxNonHeap > 0);
    }

    public void testObjectPendingFinalizationCount() {
        int pendingFinalizationCount = mb.getObjectPendingFinalizationCount();
        assertTrue("Pending finalization count should be non-negative",
                pendingFinalizationCount >= 0);
    }

    public void testSetVerbose() {
        try {
            mb.setVerbose(true);
            assertTrue("Verbose should be set to true", mb.isVerbose());
        } catch (UnsupportedOperationException e) {
            // This exception may be thrown if the JVM does not support setting verbose
            System.out.println("Setting verbose not supported: " + e.getMessage());
        }
    }

    @Override
    protected void tearDown() throws Exception {
        super.tearDown();
    }

    public static void main(String[] args) {
        junit.textui.TestRunner.run(MemoryMXBeanTest.class);
    }
}

import org.apache.ambari.server.state.Cluster;
import org.apache.ambari.server.state.Service;
import org.apache.ambari.server.state.UpgradeType;
import org.apache.ambari.server.state.stack.PrereqCheckRequest;
import org.apache.ambari.server.state.stack.PrerequisiteCheck;
import org.apache.ambari.server.state.stack.PrerequisiteCheckStatus;
import org.apache.ambari.server.state.stack.PrerequisiteCheckType;
import org.apache.ambari.server.state.stack.PrerequisiteCheckDefinition;
import com.google.inject.Singleton;

@Singleton
public class StormShutdownWarning implements PrerequisiteCheckDefinition {

    private static final String STORM_SERVICE_NAME = "STORM";
    private static final String WARNING_MESSAGE = "Storm service is installed and the upgrade type is rolling. " +
            "This may cause issues during the upgrade process. Please review the upgrade documentation.";

    @Override
    public boolean isApplicable(PrereqCheckRequest request) {
        // Check if the upgrade type is rolling
        if (request.getUpgradeType() != UpgradeType.ROLLING) {
            return false;
        }

        // Check if the Storm service is installed in the cluster
        Cluster cluster = request.getCluster();
        if (cluster == null) {
            return false;
        }

        Service stormService = cluster.getService(STORM_SERVICE_NAME);
        return stormService != null;
    }

    @Override
    public void perform(PrerequisiteCheck prerequisiteCheck, PrereqCheckRequest request) {
        if (!isApplicable(request)) {
            return;
        }

        // Set the warning status and message
        prerequisiteCheck.setStatus(PrerequisiteCheckStatus.WARNING);
        prerequisiteCheck.setFailReason(WARNING_MESSAGE);
        prerequisiteCheck.setType(PrerequisiteCheckType.SERVICE);
    }

    @Override
    public String getCheckDescription() {
        return "Checks if Storm is installed and the upgrade type is rolling, generating a warning if both conditions are met.";
    }

    @Override
    public String getCheckId() {
        return "STORM_ROLLING_UPGRADE_WARNING";
    }

    @Override
    public String getCheckName() {
        return "Storm Rolling Upgrade Warning";
    }

    @Override
    public PrerequisiteCheckType getType() {
        return PrerequisiteCheckType.SERVICE;
    }
}

