import com.google.common.io.ByteStreams;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.CRC32;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public class ZipOutputFileProvider {
    private static final String DESUGAR_DEPS_FILENAME = "desugar_deps";
    private final ZipOutputStream out;

    public ZipOutputFileProvider(Path zipFilePath) throws IOException {
        OutputStream fileOut = Files.newOutputStream(zipFilePath);
        this.out = new ZipOutputStream(fileOut);
    }

    public void copyFrom(InputFileProvider inputFileProvider, String filename) throws IOException {
        try (InputStream in = inputFileProvider.getInputStream(filename)) {
            if (in == null) {
                throw new IOException("File not found: " + filename);
            }
            ZipEntry entry = inputFileProvider.getZipEntry(filename);
            if (entry != null) {
                out.putNextEntry(entry);
                ByteStreams.copy(in, out);
                out.closeEntry();
            }
        }
    }

    public void write(String filename, byte[] content) throws IOException {
        if (filename.endsWith(".class") || filename.equals(DESUGAR_DEPS_FILENAME)) {
            writeStoredEntry(filename, content);
        } else {
            writeDeflatedEntry(filename, content);
        }
    }

    private void writeStoredEntry(String filename, byte[] content) throws IOException {
        CRC32 crc32 = new CRC32();
        crc32.update(content);
        ZipEntry result = new ZipEntry(filename);
        result.setMethod(ZipEntry.STORED);
        result.setSize(content.length);
        result.setCrc(crc32.getValue());
        result.setTime(0L); // Stable timestamp for reproducibility
        out.putNextEntry(result);
        out.write(content);
        out.closeEntry();
    }

    private void writeDeflatedEntry(String filename, byte[] content) throws IOException {
        ZipEntry result = new ZipEntry(filename);
        result.setTime(0L); // Stable timestamp for reproducibility
        out.putNextEntry(result);
        out.write(content);
        out.closeEntry();
    }

    public void close() throws IOException {
        out.close();
    }
}

interface InputFileProvider {
    InputStream getInputStream(String filename) throws IOException;
    ZipEntry getZipEntry(String filename) throws IOException;
}

