public void initProcessAnnotations(Iterable<? extends Processor> processors,
                                       Collection<? extends JavaFileObject> initialFiles,
                                       Collection<String> initialClassNames) {

        if (options.isSet(PROC, "none")) {
            processAnnotations = false;
        } else if (procEnvImpl == null) {
            procEnvImpl = JavacProcessingEnvironment.instance(context);
            procEnvImpl.setProcessors(processors);
            processAnnotations = procEnvImpl.atLeastOneProcessor();
            if (processAnnotations) {
                options.put("parameters", "parameters");
                reader.saveParameterNames = true;
                keepComments = true;
                genEndPos = true;
                if (!taskListener.isEmpty())
                    taskListener.started(new TaskEvent(TaskEvent.Kind.ANNOTATION_PROCESSING));
                deferredDiagnosticHandler = new Log.DeferredDiagnosticHandler(log);
                procEnvImpl.getFiler().setInitialState(initialFiles, initialClassNames);
            } else {
                procEnvImpl.close();
            }
        }
    }

public class Validator {
    public int minDistance(int height, int width, int[] tree, int[] squirrel, int[][] nuts) {
        int len = nuts.length;
        int[] nuts2tree = new int[len];
        int[] squirrel2nuts = new int[len];
        for(int i = 0;i<len;i++){
            nuts2tree[i] = Math.abs(nuts[i][0] - tree[0]) + Math.abs(nuts[i][1] - tree[1]);
            squirrel2nuts[i] = Math.abs(nuts[i][0] - squirrel[0]) + Math.abs(nuts[i][1] - squirrel[1]);
        }
        int sum = 0;
        int adjustment = Integer.MAX_VALUE;
        for(int i = 0;i<len;i++){
            sum += 2*nuts2tree[i];
            adjustment = Math.min(adjustment,squirrel2nuts[i] -nuts2tree[i]);
        }
        return sum + adjustment;
    }
}

