public class CF1515F extends PrintWriter {
    CF1515F() { super(System.out); }
    Scanner sc = new Scanner(System.in);
    public static void main(String[] $) {
        CF1515F o = new CF1515F(); o.main(); o.flush();
    }

    int[] ds;
    int find(int i) {
        return ds[i] < 0 ? i : (ds[i] = find(ds[i]));
    }
    boolean join(int i, int j) {
        i = find(i);
        j = find(j);
        if (i == j)
            return false;
        if (ds[i] > ds[j])
            ds[i] = j;
        else {
            if (ds[i] == ds[j])
                ds[i]--;
            ds[j] = i;
        }
        return true;
    }
    void main() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int x = sc.nextInt();
        long[] aa = new long[n]; long s = 0;
        for (int i = 0; i < n; i++)
            s += aa[i] = sc.nextInt();
        if (s < (long) (n - 1) * x) {
            println("NO");
            return;
        }
        ds = new int[n]; Arrays.fill(ds, -1);
        int[] dd = new int[n], vv = new int[n], ee = new int[n];
        for (int h = 1; h <= m; h++) {
            int i = sc.nextInt() - 1;
            int j = sc.nextInt() - 1;
            if (join(i, j)) {
                dd[i]++; vv[i] ^= j; ee[i] ^= h;
                dd[j]++; vv[j] ^= i; ee[j] ^= h;
            }
        }
        int[] qu = new int[n]; int head = 0, cnt = 0;
        for (int i = 0; i < n; i++)
            if (dd[i] == 1)
                qu[head + cnt++] = i;
        int[] ans = new int[n - 1]; int l = 0, r = n - 1;
        for (int g = 0; g < n - 1; g++) {
            int i = qu[head++]; cnt--;
            int j = vv[i], h = ee[i];
            if (aa[i] + aa[j] >= x) {
                ans[l++] = h;
                aa[j] += aa[i] - x;
            } else
                ans[--r] = h;
            if (--dd[j] == 1)
                qu[head + cnt++] = j;
            vv[j] ^= i; ee[j] ^= h;
        }
        println("YES");
        for (int g = 0; g < n - 1; g++)
            println(ans[g]);
    }
}

import java.lang.reflect.Method;
import org.hamcrest.BaseMatcher;
import org.hamcrest.Description;
import org.hamcrest.Matcher;

public class SetterMatcher<T> extends BaseMatcher<Method> {

    private final Class<?> expectedType;

    public SetterMatcher(Class<T> type) {
        this.expectedType = type;
    }

    public boolean matches(Object obj) {
        if (obj instanceof Method) {
            Method method = (Method) obj;
            if (method.getName().startsWith("set") && method.getParameterCount() == 1) {
                Class<?> actualType = method.getParameterTypes()[0];
                return expectedType.isAssignableFrom(actualType);
            }
        }
        return false;
    }

    public void describeTo(Description desc) {
        desc.appendText("setter method with parameter of type ").appendValue(expectedType);
    }

    public static <T> Matcher<Method> setterOf(Class<T> type) {
        return new SetterMatcher<>(type);
    }

}

public static void cloneTheme(Intent sourceIntent, Intent intent, boolean force) {
    Bundle sourceExtras = sourceIntent.getExtras();
    if (sourceExtras != null && sourceExtras.containsKey(_THEME_TAG)) {
        int theme = sourceExtras.getInt(_THEME_TAG);
        intent.putExtra(_THEME_TAG, theme);
    } else if (force) {
        intent.putExtra(_THEME_TAG, getDefaultTheme());
    }
}

public class RasyonelSayi {

    private int pay;        // Rasyonel sayinin payini temsil eder
    private int payda;      // Rasyonel sayinin paydasini temsil eder

    public RasyonelSayi(int pay, int payda) {
        this.pay = pay;        // Pay ve payda degerlerini ayarlar
        this.payda = payda;
    }

    // Rasyonel sayiyi basitlestiren metod
    private void basitlestir() {
        int ebob = findEBOB(pay, payda);  // Pay ve payda icin en buyuk ortak boleni hesaplar
        pay /= ebob;        // Pay ve paydayi en buyuk ortak bolen ile bolerek basitlestirir
        payda /= ebob;
    }

    // En buyuk ortak boleni bulan metod
    private int findEBOB(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;   // En buyuk ortak boleni dondurur
    }

    // Iki rasyonel sayiyi toplayan metod
    public RasyonelSayi topla(RasyonelSayi digerSayi) {
        int yeniPay = (this.pay * digerSayi.payda) + (digerSayi.pay * this.payda);  // Iki rasyonel sayiyi toplar
        int yeniPayda = this.payda * digerSayi.payda;
        return new RasyonelSayi(yeniPay, yeniPayda);   // Yeni rasyonel sayiyi dondurur
    }

    // Iki rasyonel sayiyi carpan metod
    public RasyonelSayi carp(RasyonelSayi digerSayi) {
        int yeniPay = this.pay * digerSayi.pay;   // Iki rasyonel sayiyi carpar
        int yeniPayda = this.payda * digerSayi.payda;
        return new RasyonelSayi(yeniPay, yeniPayda);   // Yeni rasyonel sayiyi dondurur
    }

    // Rasyonel sayiyi metinsel olarak temsil eden metod
    public String toString() {
        return pay + "/" + payda;   // Rasyonel sayiyi metinsel olarak temsil eder
    }

