    }

    void main() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int q = sc.nextInt();
        int[] aa = new int[1 + n + m];
        int[] ii = new int[1 + n + m];
        for (int i = 1; i <= n + m; i++) {
            aa[i] = sc.nextInt();
            ii[i] = i;
        }
        ii = Arrays.stream(ii).boxed().sorted((i, j) -> aa[i] - aa[j]).mapToInt($->$).toArray();
        long[] ss = new long[1 + n + m];
        long ans = 0;
        for (int i = 1; i <= n + m; i++) {
            ss[i] = ss[i - 1] + aa[ii[i]];
            if (ii[i] <= n)
                ans += aa[ii[i]];
        }
        int[] ll = new int[1 + n + m];
        int[] rr = new int[1 + n + m];
        int[] kk = new int[1 + n + m];
        for (int i = 1; i <= n + m; i++) {
            ll[i] = rr[i] = i;
            if (ii[i] <= n)
                kk[i] = 1;
        }
        n += m;
        int[] gg = new int[n - 1];
        for (int i = 1; i < n; i++) {
            gg[i - 1] = aa[ii[i + 1]] - aa[ii[i]];
            ii[i - 1] = i - 1;
        }
        ii = Arrays.stream(ii, 0, n - 1).boxed().sorted((i, j) -> gg[i] - gg[j]).mapToInt($->$).toArray();
        int[] ff = new int[q];
        int[] hh = new int[q];
        for (int h = 0; h < q; h++) {
            ff[h] = sc.nextInt();
            hh[h] = h;
        }
        hh = Arrays.stream(hh).boxed().sorted((i, j) -> ff[i] - ff[j]).mapToInt($->$).toArray();
        long[] cc = new long[q];
        for (int hg = 0, hf = 0; hf < q; hf++) {
            int f = ff[hh[hf]];
            while (hg < n - 1 && gg[ii[hg]] <= f) {
                int i = ii[hg++] + 1;
                int l = ll[i];
                int r = rr[i + 1];
                ans -= ss[i] - ss[i - kk[i]];
                ans += ss[r - kk[r]] - ss[r - kk[r] - kk[i]];
                rr[l] = r; ll[r] = l; kk[r] += kk[i];
            }
            cc[hh[hf]] = ans;
        }
        for (int h = 0; h < q; h++)
            println(cc[h]);
    }
}

