public class Cholesky {
    public static void main(String[] args) {
        demo(new Symmetric(3, new double[]{
                25,
                15, 18,
                -5, 0, 11}));
        demo(new Symmetric(4, new double[]{
                18,
                22, 70,
                54, 86, 174,
                42, 62, 134, 106}));
    }

    private static void demo(Symmetric a) {
        System.out.println("A:");
        a.print();
        System.out.println("L:");
        a.choleskyLower().print();
    }

    static class Symmetric {
        private final int order;
        private final double[] ele;

        Symmetric(int order, double[] ele) {
            this.order = order;
            this.ele = ele;
        }

        void print() {
            final String eleFmt = "%10.5f ";
            int row = 1;
            int diag = 0;
            for (int i = 0; i < ele.length; i++) {
                System.out.printf(eleFmt, ele[i]);
                if (i == diag) {
                    for (int j = diag + row, col = row; col < order; j += col) {
                        System.out.printf(eleFmt, ele[j]);
                        col++;
                    }
                    System.out.println();
                    row++;
                    diag += row;
                }
            }
        }

        Lower choleskyLower() {
            Lower l = new Lower(order, new double[ele.length]);
            int row = 1;
            int col = 1;
            int dr = 0; // index of diagonal element at end of row
            int dc = 0; // index of diagonal element at top of column
            for (int i = 0; i < ele.length; i++) {
                if (i < dr) {
                    double d = (ele[i] - l.ele[i]) / l.ele[dc];
                    l.ele[i] = d;
                    int ci = col;
                    int cx = dc;
                    for (int j = i + 1; j <= dr; j++) {
                        cx += ci;
                        ci++;
                        l.ele[j] += d * l.ele[cx];
                    }
                    col++;
                    dc += col;
                } else {
                    l.ele[i] = Math.sqrt(ele[i] - l.ele[i]);
                    row++;
                    dr += row;
                    col = 1;
                    dc = 0;
                }
            }
            return l;
        }
    }

    static class Lower {
        private final int order;

