class Manager:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        n = len(points)

        def dist(i, j):
            return abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])

        dists = [[dist(i, j) for j in range(n)] for i in range(n)]
        cost = 0
        seen = [0]
        seenSet = {0}
        while len(seen) < n:
            new = float('inf')
            idx = -1
            for i in seen:
                for j in range(n):
                    if j not in seenSet and dists[i][j] < new:
                        new = dists[i][j]
                        idx = j
            cost += new
            seen.append(idx)
            seenSet.add(idx)
        return cost
