public class Jboss7DockerLiveTest extends AbstractDockerLiveTest {

    private String warUrl = "https://example.com/hello-world.war";
    private JBoss7Server server;
    private String url;

    @Override
    protected void doTest(Location loc) throws Exception {
        // Create and configure JBoss 7 server entity
        server = app.createAndManageChild(EntitySpec.create(JBoss7Server.class)
                .configure("war", warUrl)
                .configure("docker.image", "jboss/wildfly:7.0.0.Final"));

        // Start the server in the specified location
        app.start(ImmutableList.of(loc));

        // Get the server's base URL
        url = server.getAttribute(JBoss7Server.ROOT_URL);

        // Verify the server is accessible and returns the expected content
        assertHttpStatusCodeEventuallyEquals(url, 200);
        assertContentContainsText(url, "Hello, World!");

        // Monitor server metrics
        succeedsEventually(() -> {
            Integer requestCount = server.getAttribute(JBoss7Server.REQUEST_COUNT);
            Integer errorCount = server.getAttribute(JBoss7Server.ERROR_COUNT);
            Long processingTime = server.getAttribute(JBoss7Server.PROCESSING_TIME);

            Asserts.assertNotNull(requestCount, "Request count should not be null");
            Asserts.assertNotNull(errorCount, "Error count should not be null");
            Asserts.assertNotNull(processingTime, "Processing time should not be null");
        });
    }

