        // Dummy test method to ensure compatibility with testing frameworks
    }

    private void assertHttpStatusCodeEventuallyEquals(String url, int statusCode) {
        HttpTestUtils.assertHttpStatusCodeEventuallyEquals(url, statusCode);
    }

    private void assertContentContainsText(String url, String text) {
        HttpTestUtils.assertContentContainsText(url, text);
    }

    private void succeedsEventually(Runnable runnable) {
        Asserts.succeedsEventually(runnable);
    }
}

