/**
 * Represents a script data source. Script data source is one that is defined in
 * JavaScript. The application is responsible for implementing two operations:
 * <ul>
 * <li>Open: connect to the external system. Report an error if the connection
 * fails.
 * <li>Close: drop the connection to the external system.
 * </ul>
 *
 *
 * @see org.eclipse.birt.report.model.elements.ScriptDataSource
 */

public class ScriptDataSourceHandle extends DataSourceHandle
        implements
            IScriptDataSourceModel
{

    /**
     * Constructs a handle for script data source.
     *
     * @param module
     *            the module
     * @param element
     *            the script data source element
     */

    public ScriptDataSourceHandle( Module module, DesignElement element )
    {
        super( module, element );
    }

    /**
     * Sets the script for opening data connection.
     *
     * @param value
     *            the script to set.
     * @throws SemanticException
     *             if the property is locked.
     */

    public void setOpen( String value ) throws SemanticException
    {
        setProperty( IScriptDataSourceModel.OPEN_METHOD, value );
    }

    /**
     * Returns the script name for opening data connection.
     *
     * @return the script name for opening data connection.
     */

    public String getOpen( )
    {
        return getStringProperty( IScriptDataSourceModel.OPEN_METHOD );
    }

    /**
     * Sets the script name for closing data connection.
     *
     * @param value
     *            the script name to set.
     * @throws SemanticException
     *             if the property is locked.
     */

    public void setClose( String value ) throws SemanticException
    {
        setProperty( IScriptDataSourceModel.CLOSE_METHOD, value );
    }

    /**
     * Returns the script name for closing data connection.
     *
     * @return the script name for closing data connection.
     */

    public String getClose( )
    {
        return getStringProperty( IScriptDataSourceModel.CLOSE_METHOD );
    }

}

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import com.ibm.ws.lars.rest.model.Asset;
import com.ibm.ws.lars.rest.model.AssetList;

public class TestUtils {

    public static byte[] slurp(InputStream is) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int length;
        while ((length = is.read(buffer)) != -1) {
            baos.write(buffer, 0, length);
        }
        return baos.toByteArray();
    }

    public static void assertAssetList(AssetList list, Asset... assets) {
        Map<String, Asset> assetIdMap = new HashMap<>();
        for (Asset asset : assets) {
            assetIdMap.put(asset.getId(), asset);
        }

        for (Asset asset : list) {
            Asset expectedAsset = assetIdMap.remove(asset.getId());
            if (expectedAsset == null) {
                throw new AssertionError("Unexpected asset found: " + asset.toJson());
            }
            if (!expectedAsset.equals(asset)) {
                throw new AssertionError("Asset mismatch: expected " + expectedAsset.toJson() + ", but got " + asset.toJson());
            }
        }

        if (!assetIdMap.isEmpty()) {
            StringBuilder message = new StringBuilder("Missing assets: ");
            for (Asset asset : assetIdMap.values()) {
                message.append(asset.toJson()).append(" ");
            }
            throw new AssertionError(message.toString());
        }
    }
}

public static <T extends SequenceElement> void writeWordVectors(WeightLookupTable<T> lookupTable, OutputStream stream) throws IOException {
    // Get the word vectors from the lookupTable
    List<Vector> wordVectors = lookupTable.getWordVectors();

    // Create a PrintWriter to write to the OutputStream
    PrintWriter writer = new PrintWriter(stream);

    // Write each word vector to the OutputStream
    for (Vector vector : wordVectors) {
        writer.println(vector);
    }

    // Don't forget to flush and close the writer
    writer.flush();
    writer.close();
}

public class Sum35 {
    public static void main(String[] args) {
        int n = 1000;
        System.out.println("For n = " + n + " -> " + sum35c(n));
        for (int p = 1; p <= 7; p++) {
            n = (int) Math.pow(10, p);
            System.out.println("For n = " + n + " -> " + sum35c(n));
        }
        n = (int) Math.pow(10, 20);
        System.out.println("\nFor n = " + n + " -> " + sum35c(n));
    }
    public static int sum35a(int n) {
        int sum = 0;
        for (int i = 0; i < n; i++) {
            if (i % 3 == 0 || i % 5 == 0) {
                sum += i;
            }
        }
        return sum;
    }
    public static int sum35b(int n) {
        int sum = 0;
        for (int i = 3; i < n; i += 3) {
            sum += i;
        }
        for (int i = 5; i < n; i += 5) {
            sum += i;
        }
        for (int i = 15; i < n; i += 15) {
            sum -= i;
        }
        return sum;
    }
    public static int sum35c(int n) {
        int[] consts = {3, 5, 15};
        int[] divs = new int[3];
        int[] sums = new int[3];
        for (int i = 0; i < 3; i++) {
            divs[i] = (n - 1) / consts[i];
            sums[i] = divs[i] * consts[i] * (1 + divs[i]) / 2;
        }
        return sums[0] + sums[1] - sums[2];
    }
}

