/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Product {
    public List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        Queue<Integer> queue1 = new LinkedList<>(), queue2 = new LinkedList<>();
        _getAllElements(root1, queue1);
        _getAllElements(root2, queue2);
        List<Integer> res = new LinkedList<>();
        while(!queue1.isEmpty() && !queue2.isEmpty()) {
            if (queue1.peek() < queue2.peek()) {
                res.add(queue1.poll());
            } else {
                res.add(queue2.poll());
            }
        }
        res.addAll(queue1);
        res.addAll(queue2);
        return res;
    }

    private void _getAllElements(TreeNode root, Queue<Integer> queue) {
        if (root == null) return;
        _getAllElements(root.left, queue);
        queue.offer(root.val);
        _getAllElements(root.right, queue);
    }

}

import javafx.application.Application;
import javafx.geometry.Point2D;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.text.Font;
