public class Library extends Application {
    static String[] message = new String[]{"W", "E", "L", "C", "O", "M", "E", " ", "T", "O", " ", "J", "A", "V", "A"};
    static Font font = Font.font("Times New Roman", FontWeight.BOLD, 28);

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage primaryStage) throws Exception {
        Pane pane = new Pane();
        double radius = 75;
        for (int i = 0, currentAngle = 0, rotation = 90; i < message.length; i++, currentAngle += 22, rotation += 22) {
            double x = 105 + radius * Math.cos(Math.toRadians(currentAngle));
            double y = 105 + radius * Math.sin(Math.toRadians(currentAngle));
            Text text = new Text(x, y, message[i]);
            text.setFont(font);
            text.setRotate(rotation);
            pane.getChildren().add(text);

        }
        Scene scene = new Scene(pane, 225, 225);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();
    }

}

import javax.swing.*;
import java.awt.*;

/**
 * Grafiksel Hanoi Kuleleri gosterimi: cubuklar ve diskler JPanel
 * bilesenleriyle temsil edilir, cozum rekursif algoritma ile
 * adim adim animasyona donusturulur.
 */
public class HanoiKuleleri extends JFrame {

    private static final long serialVersionUID = 1L;
    private static final int FRAME_GENISLIK = 600;
    private static final int FRAME_YUKSEKLIK = 400;

    private static final int DIREK_GENISLIK = 100;
    private static final int DIREK_YUKSEKLIK = 300;

    private static final int KATMAN_YUKSEKLIK = 20;
    private static final int TOPLAM_DISK = 4;
    private static final int TOPLAM_DIREK = 3;

    private final int[] direkDoluluk = new int[TOPLAM_DIREK];
    private final JPanel[] direkler = new JPanel[TOPLAM_DIREK];
    private final JPanel[] diskKatmanlari = new JPanel[TOPLAM_DISK];

    public HanoiKuleleri() {
        direkleriHazirla();
        diskleriHazirla();
        ilkDirekeDiskleriYerlestir();

        JPanel govdePaneli = new JPanel(new FlowLayout(FlowLayout.CENTER, 10, 10));
        for (JPanel direk : direkler) {
            govdePaneli.add(direk);
        }

        setTitle("Tower of Hanoi");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(FRAME_GENISLIK, FRAME_YUKSEKLIK);
        setLocationRelativeTo(null);
        setResizable(false);
        add(govdePaneli);
    }

    private void direkleriHazirla() {
        for (int i = 0; i < TOPLAM_DIREK; i++) {
            direkler[i] = new JPanel();
            direkler[i].setPreferredSize(new Dimension(DIREK_GENISLIK, DIREK_YUKSEKLIK));
            direkler[i].setBackground(new Color(144, 238, 144));
        }
    }

    private void diskleriHazirla() {
        for (int i = 0; i < TOPLAM_DISK; i++) {
            int genislik = (TOPLAM_DISK - i + 1) * KATMAN_YUKSEKLIK;
            diskKatmanlari[i] = new JPanel();
            diskKatmanlari[i].setPreferredSize(new Dimension(genislik, KATMAN_YUKSEKLIK));
            diskKatmanlari[i].setBackground(Color.RED);
        }
    }

    private void ilkDirekeDiskleriYerlestir() {
        direkDoluluk[0] = TOPLAM_DISK;
        for (int i = 0; i < TOPLAM_DISK; i++) {
            direkler[0].add(diskKatmanlari[i]);
        }
    }

    /** Bir diregin en ustundeki diski baska bir direge tasir ve ekrani gunceller. */
    public void diskTasi(int kaynakDirek, int hedefDirek) {
        JPanel tasinanDisk = (JPanel) direkler[kaynakDirek].getComponent(--direkDoluluk[kaynakDirek]);
        direkler[kaynakDirek].remove(tasinanDisk);

import java.util.*;

import java.io.*;

public class Timer {

    static ContestScanner sc = new ContestScanner(System.in);

    static PrintWriter pw = new PrintWriter(System.out);

    static StringBuilder sb = new StringBuilder();

    static long mod = (long) 1e9 + 7;

    public static void main(String[] args) throws Exception {

        //int T = sc.nextInt();

        //for(int i = 0; i < T; i++)solve();

        solve();

        pw.flush();

    }

    public static void solve() {

        int N = sc.nextInt();

        int[] a = sc.nextIntArray(N);

        int[] ans = new int[N];

        int prev = 0;

        for(int i = 0; i < N; i++){

            if(a[i] > prev){

                ans[i] = prev;

            }else{

                ans[i] = -1;

            }

            prev = a[i];

        }

        Deque<Integer> dq = new ArrayDeque<Integer>();

        for(int i = N-1; i >= 0; i--){

            if(ans[i] != -1){

                for(int j = ans[i]+1; j < a[i]; j++){

                    dq.add(j);

                }

            }else{

                if(dq.size() > 0){

                    ans[i] = dq.poll();

                }else{

                    ans[i] = (int)1e6;

                }

            }

        }

        for(int v : ans) sb.append(v).append(" ");

        pw.println(dq.size() == 0 ? sb.toString().trim() : -1);

    }

    static class GeekInteger {

        public static void save_sort(int[] array) {

            shuffle(array);

            Arrays.sort(array);

        }

        public static int[] shuffle(int[] array) {

            int n = array.length;

            Random random = new Random();

            for (int i = 0, j; i < n; i++) {

                j = i + random.nextInt(n - i);

                int randomElement = array[j];

                array[j] = array[i];

                array[i] = randomElement;

            }

            return array;

        }

        public static void save_sort(long[] array) {

            shuffle(array);

            Arrays.sort(array);

        }

        public static long[] shuffle(long[] array) {

            int n = array.length;

            Random random = new Random();

            for (int i = 0, j; i < n; i++) {

                j = i + random.nextInt(n - i);

                long randomElement = array[j];

                array[j] = array[i];

                array[i] = randomElement;

            }

            return array;

        }

    }

}

