class Handler {
    public int numDifferentIntegers(String word) {
        Set<String> set = new HashSet<String>();

        word = "a" + word + "a";
        char[] a = word.toCharArray();
        int index = 0;
        for (int i = 0; i < word.length(); i++) {
            if (a[i] > '9' || a[i] < '0') {
                if (i > index + 1) {
                    String key = word.substring(index + 1, i);

                    int j = 0;
                    for (j = 0; j < key.length(); j++) {
                        if (key.charAt(j) != '0') {
                            break;
                        }
                    }
                    if (j == key.length()) {
                        key = "0";
                    } else {
                        key = key.substring(j);
                    }
                    set.add(key);
                }

                index = i;
            }
        }

        return set.size();
    }
}

import javax.jcr.RepositoryException;

public class Session {
    private List<Lock> locks = new ArrayList<>();

    public void cleanLocks() throws RepositoryException {
        for (Lock lock : locks) {
            if (lock.isLive()) {
                lock.unlock();
            } else {
                throw new RepositoryException("Session is not live");
            }
        }
    }
}

