import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class DateConverter {

    public static String convertDateString(String date) throws ParseException {
        SimpleDateFormat inputFormat = new SimpleDateFormat("d''th'' MMMM yyyy", Locale.ENGLISH);
        SimpleDateFormat outputFormat = new SimpleDateFormat("yyyy-MM-dd");
        Date parsedDate = inputFormat.parse(date);
        return outputFormat.format(parsedDate);
    }

    public static void main(String[] args) {
        try {
            System.out.println(convertDateString("20th Oct 2052"));
            System.out.println(convertDateString("6th Jun 1933"));
            System.out.println(convertDateString("26th May 1960"));
        } catch (ParseException e) {
            e.printStackTrace();
        }
    }
}

