            return;
        }
        response.setContentType(MediaType.TEXT_PLAIN_VALUE);
        response.getWriter().write(TEST_RESPONSE);
    }

    private boolean isExcludedVersion(String apiVersion) {
        return EXCLUDED_VERSION.equalsIgnoreCase(apiVersion);
