private static String removeSlashes(String path) {
    if (path.isEmpty()) {
        return path;
    }

    int beginIndex = 0;
    int endIndex = path.length() - 1;

    while (beginIndex < path.length() && path.charAt(beginIndex) == '/') {
        beginIndex++;
    }

    while (endIndex >= 0 && path.charAt(endIndex) == '/') {
        endIndex--;
    }

    return path.substring(beginIndex, endIndex + 1);
}

