import java.util.List;
import org.graalvm.compiler.graph.NodeClass;
import jdk.vm.ci.meta.Assumptions;
import jdk.vm.ci.meta.ResolvedJavaMethod;

public final class EncodedGraph {
    private final byte[] encoding;
    private final Object[] objects;
    private final NodeClass<?>[] nodeClasses;
    private final long[] nodeStartOffsets;
    private final Assumptions assumptions;
    private final List<ResolvedJavaMethod> inlinedMethods;
    private final int startOffset;

    public EncodedGraph(
        byte[] encoding,
        Object[] objects,
        NodeClass<?>[] nodeClasses,
        long[] nodeStartOffsets,
        Assumptions assumptions,
        List<ResolvedJavaMethod> inlinedMethods,
        int startOffset
    ) {
        this.encoding = encoding;
        this.objects = objects;
        this.nodeClasses = nodeClasses;
        this.nodeStartOffsets = nodeStartOffsets;
        this.assumptions = assumptions;
        this.inlinedMethods = inlinedMethods;
        this.startOffset = startOffset;
    }

    public byte[] getEncoding() {
        return encoding;
    }

    public int getStartOffset() {
        return startOffset;
    }

    public Object[] getObjects() {
        return objects;
    }

    public NodeClass<?>[] getNodeClasses() {
        return nodeClasses;
    }

    public Assumptions getAssumptions() {
        return assumptions;
    }

    public List<ResolvedJavaMethod> getInlinedMethods() {
        return inlinedMethods;
    }

    public long getNodeStartOffset(int index) {
        return nodeStartOffsets[index];
    }

    public int getNodeClassIndex(int nodeOffset) {
        int classIndex = 0;
        for (int i = 0; i < nodeStartOffsets.length; i++) {
            if (nodeStartOffsets[i] <= nodeOffset) {
                classIndex = i;
            }
        }
        return classIndex;
    }

    public Object getObject(int objectIndex) {
        return objects[objectIndex];
    }

    public boolean hasObjects() {
        return objects != null && objects.length > 0;
    }

    public boolean hasNodeClasses() {
        return nodeClasses != null && nodeClasses.length > 0;
    }

    public boolean hasInlinedMethods() {
        return inlinedMethods != null && !inlinedMethods.isEmpty();
    }

    public int getEncodingLength() {
        return encoding != null ? encoding.length : 0;
    }

    public int getNodesCount() {
        return nodeStartOffsets != null ? nodeStartOffsets.length : 0;
    }
}

import java.math.BigInteger;

public class DivisibleByFiveOrSix {
    public static void main(String[] args) {
        BigInteger maxLong = BigInteger.valueOf(Long.MAX_VALUE);
        BigInteger number = maxLong.add(BigInteger.ONE); // Start with the number after Long.MAX_VALUE

        int count = 0;
        while (count < 10) {
            if (number.remainder(BigInteger.valueOf(5)).equals(BigInteger.ZERO)
                    || number.remainder(BigInteger.valueOf(6)).equals(BigInteger.ZERO)) {
                System.out.println(number);
                count++;
            }
            number = number.add(BigInteger.ONE);
        }
    }
}

