public class ZipOutputFileProvider implements Closeable {
    private static final long STABLE_TIMESTAMP = 315532800000L; // Jan 1, 1980
    private static final int BUFFER_SIZE = 8192;

    private final ZipOutputStream zipOutputStream;
    private final CRC32 checksumCalculator;
    private final byte[] transferBuffer;

    public ZipOutputFileProvider(Path outputZipPath) throws IOException {
        Preconditions.checkNotNull(outputZipPath, "Output ZIP path cannot be null");
        this.transferBuffer = new byte[BUFFER_SIZE];
        this.checksumCalculator = new CRC32();
        this.zipOutputStream = new ZipOutputStream(
            new BufferedOutputStream(Files.newOutputStream(outputZipPath))
        );
    }

    public void writeStoredEntry(String entryName, byte[] content) throws IOException {
        validateFileType(entryName);
        ZipEntry entry = createZipEntry(entryName);
        entry.setMethod(ZipEntry.STORED);

        checksumCalculator.reset();
        checksumCalculator.update(content);

        entry.setSize(content.length);
        entry.setCrc(checksumCalculator.getValue());

        zipOutputStream.putNextEntry(entry);
        zipOutputStream.write(content);
        zipOutputStream.closeEntry();
    }

    public void copyFrom(Path inputPath, String entryName) throws IOException {
        validateFileType(entryName);
        try (InputStream inputStream = Files.newInputStream(inputPath)) {
            ZipEntry entry = createZipEntry(entryName);
            entry.setMethod(ZipEntry.STORED);

            long size = Files.size(inputPath);
            entry.setSize(size);

            checksumCalculator.reset();
            long computedCrc = computeCrc32(inputStream, size);
            entry.setCrc(computedCrc);

            zipOutputStream.putNextEntry(entry);
            Files.copy(inputPath, zipOutputStream);
            zipOutputStream.closeEntry();
        }
    }

    private long computeCrc32(InputStream inputStream, long size) throws IOException {
