import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoClients;
import com.mongodb.client.MongoCollection;
import com.mongodb.client.MongoCursor;
import com.mongodb.client.MongoDatabase;
import org.bson.Document;
import org.springframework.stereotype.Repository;

import java.util.ArrayList;
import java.util.List;

@Repository
public class AuditLogLoadMongoRepository implements AuditLogLoadRepository {

    private static final String DB_NAME = "audit_db";
    private static final String COLLECTION_NAME = "audit_logs";

    @Override
    public long count() {
        try (MongoClient mongoClient = MongoClients.create()) {
            MongoDatabase database = mongoClient.getDatabase(DB_NAME);
            MongoCollection<Document> collection = database.getCollection(COLLECTION_NAME);
            return collection.countDocuments();
        }
    }

    @Override
    public List<AuditLog> fetchPage(int start, int length) {
        List<AuditLog> auditLogs = new ArrayList<>();
        try (MongoClient mongoClient = MongoClients.create()) {
            MongoDatabase database = mongoClient.getDatabase(DB_NAME);
            MongoCollection<Document> collection = database.getCollection(COLLECTION_NAME);

            MongoCursor<Document> cursor = collection.find().skip(start).limit(length).iterator();

            try {
                while (cursor.hasNext()) {
                    Document document = cursor.next();
                    AuditLog auditLog = convertDocumentToAuditLog(document);
                    auditLogs.add(auditLog);
                }
            } finally {
                cursor.close();
            }
        }
        return auditLogs;
    }

    private AuditLog convertDocumentToAuditLog(Document document) {
        AuditLog auditLog = new AuditLog();
        auditLog.setId(document.getObjectId("_id").toHexString());
        auditLog.setTimestamp(document.getDate("timestamp"));
        auditLog.setUser(document.getString("user"));
        auditLog.setAction(document.getString("action"));
        auditLog.setDetails(document.getString("details"));

        return auditLog;
    }
}

/**
 * Complete the 'stringForceTimes' function below.
 *
 * The function is expected to return an INTEGER.
 * The function takes in the following parameters:
 *  1. STRING s
 *  2. INTEGER n
 *  3. INTEGER k
 *
 * maxSubstr
 * {
 * @param s
 * @param k
 * @param n
 * @return
 * }
 *
 */
public static int stringForceTimes(String s, int n, int k) {
    int minFreq= Integer.MAX_VALUE;
    int maxFreq=0;
    int consecutiveChars=1;

    int[] arrCharFrequency=new int[k];
    for(int i=0;i<n;i++){
        if(s.charAt(i)!='?'){
            arrCharFrequency[s.charAt(i)-'a']++;
        }
        if(s.charAt(i)=='?' && consecutiveChars>1){
            consecutiveChars--;
        }
        else if(s.charAt(i)=='?'){
            consecutiveChars++;
        }
        minFreq=Math.min(minFreq,arrCharFrequency[s.charAt(i)-'a']);
        maxFreq=Math.max(maxFreq,arrCharFrequency[s.charAt(i)-'a');
    }

    return min(minFreq,consecutiveChars);
}
