class Runner {
    public int minOperations(int[] nums, int[] numsDivide) {
        int gcd = numsDivide[0];
        for (int i : numsDivide) {
            gcd = gcd(gcd, i);
        }

        Arrays.sort(nums);
        for (int i = 0; i < nums.length; i++) {
            if (gcd % nums[i] == 0) {
                return i;
            }
        }
        return -1;
    }

    private int gcd(int a ,int b) {
        if (a < b) {
            return gcd(b,a);
        }
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

