        for (int i = 0; i < nums.size(); i++)
            count[nums[i]]++;
        int res = 0;
        for (int i = 0; i < count.size(); ++i) {
            if (count[i]) {
                int cnt = 0, que = count[i], sum = count[i] * i;
                for (int j = i + 1; que > k && j < count.size(); j++) {
                    que -= count[j];
                    sum -= j * count[j];
                    cnt += que / k;
                    res = max(res, cnt + i - j);
                    i = j - 1;
                }
            }
        }
        return res;
    }
};
