class Shape {
      public int merge2Stones(int[] stones, int K) {
        int[] psums = new int[stones.length + 1];
        for (int i = 0; i <= stones.length; i++) {
            if (i != 0) psums[i] = psums[i - 1] + stones[i - 1];
        }
        int[][] minCost = new int[psums.length][psums.length];
        for (int j = 1; j < psums.length; j++) {
            for (int i = j - 1; i >= 0; i--) {
                if (i == j - 1) minCost[i][j] = 0;
                else {
                    minCost[i][j] = Integer.MAX_VALUE;
                    for (int k = i + 1; k < j; k++) {
                        int subcost = minCost[i][k] + minCost[k][j] + psums[j] - psums[i];
                        minCost[i][j] = Math.min(minCost[i][j], subcost);
                    }
                }
            }
        }
        return minCost[0][psums.length - 1];
    }

    HashMap<List<Integer>, Integer> paths;

    public int mergeStones(int[] stones, int K) {
        int len = stones.length;
        if ((len - 1) % (K - 1) != 0) {
            return -1;
        }
        if (K == 2) {
            return merge2Stones(stones, K);
        }

        LinkedList<Integer> stl = new LinkedList<>();
        for (int s : stones) {
            stl.add(s);
        }
        paths = new HashMap<>();
        return dfs(stl, K);
    }

    int dfs(LinkedList<Integer> stones, int K) {
        if (paths.containsKey(stones)) {
            return paths.get(stones);
        }
        if (stones.size() == 1) {
            return 0;
        }
        int cost = 5000000;
        for (int i = 0; i <= stones.size() - K && i <= 2 * K; i++) {
            LinkedList<Integer> sublist = new LinkedList<>();
            sublist.addAll(stones);
            int sum = 0;
            for (int j = 0; j < K; j++) {
                sum += sublist.remove(i);
            }
            sublist.add(i, sum);
            if (sum < cost) {
                cost = Math.min(sum + dfs(sublist, K), cost);
            }
        }
//        pt(stones);
//        pt(cost);
        paths.put(stones, cost);
        return cost;
    }
}

