        } catch (Exception e) {
            System.out.println("Invalid input for month.");
            System.exit(1);
        }
        switch (month) {
            case "Sep":
            case "Apr":
            case "Jun":
            case "Nov":
                days += "30";
                break;
            case "Jan":
            case "Mar":
            case "May":
            case "Jul":
            case "Aug":
            case "Oct":
            case "Dec":
                days += "31";
