                    if (nYear % 100 == 0) {
                        if (nYear % 400 == 0) {
                            days += "29";
                        } else {
                            days += "28";
                        }
                    } else {
                        days += "29";

                    }
                } else {
                    days += "28";
                }

        }
        System.out.println(month + " " + year + " has " + days + " days.");

    }

