class Matrix {

    int[][] dp;
    int m;
    int n;
    public void NumMatrix(int[][] matrix) {
        if (matrix.length == 0 || matrix[0].length == 0) {
            return;
        }
        m = matrix.length;
        n = matrix[0].length;
        dp = new int[m + 1][n + 1];
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = dp[i - 1][j] + matrix[i - 1][j - 1] + dp[i][j - 1] - dp[i - 1][j - 1];
            }
        }
    }
    public int sumRegion(int row1, int col1, int row2, int col2) {
        return dp[row2 + 1][col2 + 1] - dp[row2 + 1][col1] - dp[row1][col2 + 1] + dp[row1][col1];
    }
    public int maxSideLength(int[][] mat, int threshold) {
        NumMatrix(mat);
        for (int side = Math.min(m, n); side >= 1; side--) {
            for (int i = 0; i + side - 1 < m; i++) {
                for (int j = 0; j + side - 1 < n; j++) {
                    if (sumRegion(i, j, i + side - 1, j + side - 1) <= threshold) {
                        System.out.println(i + "," + j + "," + side);
                        return side;
                    }
                }
            }
        }
        return 0;
    }
}

private boolean estimateMotion() {
        modelFitData.reset();
        Point2D_F64 normLeft = new Point2D_F64();
        Point2D_F64 normRight = new Point2D_F64();

        for( int i = 0; i < quadViews.size; i++ ) {
            QuadView obs = quadViews.get(i);

            leftImageToNorm.compute(obs.v0.x,obs.v0.y,normLeft);
            rightImageToNorm.compute(obs.v1.x,obs.v1.y,normRight);

            triangulate.triangulate(normLeft,normRight,leftToRight,obs.X);

            if( !Double.isInfinite(obs.X.normSq()) ) {
                Stereo2D3D data = modelFitData.grow();
                leftImageToNorm.compute(obs.v2.x,obs.v2.y,data.leftObs);
                rightImageToNorm.compute(obs.v3.x,obs.v3.y,data.rightObs);
                data.location.set(obs.X);
            }
        }

        if( !matcher.process(modelFitData.toList()) )
            return false;
        Se3_F64 oldToNew = matcher.getModelParameters();

        if( modelRefiner != null ) {
            Se3_F64 found = new Se3_F64();
            if( modelRefiner.fitModel(matcher.getMatchSet(), oldToNew, found) ) {

                found.invert(newToOld);
            } else {
                oldToNew.invert(newToOld);

            }
        } else {
            oldToNew.invert(newToOld);
        }

        Se3_F64 temp = new Se3_F64();
        newToOld.concat(leftCamToWorld, temp);
        leftCamToWorld.set(temp);
        return true;
    }

import java.io.IOException;
import java.nio.file.FileSystem;
import java.nio.file.FileSystems;
import java.nio.file.Path;

public class TempFileSystemManager {
    public static FileSystemHandle createAndMountTempFileSystem(Path mountPoint, TempFileProvider tempFileProvider)
            throws IOException {
        FileSystem fileSystem = FileSystems.newFileSystem(tempFileProvider.getTempFile().toPath(), null);
        Path mountPath = mountPoint.toAbsolutePath();

        try {
            fileSystem.provider().checkAccess(mountPath);
        } catch (IOException e) {
            throw new IOException("Mount point not accessible: " + mountPath, e);
        }

        fileSystem.provider().mount(fileSystem, mountPath, null);

        return new FileSystemHandle(fileSystem, mountPath);
    }

    public static class FileSystemHandle implements AutoCloseable {
        private final FileSystem fileSystem;
        private final Path mountPath;

        public FileSystemHandle(FileSystem fileSystem, Path mountPath) {
            this.fileSystem = fileSystem;
            this.mountPath = mountPath;
        }

        @Override
        public void close() throws Exception {
            fileSystem.provider().unmount(mountPath);
            fileSystem.close();
        }
    }
}

