public:
    bool equationsPossible(vector<string>& equations) {
        int parent[26] = {0}, rank[26] = {0};
        for (int i = 0; i < 26; i++){
            parent[i] = i;
        }
        for (auto i : equations){
            if (i[1] == '='){
                if (find(parent, i[0] - 'a') == find(parent, i[3] - 'a')){
                    continue;
                }
                parent[find(parent, i[3] - 'a')] = parent[find(parent, i[0] - 'a')];
            }
        }
        for (auto i : equations){
            if (i[1] == '!'){
                if (find(parent, i[0] - 'a') == find(parent, i[3] - 'a')){
                    return false;
                }
            }
        }
        return true;
    }
    private:
    int find(int parent[], int a){
        if (parent[a] == a){
            return a;
        }
        return find(parent, parent[a]);
    }
