public static void updateChunkChecksum( byte[] buf, int checksumOff, int dataOff, int dataLen, DataChecksum checksum ) throws IOException {
    // Calculate the checksum for the data
    checksum.reset();
    checksum.update(buf, dataOff, dataLen);
    byte[] checksumBytes = checksum.digest();

    // Write the checksum to the buffer at the specified offset
    System.arraycopy(checksumBytes, 0, buf, checksumOff, checksumBytes.length);
