import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
 
public class Huffman {
 
    public static void main(String[] args) {
        String text = "this is an example for huffman encoding";
 
        Map<Character, Integer> frequencies = new HashMap<>();
        for (char ch : text.toCharArray()) {
            frequencies.put(ch, frequencies.getOrDefault(ch, 0) + 1);
        }
 
        PriorityQueue<Node> prioritizedFrequencies = new PriorityQueue<>(Comparator.comparingInt(o -> o.frequency));
        for (Map.Entry<Character, Integer> countedChar : frequencies.entrySet()) {
            prioritizedFrequencies.add(new Node(countedChar.getValue(), new Leaf(countedChar.getKey())));
        }
 
        while (prioritizedFrequencies.size() > 1) {
            Node leftChild = prioritizedFrequencies.poll();
            Node rightChild = prioritizedFrequencies.poll();
            prioritizedFrequencies.add(new Node(rightChild.frequency + leftChild.frequency, new Internal(leftChild, rightChild)));
        }
 
        Map<Character, List<Integer>> codes = new HashMap<>();
        generateCodes(prioritizedFrequencies.peek(), new ArrayList<>(), codes);
 
        for (Map.Entry<Character, List<Integer>> item : codes.entrySet()) {
            System.out.print(item.getKey() + ": ");
            for (Integer bit : item.getValue()) {
                System.out.print(bit);
            }
            System.out.println();
        }
    }
 
    private static void generateCodes(Node node, List<Integer> prefix, Map<Character, List<Integer>> outCodes) {
        if (node.kind instanceof Leaf) {
            outCodes.put(((Leaf) node.kind).ch, prefix);
        } else if (node.kind instanceof Internal) {
            List<Integer> leftPrefix = new ArrayList<>(prefix);
            leftPrefix.add(0);
            generateCodes(((Internal) node.kind).leftChild, leftPrefix, outCodes);
 
            List<Integer> rightPrefix = new ArrayList<>(prefix);
            rightPrefix.add(1);
            generateCodes(((Internal) node.kind).rightChild, rightPrefix, outCodes);
        }
    }
 
    private static class Node {
        private final int frequency;
        private final Kind kind;
 
        private Node(int frequency, Kind kind) {
            this.frequency = frequency;
            this.kind = kind;
        }
    }
 
    private static abstract class Kind {
    }
 
    private static class Leaf extends Kind {
        private final char ch;

public <T> void put(Key<T> key, T value) {
    Preconditions.checkNotNull(key, "key");
    Preconditions.checkNotNull(value, "value");
    maybeExpand();
    name(size, key.asciiName());
    value(size, key.toBytes(value));
    size++;
  }

import java.io.File;
import java.rmi.RemoteException;
import java.util.Properties;

import org.apache.geode.test.dunit.internal.BounceResult;

/**
 * This class provides an abstraction over the environment that is used to run dunit. This will
 * delegate to the hydra or to the standalone dunit launcher as needed.
 *
 * <p>
 * Any dunit tests that rely on hydra configuration should go through here, so that we can separate
 * them out from depending on hydra and run them on a different VM launching system.
 */
public abstract class DUnitEnv {

  private static DUnitEnv instance = null;

  public static DUnitEnv get() {
    if (instance == null) {
      try {
        // for tests that are still being migrated to the open-source
        // distributed unit test framework we need to look for this
        // old closed-source dunit environment
        Class clazz = Class.forName("dunit.hydra.HydraDUnitEnv");
        instance = (DUnitEnv) clazz.newInstance();
      } catch (Exception e) {
        throw new Error("Distributed unit test environment is not initialized");
      }
    }
    return instance;
  }

  public static void set(DUnitEnv dunitEnv) {
    instance = dunitEnv;
  }

  public abstract String getLocatorString();

  public abstract String getLocatorAddress();

  public abstract int getLocatorPort();

  public abstract Properties getDistributedSystemProperties();

  public abstract int getPid();

  public abstract int getVMID();

  public abstract BounceResult bounce(String version, int pid, boolean force)
      throws RemoteException;

  public abstract File getWorkingDirectory(int pid);

  public abstract File getWorkingDirectory(String version, int pid);

}

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;

import javax.xml.transform.stream.StreamResult;

import org.jpedal.examples.simpleviewer.SimpleViewer;
import org.xml.sax.ContentHandler;

import au.gov.naa.digipres.xena.kernel.XenaException;
import au.gov.naa.digipres.xena.kernel.view.XenaView;
import au.gov.naa.digipres.xena.util.BinaryDeNormaliser;

/**
 * View for PDF files.
 *
 */
public class PdfView extends XenaView {
    public static final String PDFVIEW_VIEW_NAME = "PDF Viewer";
    private static final long serialVersionUID = 1L;
    private SimpleViewer simpleViewer;
    private File pdfFile;

    public PdfView() {
    }

    @Override
    public boolean canShowTag(String tag) throws XenaException {
        return tag.equals(viewManager.getPluginManager().getTypeManager().lookupXenaFileType(XenaPdfFileType.class).getTag());
    }

    @Override
    public String getViewName() {
        return PDFVIEW_VIEW_NAME;
    }

    @Override
    public ContentHandler getContentHandler() throws XenaException {

        FileOutputStream xenaTempOS = null;
        try {
            pdfFile = File.createTempFile("pdffile", ".pdf");
            pdfFile.deleteOnExit();
            xenaTempOS = new FileOutputStream(pdfFile);
        } catch (IOException e) {
            throw new XenaException("Problem creating temporary xena output file", e);
        }

        BinaryDeNormaliser base64Handler = new BinaryDeNormaliser() {
            /*
             * (non-Javadoc)
             * @see au.gov.naa.digipres.xena.kernel.normalise.AbstractDeNormaliser#endDocument()
             */
            @Override
            public void endDocument() {
                if (pdfFile.exists()) {
                    simpleViewer = new SimpleViewer();
                    simpleViewer.setRootContainer(PdfView.this);
                    simpleViewer.setupViewer();
                    simpleViewer.openDefaultFile(pdfFile.getAbsolutePath());
                }
            }
        };

        StreamResult result = new StreamResult(xenaTempOS);
        base64Handler.setResult(result);
        return base64Handler;
    }

    /*
     * (non-Javadoc)
     * @see au.gov.naa.digipres.xena.kernel.view.XenaView#doClose()
     */
    @Override
    public void doClose() {
        super.doClose();

    }

}

public static int[] merge(int[] list1, int[] list2) {
    int[] result = new int[list1.length + list2.length];
    int i = 0, j = 0, k = 0;
    while (i < list1.length && j < list2.length) {
        if (list1[i] < list2[j]) {
            result[k++] = list1[i++];
        } else {
            result[k++] = list2[j++];
        }
    }
    while (i < list1.length) {
        result[k++] = list1[i++];
    }
    while (j < list2.length) {
        result[k++] = list2[j++];
    }
    return result;
}
 import java.util.Scanner;

public class Matrix {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter list1: ");
        int n1 = input.nextInt();
        int[] list1 = new int[n1];
        for (int i = 0; i < n1; i++) {
            list1[i] = input.nextInt();
        }
        System.out.print("Enter list2: ");
        int n2 = input.nextInt();
        int[] list2 = new int[n2];
        for (int i = 0; i < n2; i++) {
            list2[i] = input.nextInt();
        }
        int[] mergedList = merge(list1, list2);
        System.out.print("The merged list is ");
        for (int i = 0; i < mergedList.length; i++) {
            System.out.print(mergedList[i] + " ");
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;

public class ArrayListShuffle {

    public static <E> void shuffle(ArrayList<E> list) {
        Collections.shuffle(list);
    }

    public static void main(String[] args) {
        ArrayList<Integer> numbers = new ArrayList<>();
        for (int i = 1; i <= 10; i++) {
            numbers.add(i);
        }
        System.out.println("Original list: " + numbers);
        shuffle(numbers);
        System.out.println("Shuffled list: " + numbers);
    }
}

